function captureScoreSnapshot() {
  return Object.fromEntries(scoreEditorEntries.map(([key, editor]) => [key, editor.value]));
}

function scoreSnapshotsEqual(first, second) {
  return scoreEditorEntries.every(([key]) => first?.[key] === second?.[key]);
}

function updateHistoryControls() {
  elements.undoButton.disabled = scoreHistory.undo.length === 0;
  elements.redoButton.disabled = scoreHistory.redo.length === 0;
}

function resetScoreHistory() {
  scoreHistory.undo = [];
  scoreHistory.redo = [];
  scoreHistory.current = captureScoreSnapshot();
  updateHistoryControls();
}

function recordScoreHistory() {
  if (scoreHistory.applying) return;
  const next = captureScoreSnapshot();
  if (!scoreHistory.current) {
    scoreHistory.current = next;
    updateHistoryControls();
    return;
  }
  if (scoreSnapshotsEqual(scoreHistory.current, next)) return;
  scoreHistory.undo.push(scoreHistory.current);
  scoreHistory.current = next;
  scoreHistory.redo = [];
  updateHistoryControls();
}

function applyScoreHistorySnapshot(snapshot) {
  if (!snapshot) return;
  scoreHistory.applying = true;
  scoreEditorEntries.forEach(([key, editor]) => { editor.value = snapshot[key] ?? ""; });
  scoreHistory.applying = false;
  scoreHistory.current = captureScoreSnapshot();
  handleScoreInput();
  const activeEditor = editorForMode(inputMode);
  activeEditor?.focus({ preventScroll: true });
}

function undoScoreEdit() {
  if (!scoreHistory.undo.length) return;
  scoreHistory.redo.push(scoreHistory.current);
  applyScoreHistorySnapshot(scoreHistory.undo.pop());
}

function redoScoreEdit() {
  if (!scoreHistory.redo.length) return;
  scoreHistory.undo.push(scoreHistory.current);
  applyScoreHistorySnapshot(scoreHistory.redo.pop());
}

function clearScoreContent() {
  const current = captureScoreSnapshot();
  if (Object.values(current).every((value) => !value)) {
    elements.jianpuScore.focus({ preventScroll: true });
    return;
  }
  if (!scoreHistory.current || !scoreSnapshotsEqual(scoreHistory.current, current)) scoreHistory.current = current;
  scoreHistory.undo.push(scoreHistory.current);
  scoreEditorEntries.forEach(([, editor]) => { editor.value = ""; });
  scoreHistory.current = captureScoreSnapshot();
  scoreHistory.redo = [];
  updateHistoryControls();
  finishRecording({ apply: false });
  stopPreview();
  lastMidiFile = null;
  resetMidiTrackPicker();
  activeAnalyticsScoreOrigin = "editor";
  activeAnalyticsScoreId = "";
  currentPublicScoreCode = "";
  updateLineNumbers();
  convert();
  editorForMode(inputMode)?.focus({ preventScroll: true });
}

function setSectionSidebarCollapsed(collapsed) {
  if (!elements.sectionSidebar || !elements.sectionSidebarToggle) return;
  const isCollapsed = Boolean(collapsed);
  elements.pageLayout?.setAttribute("data-sidebar-collapsed", String(isCollapsed));
  elements.sectionSidebar.dataset.collapsed = String(isCollapsed);
  elements.sectionSidebarToggle.setAttribute("aria-expanded", String(!isCollapsed));
  elements.sectionSidebarToggle.setAttribute("aria-label", isCollapsed ? "展开页面目录" : "折叠页面目录");
  elements.sectionSidebarToggle.title = isCollapsed ? "展开页面目录" : "折叠页面目录";
  elements.sectionSidebarToggle.textContent = isCollapsed ? "+" : "−";
  if (elements.sectionSidebarOpen) {
    elements.sectionSidebarOpen.hidden = !isCollapsed;
    elements.sectionSidebarOpen.setAttribute("aria-expanded", String(!isCollapsed));
  }
}

function scrollToSectionNavTarget(targetId) {
  const target = document.getElementById(targetId);
  if (!target) return;
  target.scrollIntoView({ behavior: "smooth", block: "start", inline: "nearest" });
  if (window.history?.replaceState) {
    const url = new URL(window.location.href);
    url.hash = targetId;
    window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
  }
}

function setActiveSectionNav(targetIds) {
  const activeTargets = new Set(Array.isArray(targetIds) ? targetIds : [targetIds]);
  elements.sectionNavLinks.forEach((link) => {
    const active = activeTargets.has(link.dataset.sectionNavTarget);
    link.classList.toggle("active", active);
    if (active) link.setAttribute("aria-current", "location");
    else link.removeAttribute("aria-current");
  });
}

function setupSectionSidebar() {
  if (!elements.sectionSidebar || !elements.sectionSidebarToggle) return;
  elements.sectionSidebarToggle.addEventListener("click", () => {
    setSectionSidebarCollapsed(elements.sectionSidebar.dataset.collapsed !== "true");
  });
  elements.sectionSidebarOpen?.addEventListener("click", () => setSectionSidebarCollapsed(false));
  elements.sectionNavLinks.forEach((link) => {
    link.addEventListener("click", (event) => {
      event.preventDefault();
      scrollToSectionNavTarget(link.dataset.sectionNavTarget);
    });
  });

  const targets = [...new Set(elements.sectionNavLinks.map((link) => link.dataset.sectionNavTarget))]
    .map((targetId) => document.getElementById(targetId))
    .filter(Boolean);
  if (typeof IntersectionObserver !== "function") {
    setActiveSectionNav(targets[0]?.id || "home");
    return;
  }
  const visibleTargets = new Map();
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) visibleTargets.set(entry.target.id, entry);
      else visibleTargets.delete(entry.target.id);
    });
    const visible = [...visibleTargets.values()].sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
    if (!visible[0]) return;
    const firstTop = visible[0].boundingClientRect.top;
    const activeTargets = visible.filter((entry) => entry.boundingClientRect.top - firstTop < 12).map((entry) => entry.target.id);
    setActiveSectionNav(activeTargets);
  }, { rootMargin: "-12% 0px -72% 0px", threshold: [0, .15, .5, 1] });
  targets.forEach((target) => observer.observe(target));
  setActiveSectionNav(targets[0]?.id || "home");
}

