function resolveTourTarget(step) {
  return typeof step.target === "function" ? step.target() : document.querySelector(step.target);
}

function updateTourPosition() {
  if (!activeTour) return;
  const step = activeTour.steps[activeTour.stepIndex];
  const target = resolveTourTarget(step);
  if (!target) return;
  const rect = target.getBoundingClientRect();
  const padding = 7;
  const margin = 12;
  const gap = 16;
  Object.assign(elements.tourSpotlight.style, {
    left: `${Math.max(4, rect.left - padding)}px`, top: `${Math.max(4, rect.top - padding)}px`,
    width: `${Math.min(window.innerWidth - 8, rect.width + padding * 2)}px`, height: `${Math.min(window.innerHeight - 8, rect.height + padding * 2)}px`
  });
  const safeLeft = Math.max(0, rect.left - padding);
  const safeTop = Math.max(0, rect.top - padding);
  const safeRight = Math.min(window.innerWidth, rect.right + padding);
  const safeBottom = Math.min(window.innerHeight, rect.bottom + padding);
  const safeHeight = Math.max(0, safeBottom - safeTop);
  const shieldBounds = {
    ".tour-shield-top": [0, 0, window.innerWidth, safeTop],
    ".tour-shield-right": [safeRight, safeTop, Math.max(0, window.innerWidth - safeRight), safeHeight],
    ".tour-shield-bottom": [0, safeBottom, window.innerWidth, Math.max(0, window.innerHeight - safeBottom)],
    ".tour-shield-left": [0, safeTop, safeLeft, safeHeight]
  };
  Object.entries(shieldBounds).forEach(([selector, [left, top, width, height]]) => {
    Object.assign(document.querySelector(selector).style, { left: `${left}px`, top: `${top}px`, width: `${width}px`, height: `${height}px` });
  });

  // Informational steps do not require an underlying click. Center their card
  // so a large panel target cannot collapse the tutorial controls.
  if (!step.action) {
    elements.tourPopover.style.removeProperty("--tour-popover-max-height");
    const infoPopover = elements.tourPopover.getBoundingClientRect();
    elements.tourPopover.style.top = `${Math.max(margin, (window.innerHeight - infoPopover.height) / 2)}px`;
    elements.tourPopover.style.left = `${Math.max(margin, (window.innerWidth - infoPopover.width) / 2)}px`;
    return;
  }

  // Reset the size constraint before measuring the next target. A tall tour
  // card previously overlapped the very control it asked the user to click.
  elements.tourPopover.style.removeProperty("--tour-popover-max-height");
  const popoverRect = elements.tourPopover.getBoundingClientRect();
  const below = window.innerHeight - rect.bottom - gap - margin;
  const above = rect.top - gap - margin;
  const right = window.innerWidth - rect.right - gap - margin;
  const left = rect.left - gap - margin;
  const needsSidePlacement = Math.max(above, below) < 260 && Math.max(left, right) >= popoverRect.width;

  let top;
  let horizontal;
  if (needsSidePlacement) {
    const placeRight = right >= left && right >= popoverRect.width;
    horizontal = placeRight ? rect.right + gap : rect.left - gap - popoverRect.width;
    const availableHeight = window.innerHeight - margin * 2;
    elements.tourPopover.style.setProperty("--tour-popover-max-height", `${availableHeight}px`);
    const constrainedHeight = elements.tourPopover.getBoundingClientRect().height;
    top = Math.max(margin, Math.min(window.innerHeight - constrainedHeight - margin, rect.top + (rect.height - constrainedHeight) / 2));
  } else {
    const placeBelow = below >= above;
    const availableHeight = Math.max(0, placeBelow ? below : above);
    elements.tourPopover.style.setProperty("--tour-popover-max-height", `${availableHeight}px`);
    const constrainedHeight = elements.tourPopover.getBoundingClientRect().height;
    top = placeBelow ? rect.bottom + gap : rect.top - gap - constrainedHeight;
    horizontal = Math.max(margin, Math.min(window.innerWidth - popoverRect.width - margin, rect.left));
  }
  elements.tourPopover.style.top = `${top}px`;
  elements.tourPopover.style.left = `${horizontal}px`;
}

function renderTourStep({ scroll = true } = {}) {
  if (!activeTour) return;
  document.querySelectorAll(".tour-target").forEach((element) => element.classList.remove("tour-target"));
  const step = activeTour.steps[activeTour.stepIndex];
  const target = resolveTourTarget(step);
  if (!target) { endTour(); return; }
  // Smooth scrolling can leave the popover positioned for an intermediate
  // target location, covering the control once the scroll finishes.
  if (scroll) target.scrollIntoView({ behavior: "auto", block: "center", inline: "nearest" });
  target.classList.add("tour-target");
  elements.tourIndex.textContent = step.index;
  elements.tourTitle.textContent = step.title;
  elements.tourCopy.textContent = step.copy;
  elements.tourStatus.textContent = step.status || "";
  elements.tourStatus.hidden = !step.status;
  elements.tourProgress.innerHTML = activeTour.steps.map((_, index) => `<i class="${index === activeTour.stepIndex ? "active" : ""}"></i>`).join("");
  elements.tourPrevious.hidden = activeTour.stepIndex === 0;
  elements.tourNext.disabled = Boolean(step.action);
  elements.tourNext.querySelector("span").textContent = step.terminal ? "完成" : "下一步";
  elements.tourNext.querySelector("b").textContent = step.terminal ? "✓" : "→";
  window.requestAnimationFrame(updateTourPosition);
  window.setTimeout(updateTourPosition, scroll ? 120 : 0);
  window.setTimeout(updateTourPosition, scroll ? 520 : 0);
}

function startTour(name, returnFocus = document.activeElement) {
  const steps = TOUR_FLOWS[name];
  if (!steps) return;
  stopPreview();
  if (name === "manual") setInputMode("jianpu", { force: true, silent: true });
  activeTour = { name, steps, stepIndex: 0, returnFocus };
  elements.tourLayer.hidden = false;
  elements.tourLayer.setAttribute("aria-hidden", "false");
  renderTourStep();
  window.setTimeout(() => elements.tourSkip.focus(), 350);
}

function endTour() {
  document.querySelectorAll(".tour-target").forEach((element) => element.classList.remove("tour-target"));
  const returnFocus = activeTour?.returnFocus;
  activeTour = null;
  elements.tourLayer.hidden = true;
  elements.tourLayer.setAttribute("aria-hidden", "true");
  returnFocus?.focus?.({ preventScroll: true });
}

function moveTour(delta) {
  if (!activeTour) return;
  const nextIndex = activeTour.stepIndex + delta;
  if (nextIndex >= activeTour.steps.length) { endTour(); return; }
  if (nextIndex < 0) return;
  activeTour.stepIndex = nextIndex;
  renderTourStep();
}

function completeTourAction(action, status = "操作完成，正在进入下一步。") {
  if (!activeTour || activeTour.steps[activeTour.stepIndex].action !== action) return;
  elements.tourStatus.textContent = status;
  elements.tourStatus.hidden = false;
  window.setTimeout(() => moveTour(1), 140);
}

function setTourStatus(status) {
  if (!activeTour) return;
  elements.tourStatus.textContent = status;
  elements.tourStatus.hidden = false;
}

function syncWorkbenchHeight() {
  if (!elements.workbench || !elements.editorPanel) return;
  if (window.matchMedia("(max-width: 860px)").matches) {
    elements.workbench.style.removeProperty("--workbench-height");
    return;
  }
  // offsetHeight is the unzoomed (layout) height, matching the CSS length used for --workbench-height.
  const editorHeight = elements.editorPanel.offsetHeight;
  if (editorHeight > 0) elements.workbench.style.setProperty("--workbench-height", `${editorHeight}px`);
}

function scheduleWorkbenchHeightSync() {
  window.cancelAnimationFrame(workbenchHeightSyncFrame);
  workbenchHeightSyncFrame = window.requestAnimationFrame(syncWorkbenchHeight);
}
let recording = null;
let selectedRecordModifier = "";
let liveRecordingVoice = null;
let currentScoreCredit = { artist: "", sharedBy: "", displayUrl: "", declaration: "", remixCode: "" };
let currentScoreEditMode = false;
let scoreExportMode = "download";

function tokenPosition(source, offset) {
  const before = source.slice(0, offset);
  return { line: before.split("\n").length, column: offset - before.lastIndexOf("\n") };
}

function pitchCandidates() {
  // The comma key is the eighth base key (C5), not merely display sugar for
  // right-click + Z.  Its altered forms are preferable to equivalent
  // combinations on the lower row: #1' must be M + comma, rather than R + M
  // + Z.  Besides matching the game input precisely, this avoids an
  // unnecessary octave modifier in melodies such as 鸟之诗.
  const candidates = [
    { midi: 72, note: "1'", modifier: null },
    { midi: 73, note: "1'", modifier: "M" },
    { midi: 84, note: "1'", modifier: "R" },
    { midi: 85, note: "1'", modifier: "RM" }
  ];
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi, note, modifier: null }));
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi: midi + 1, note, modifier: "M" }));
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi: midi - 12, note, modifier: "L" }));
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi: midi + 12, note, modifier: "R" }));
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi: midi - 11, note, modifier: "LM" }));
  Object.entries(DIATONIC_MIDI).forEach(([note, midi]) => candidates.push({ midi: midi + 13, note, modifier: "RM" }));
  return candidates;
}

const PLAYABLE_PITCHES = pitchCandidates();

function encodeJianpuPitch(accidental, lowMark, digit, highMark) {
  if (digit === "0") {
    if (accidental || lowMark || highMark) return null;
    return { note: "0", modifier: null };
  }
  const octave = (highMark.length * 12) - (lowMark.length * 12);
  const accidentalOffset = accidental === "#" || accidental === "♯" ? 1 : accidental === "b" || accidental === "♭" ? -1 : 0;
  const midi = DIATONIC_MIDI[digit] + octave + accidentalOffset;
  return PLAYABLE_PITCHES.find((candidate) => candidate.midi === midi) || null;
}

function parseJianpu(source, bpm) {
  if (!source.trim()) return { error: { message: "请先输入至少一个简谱音符。", line: 1, column: 1 } };
  const notes = [];
  let tiePending = false;
  const tokens = [...source.matchAll(/\|\|:|:\|\||\|+|[^\s|]+/g)];
  for (const match of tokens) {
    let token = match[0].replace(/[—–]/g, "-").replace(/[·。]/g, ".").replace(/[，、]$/, "");
    const position = tokenPosition(source, match.index);
    if (/^(?:\|+|\|\|:|:\|\||:|\(|\)|\[|\]|\{|\})$/.test(token)) continue;
    if (/^[1-7]=[A-G](?:[#b♯♭])?$/i.test(token) || /^\d+\/\d+$/.test(token) || /^(?:♩|♪)=?\d+$/.test(token)) continue;
    token = token.replace(/^[([{]+/, "").replace(/[)\]}]+$/, "");
    if (!token) continue;
    if (/^-+$/.test(token)) {
      if (!notes.length) return { error: { message: "延音线前必须先有音符或休止符。", ...position } };
      notes[notes.length - 1].beats += token.length;
      continue;
    }
    if (token === "~") {
      if (!notes.length) return { error: { message: "连音线前必须先有音符。", ...position } };
      tiePending = true;
      continue;
    }
    if (token.replace(/ /g, "").includes(",,,") || /'{3,}/.test(token)) return { error: { message: "高低音标记最多各两个点（文本写法为最多两个逗号或撇号）。", ...position } };
    if (token.includes("____")) return { error: { message: "减时线最多三条（半拍、四分之一拍或八分之一拍）。", ...position } };
    const physicalFound = token.match(/^([LMR]{1,2})(0|1'|[1-7])(_{0,2})(\.*)(-*)(?::(\d+(?:\.\d+)?))?(~?)$/i);
    const found = token.match(/^([#b♯♭]?)(,{0,2})(0|[1-7])('{0,2})(_{0,3})(\.*)(-*)(?::(\d+(?:\.\d+)?))?(~?)$/);
    if (!found && !physicalFound) return { error: { message: `无法识别“${match[0]}”。可输入 5、0、#4、1'、1''、,1、,,1、5_、5___、5.，或用 5:1.25 写精确拍数。`, ...position } };
    if (found && found[4].length === 2 && found[3] !== "1") return { error: { message: "目前仅支持 1'' 双高音；2'' 至 7'' 暂不支持。", ...position } };
    const [, accidental = "", lowMark = "", digit, highMark = "", standardUnderscores = "", standardDots = "", standardDashes = "", standardExplicitBeats, standardTieMark = ""] = found || [];
    const [, physicalModifier = "", physicalDigit, physicalUnderscores = "", physicalDots = "", physicalDashes = "", physicalExplicitBeats, physicalTieMark = ""] = physicalFound || [];
    const note = physicalDigit || digit;
    const modifier = physicalModifier.toUpperCase();
    const underscores = physicalFound ? physicalUnderscores : standardUnderscores;
    const dots = physicalFound ? physicalDots : standardDots;
    const dashes = physicalFound ? physicalDashes : standardDashes;
    const explicitBeats = physicalFound ? physicalExplicitBeats : standardExplicitBeats;
    const tieMark = physicalFound ? physicalTieMark : standardTieMark;
    if (physicalFound && (note === "0" || new Set(modifier).size !== modifier.length || (modifier.includes("L") && modifier.includes("R")))) {
      return { error: { message: "物理键位前缀不能用于休止符，且不能重复或同时包含 L 与 R。", ...position } };
    }
    if (lowMark && highMark) return { error: { message: "同一个音不能同时标记高八度和低八度。", ...position } };
    const pitch = physicalFound ? { note, modifier } : encodeJianpuPitch(accidental, lowMark, note, highMark);
    if (!pitch) return { error: { message: `“${match[0]}”超出当前游戏键位可表达的音域。`, ...position } };
    if (explicitBeats && (underscores || dots || dashes)) return { error: { message: "精确拍数不能与下划线、附点或延音线同时使用。", ...position } };
    const baseBeats = 1 / (2 ** underscores.length);
    const dotFactor = dots.length ? 2 - (1 / (2 ** dots.length)) : 1;
    const beats = explicitBeats ? Number(explicitBeats) : baseBeats * dotFactor + dashes.length;
    if (!Number.isFinite(beats) || beats <= 0) return { error: { message: "拍数必须是大于 0 的数字。", ...position } };
    // Keep the user's standard spelling: #7' and physical R1' share MIDI 84,
    // but only the latter is an upload-incompatible physical-key notation.
    const item = {
      ...pitch,
      ...(physicalFound ? { physicalSourcePitch: `${physicalModifier}${physicalDigit}` } : { sourcePitch: `${accidental}${lowMark}${note}${highMark}` }),
      beats,
      start: match.index,
      ...position
    };
    const previous = notes[notes.length - 1];
    const samePitch = previous && (
      (Number.isFinite(previous.midi) && Number.isFinite(item.midi) && previous.midi === item.midi) ||
      (previous.note === item.note && previous.modifier === item.modifier)
    );
    if (tiePending && samePitch) previous.beats += item.beats;
    else notes.push(item);
    tiePending = Boolean(tieMark);
  }
  if (tiePending) return { error: { message: "连音线后缺少相同音高的音符。", line: source.split("\n").length, column: source.length - source.lastIndexOf("\n") } };
  if (!notes.length) return { error: { message: "没有找到可演奏的简谱音符。", line: 1, column: 1 } };
  return enrichNotes(notes, bpm);
}

function enrichNotes(notes, bpm) {
  if (!Number.isFinite(bpm) || bpm < 30 || bpm > 300) return { error: { message: "BPM 必须在 30 到 300 之间。", line: 1, column: 1 } };
  const beatMs = 60000 / bpm;
  let cursor = 0;
  const enriched = notes.map((item) => {
    const isRest = item.note === "0";
    const durationMs = Math.round(item.beats * beatMs);
    const eventCount = isRest ? 0 : 2 + (item.modifier?.length || 0) * 2;
    const event = { ...item, key: NOTE_KEYS[item.note] || null, isRest, durationMs, pressMs: isRest ? 0 : durationMs, waitMs: 0, inputLeadMs: 0, timeMs: cursor, eventCount };
    cursor += durationMs;
    return event;
  });
  enriched.forEach((event, index) => {
    const next = enriched[index + 1];
    if (event.isRest || !next || next.isRest) return;
    const transitionMs = Math.min(INPUT_TRANSITION_GAP_MS, Math.max(0, event.durationMs - MIN_NOTE_HOLD_MS));
    event.pressMs = event.durationMs - transitionMs;
    event.waitMs = transitionMs;
  });
  enriched.forEach((event) => {
    if (event.isRest || !event.modifier) return;
    event.inputLeadMs = Math.min(MODIFIER_SETTLE_MS, Math.max(0, event.pressMs - MIN_NOTE_HOLD_MS));
  });
  return { notes: enriched, beatMs: Math.round(beatMs), totalMs: cursor, events: enriched.reduce((sum, item) => sum + item.eventCount, 0) };
}

function macroMidi(item) {
  const baseMidi = PREVIEW_MIDI[item.note];
  if (!Number.isFinite(baseMidi)) return null;
  return [...(item.modifier || "")].reduce((midi, modifier) => midi + (PREVIEW_OFFSETS[modifier] || 0), baseMidi);
}

const KEY_SIGNATURE_SEMITONES = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
const KEY_SIGNATURE_NAMES = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];

function playablePitchAt(midi) {
  return PLAYABLE_PITCHES.find((candidate) => candidate.midi === midi) || null;
}

function transposeSequence(sequence, semitones) {
  const notes = [];
  for (const item of sequence.notes) {
    if (item.isRest || item.note === "0") {
      notes.push({ note: "0", modifier: null, beats: item.beats, line: item.line });
      continue;
    }
    const sourceMidi = macroMidi(item);
    const target = Number.isFinite(sourceMidi) ? playablePitchAt(sourceMidi + semitones) : null;
    if (!target) return null;
    notes.push({ note: target.note, modifier: target.modifier, beats: item.beats, line: item.line });
  }
  return enrichNotes(notes, sequence.bpm ? sequence.bpm : Number(elements.bpm.value));
}

function updateTransposeControls(sequence = currentSequence) {
  const pitchValues = sequence?.notes?.filter((item) => !item.isRest && item.note !== "0").map(macroMidi).filter(Number.isFinite) || [];
  if (!pitchValues.length) {
    elements.transposeDown.disabled = true;
    elements.transposeUp.disabled = true;
    elements.transposeStatus.textContent = sequence ? "仅休止" : "等待曲谱";
    return;
  }
  elements.transposeDown.disabled = !transposeSequence(sequence, -1);
  elements.transposeUp.disabled = !transposeSequence(sequence, 1);
  elements.transposeStatus.textContent = `${midiPitchLabel(Math.min(...pitchValues))} ↔ ${midiPitchLabel(Math.max(...pitchValues))}`;
}

function transposeKeySignature(semitones) {
  const match = String(elements.keySignature.value).trim().match(/^(1=)?([A-G])([#♯b♭])?$/i);
  if (!match) return;
  const accidental = match[3] === "#" || match[3] === "♯" ? 1 : match[3] === "b" || match[3] === "♭" ? -1 : 0;
  const natural = KEY_SIGNATURE_SEMITONES[match[2].toUpperCase()];
  if (!Number.isFinite(natural)) return;
  const pitch = (natural + accidental + semitones + 120) % 12;
  elements.keySignature.value = `${match[1] || ""}${KEY_SIGNATURE_NAMES[pitch]}`;
}

function transposeCurrentScore(semitones) {
  const sequence = convert();
  if (!sequence) { toast("请先修正谱子错误。 "); return; }
  const shifted = transposeSequence(sequence, semitones);
  if (!shifted || shifted.error) {
    toast(semitones > 0 ? "已到达口琴可演奏的最高音。" : "已到达口琴可演奏的最低音。");
    updateTransposeControls(sequence);
    return;
  }
  stopPreview();
  finishRecording({ apply: false });
  lastMidiFile = null;
  resetMidiTrackPicker();
  shifted.notes.forEach((item, index) => { item.index = index; });
  currentSequence = shifted;
  syncSequenceToEditors(shifted);
  updateMonitor(shifted);
  transposeKeySignature(semitones);
  elements.status.textContent = "序列已移调";
  setValidation(`已将整首谱子${semitones > 0 ? "升高" : "降低"}半音 · ${shifted.notes.length} 个音符均在口琴可演奏音域内。`, "success");
  updateTransposeControls(shifted);
  toast(`整首谱子已${semitones > 0 ? "升高" : "降低"}半音。`);
}

function parseScore(source, bpm) {
  if (!source.trim()) return { error: { message: "请先输入至少一个音符。", line: 1, column: 1 } };
  if (!Number.isFinite(bpm) || bpm < 30 || bpm > 300) return { error: { message: "BPM 必须在 30 到 300 之间。", line: 1, column: 1 } };
  const notes = [];
  const tokens = [...source.matchAll(/\S+/g)];
  for (const match of tokens) {
    const token = match[0];
    if (token === "|") continue;
    const position = tokenPosition(source, match.index);
    const found = token.match(/^([LMRlmr]{0,2})(0|1'|[1-7])\/(\d+(?:\.\d+)?)$/);
    if (!found) {
      return { error: { message: `无法识别“${token}”。请使用例如 M2/0.5 的格式。`, ...position } };
    }
    const modifier = found[1].trim().toUpperCase() || null;
    const note = found[2];
    const beats = Number(found[3]);
    if (!Number.isFinite(beats) || beats <= 0) return { error: { message: "拍数必须是大于 0 的数字。", ...position } };
    if (note === "0" && modifier) return { error: { message: "休止符不能添加变调前缀。", ...position } };
    if (modifier && (new Set(modifier).size !== modifier.length || (modifier.includes("L") && modifier.includes("R")))) return { error: { message: "变调前缀不能重复，也不能同时使用 L 与 R。", ...position } };
    notes.push({ note, key: NOTE_KEYS[note] || null, modifier, ...(modifier && /[LR]/.test(modifier) ? { physicalSourcePitch: `${modifier}${note}` } : {}), isRest: note === "0", beats, start: match.index, ...position });
  }
  if (!notes.length) return { error: { message: "小节线不是音符，请输入例如 1/1。", line: 1, column: 1 } };
  return enrichNotes(notes, bpm);
}

function parseKeyboardScore(source, bpm) {
  if (!source.trim()) return { error: { message: "请先输入至少一项按键或等待时值。", line: 1, column: 1 } };
  if (!Number.isFinite(bpm) || bpm < 30 || bpm > 300) return { error: { message: "BPM 必须在 30 到 300 之间。", line: 1, column: 1 } };
  const notes = [];
  const beatMs = 60000 / bpm;
  const lines = source.split("\n");

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const rawLine = lines[lineIndex];
    const value = rawLine.trim();
    if (!value) continue;
    const position = { line: lineIndex + 1, column: rawLine.indexOf(value) + 1 };
    const found = value.match(/^(.+?)\s*\/\s*(\d+)\s*ms$/);
    if (!found) {
      return { error: { message: "请使用“按键组合 / 正整数ms”格式，例如 Z / 500ms。", ...position } };
    }

    const input = found[1].trim();
    const durationMs = Number(found[2]);
    if (!Number.isSafeInteger(durationMs) || durationMs <= 0) {
      return { error: { message: "时值必须是正整数毫秒。", ...position } };
    }

    if (input === "等待") {
      notes.push({ note: "0", key: null, modifier: null, isRest: true, beats: durationMs / beatMs, ...position });
      continue;
    }

    const parts = input.split(/\s*\+\s*/).map((part) => part.trim());
    if (!parts.length || parts.some((part) => !part)) {
      return { error: { message: "按键组合中的“+”两侧都必须有内容。", ...position } };
    }
    const keyToken = parts.at(-1).toLowerCase();
    const note = KEY_TO_NOTE[keyToken];
    if (!note) {
      return { error: { message: "按键只能使用 Z、X、C、V、B、N、M 或英文逗号 ,。", ...position } };
    }
    const modifierTokens = parts.slice(0, -1);
    const modifiers = modifierTokens.map((label) => KEYBOARD_LABEL_TO_MODIFIER[label]);
    if (modifiers.some((modifier) => !modifier)) {
      return { error: { message: "变调键只能使用“左键”、“中键”或“右键”，且必须写在键盘按键前。", ...position } };
    }
    if (new Set(modifiers).size !== modifiers.length || (modifiers.includes("L") && modifiers.includes("R"))) {
      return { error: { message: "变调键不能重复，也不能同时使用左键与右键。", ...position } };
    }
    const modifier = ["L", "M", "R"].filter((candidate) => modifiers.includes(candidate)).join("") || null;
    notes.push({ note, key: NOTE_KEYS[note], modifier, isRest: false, beats: durationMs / beatMs, ...position });
  }

  if (!notes.length) return { error: { message: "请至少输入一项按键或等待时值。", line: 1, column: 1 } };
  return enrichNotes(notes, bpm);
}

function readMidiText(bytes) {
  if (!bytes?.length) return "";
  try { return new TextDecoder("utf-8", { fatal: false }).decode(bytes).replace(/\0/g, "").trim(); } catch {}
  return Array.from(bytes, (byte) => String.fromCharCode(byte)).join("").replace(/\0/g, "").trim();
}

function midiKeySignature(sharpsFlats, isMinor) {
  const majorKeys = ["Cb", "Gb", "Db", "Ab", "Eb", "Bb", "F", "C", "G", "D", "A", "E", "B", "F#", "C#"];
  const minorKeys = ["Ab", "Eb", "Bb", "F", "C", "G", "D", "A", "E", "B", "F#", "C#", "G#", "D#", "A#"];
  const index = Math.max(0, Math.min(14, sharpsFlats + 7));
  return `1=${(isMinor ? minorKeys : majorKeys)[index]}`;
}

function midiMedian(values) {
  if (!values.length) return 0;
  const ordered = [...values].sort((left, right) => left - right);
  const middle = Math.floor(ordered.length / 2);
  return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
}

const MIDI_PROGRAM_NAMES = Object.freeze({
  0: "大钢琴",
  4: "电钢琴",
  12: "木琴",
  24: "尼龙弦吉他",
  25: "钢弦吉他",
  32: "原声贝斯",
  33: "电贝斯",
  40: "小提琴",
  41: "中提琴",
  42: "大提琴",
  43: "低音提琴",
  48: "弦乐合奏",
  49: "弦乐合奏 2",
  56: "小号",
  57: "长号",
  64: "高音萨克斯",
  65: "次中音萨克斯",
  73: "长笛",
  74: "短笛",
  80: "合唱音色",
  88: "合成主音",
  118: "合成鼓"
});

function midiTrackDisplayName(track, index) {
  const name = String(track?.name || "").trim();
  const genericName = !name || /^(?:无标题|untitled|track|音轨)(?:\s*\d+)?$/i.test(name);
  const instrument = Number.isInteger(track?.program) ? MIDI_PROGRAM_NAMES[track.program] : "";
  if (!genericName) return instrument ? `${name} · ${instrument}` : name;
  return instrument ? `${instrument} · 音轨 ${String(index + 1).padStart(2, "0")}` : `音轨 ${String(index + 1).padStart(2, "0")}`;
}

function parseMidiData(buffer) {
  const bytes = new Uint8Array(buffer);
  if (bytes.length < 14 || readMidiText(bytes.slice(0, 4)) !== "MThd") throw new Error("这不是有效的标准 MIDI 文件。");
  const readU16 = (offset) => (bytes[offset] << 8) | bytes[offset + 1];
  const readU32 = (offset) => ((bytes[offset] * 0x1000000) + (bytes[offset + 1] << 16) + (bytes[offset + 2] << 8) + bytes[offset + 3]) >>> 0;
  const headerLength = readU32(4);
  if (headerLength < 6 || 8 + headerLength > bytes.length) throw new Error("MIDI 文件头损坏。");
  const division = readU16(12);
  if (division & 0x8000) throw new Error("暂不支持 SMPTE 时间码 MIDI，请先另存为常规节拍（PPQN）MIDI。");
  if (!division) throw new Error("MIDI 的节拍分辨率无效。");
  const trackCount = readU16(10);
  const tempos = [];
  const meters = [];
  const keys = [];
  const tracks = [];
  const ignoredInvalidNonNoteEvents = { controller: 0, program: 0, other: 0 };
  let offset = 8 + headerLength;

  function readVariable(cursor, end) {
    let value = 0;
    for (let count = 0; count < 4; count += 1) {
      if (cursor >= end) throw new Error("MIDI 事件被意外截断。");
      const byte = bytes[cursor++];
      value = (value << 7) | (byte & 0x7f);
      if (!(byte & 0x80)) return { value, cursor };
    }
    throw new Error("MIDI 事件长度无效。");
  }

  for (let trackIndex = 0; trackIndex < trackCount && offset + 8 <= bytes.length; trackIndex += 1) {
    const chunkType = readMidiText(bytes.slice(offset, offset + 4));
    const chunkLength = readU32(offset + 4);
    const start = offset + 8;
    const end = start + chunkLength;
    if (end > bytes.length) throw new Error("MIDI 音轨数据被意外截断。");
    offset = end;
    if (chunkType !== "MTrk") continue;
    let cursor = start;
    let tick = 0;
    let runningStatus = null;
    let name = "";
    let program = null;
    const active = new Map();
    const notes = [];
    while (cursor < end) {
      const delta = readVariable(cursor, end);
      tick += delta.value;
      cursor = delta.cursor;
      if (cursor >= end) throw new Error("MIDI 事件缺少状态字节。");
      let status = bytes[cursor++];
      let firstData = null;
      if (status < 0x80) {
        if (!runningStatus) throw new Error("MIDI 的运行状态无效。 ");
        firstData = status;
        status = runningStatus;
      }
      if (status === 0xff) {
        if (cursor >= end) throw new Error("MIDI 元事件损坏。");
        const type = bytes[cursor++];
        const length = readVariable(cursor, end);
        cursor = length.cursor;
        if (cursor + length.value > end) throw new Error("MIDI 元事件被意外截断。");
        const data = bytes.slice(cursor, cursor + length.value);
        cursor += length.value;
        if (type === 0x03 && !name) name = readMidiText(data);
        if (type === 0x51 && data.length === 3) tempos.push({ tick, value: (data[0] << 16) | (data[1] << 8) | data[2], trackIndex });
        if (type === 0x58 && data.length >= 2) meters.push({ tick, numerator: data[0], denominator: 2 ** data[1], trackIndex });
        if (type === 0x59 && data.length >= 2) keys.push({ tick, sharpsFlats: data[0] > 127 ? data[0] - 256 : data[0], isMinor: data[1] === 1, trackIndex });
        continue;
      }
      if (status === 0xf0 || status === 0xf7) {
        const length = readVariable(cursor, end);
        cursor = length.cursor + length.value;
        if (cursor > end) throw new Error("MIDI 系统事件被意外截断。");
        continue;
      }
      if (status < 0x80 || status > 0xef) throw new Error("MIDI 包含不支持的系统事件。");
      runningStatus = status;
      const type = status & 0xf0;
      const channel = status & 0x0f;
      const dataLength = type === 0xc0 || type === 0xd0 ? 1 : 2;
      const data1 = firstData ?? bytes[cursor++];
      if (data1 === undefined || (dataLength === 2 && cursor >= end)) throw new Error("MIDI 通道事件被意外截断。");
      const data2 = dataLength === 2 ? bytes[cursor++] : 0;
      if (data1 > 127 || data2 > 127) {
        if (type === 0x80 || type === 0x90) throw new Error("MIDI 音符事件数据无效。");
        if (type === 0xb0) ignoredInvalidNonNoteEvents.controller += 1;
        else if (type === 0xc0) ignoredInvalidNonNoteEvents.program += 1;
        else ignoredInvalidNonNoteEvents.other += 1;
        continue;
      }
      if (type === 0xc0) {
        if (program === null) program = data1;
        continue;
      }
      if (type !== 0x80 && type !== 0x90) continue;
      const noteKey = `${channel}:${data1}`;
      if (type === 0x90 && data2 > 0) {
        const pending = active.get(noteKey) || [];
        pending.push({ start: tick, midi: data1, channel });
        active.set(noteKey, pending);
      } else {
        const pending = active.get(noteKey);
        const started = pending?.shift();
        if (!pending?.length) active.delete(noteKey);
        if (started && tick > started.start) notes.push({ ...started, id: notes.length, end: tick });
      }
    }
    tracks.push({ name, program, notes });
  }
  if (!tracks.length) throw new Error("MIDI 文件中没有可读取的音轨。");
  return { division, tracks, tempos, meters, keys, ignoredInvalidNonNoteEvents };
}

function selectMidiMelodyTrack(tracks) {
  const candidates = tracks.map((track, index) => ({ ...track, index, notes: track.notes.filter((note) => note.channel !== 9) })).filter((track) => track.notes.length);
  if (!candidates.length) throw new Error("MIDI 中没有可演奏的非打击乐音符。");
  return candidates.map((track) => {
    const starts = new Set(track.notes.map((note) => note.start)).size;
    const median = midiMedian(track.notes.map((note) => note.midi));
    const monophonicRatio = starts / track.notes.length;
    return { ...track, rank: track.notes.length * (0.6 + monophonicRatio) + median / 3 };
  }).sort((left, right) => right.rank - left.rank || right.notes.length - left.notes.length || right.index - left.index)[0];
}

function midiTrackCandidates(tracks) {
  return tracks.map((track, index) => ({ ...track, index, notes: track.notes.filter((note) => note.channel !== 9) })).filter((track) => track.notes.length);
}

function midiDurationTicks(parsed) {
  return Math.max(parsed.division, ...parsed.tracks.flatMap((track) => track.notes.map((note) => note.end)), ...parsed.tempos.map((tempo) => tempo.tick), ...parsed.meters.map((meter) => meter.tick));
}

function chooseMidiTranspose(notes) {
  const playable = new Set(PLAYABLE_PITCHES.map((item) => item.midi));
  const median = midiMedian(notes.map((note) => note.midi));
  return [-36, -24, -12, 0, 12, 24, 36].map((shift) => {
    const covered = notes.filter((note) => playable.has(note.midi + shift)).length;
    return { shift, rank: covered * 100 - Math.abs(shift) * 3 - Math.abs(median + shift - 66) * 0.2 };
  }).sort((left, right) => right.rank - left.rank || Math.abs(left.shift) - Math.abs(right.shift))[0].shift;
}

function chooseMidiTransposeForTracks(parsed, trackIndexes) {
  const notes = trackIndexes.flatMap((trackIndex) => parsed.tracks[trackIndex]?.notes || []).filter((note) => note.channel !== 9);
  return notes.length ? chooseMidiTranspose(notes) : 0;
}

function midiChordGroups(notes, division) {
  const chordWindowTicks = Math.max(1, Math.round(division / 64));
  const ordered = [...notes].sort((left, right) => left.start - right.start || right.midi - left.midi || right.end - left.end);
  const groups = [];
  let chord = [];
  const flush = () => {
    if (!chord.length) return;
    groups.push(chord);
    chord = [];
  };
  ordered.forEach((note) => {
    if (chord.length && note.start - chord[0].start > chordWindowTicks) flush();
    chord.push(note);
  });
  flush();
  return groups;
}

function defaultMidiNoteSelection(notes, division) {
  return new Set(midiChordGroups(notes, division).map((group) => [...group].sort((left, right) => right.midi - left.midi || right.end - left.end)[0].id));
}

function collapseMidiChords(notes, division) {
  const melody = midiChordGroups(notes, division).map((group) => [...group].sort((left, right) => right.midi - left.midi || right.end - left.end)[0]);
  return { notes: melody, collapsedNotes: Math.max(0, notes.length - melody.length) };
}

function midiToSequence(parsed, { trackIndex = null, trackIndexes = null, startTick = 0, endTick = null, selectedNoteIds = null, transposeOverride = null } = {}) {
  const candidates = midiTrackCandidates(parsed.tracks);
  if (!candidates.length) throw new Error("MIDI 中没有可演奏的非打击乐音符。");
  const indexes = [...new Set((Array.isArray(trackIndexes) ? trackIndexes : [trackIndex === null ? selectMidiMelodyTrack(parsed.tracks).index : trackIndex]).map(Number))].filter((index) => candidates.some((candidate) => candidate.index === index));
  if (!indexes.length) throw new Error("所选 MIDI 音轨没有可演奏的非打击乐音符。");
  const durationTicks = midiDurationTicks(parsed);
  const from = Math.max(0, Math.min(durationTicks - 1, Math.round(startTick)));
  const to = Math.max(from + 1, Math.min(durationTicks, Math.round(endTick ?? durationTicks)));
  const hasPreciseSelection = indexes.length === 1 && selectedNoteIds !== null && selectedNoteIds !== undefined;
  const selectedIds = hasPreciseSelection ? new Set(selectedNoteIds) : null;
  const sourceNotes = indexes.flatMap((index) => {
    const track = parsed.tracks[index];
    const trackSelectedIds = index === indexes[0] ? selectedIds : null;
    return (track?.notes || []).filter((note) => note.channel !== 9 && note.end > from && note.start < to && (!trackSelectedIds || trackSelectedIds.has(note.id))).map((note) => ({
      ...note,
      trackIndex: index,
      start: Math.max(note.start, from) - from,
      end: Math.min(note.end, to) - from
    }));
  });
  if (!sourceNotes.length) throw new Error(hasPreciseSelection ? "精确选择中没有可转换的音符。" : "所选音轨在这个截取范围内没有可转换的音符。");
  const collapsed = hasPreciseSelection ? { notes: [...sourceNotes].sort((left, right) => left.start - right.start || right.midi - left.midi || right.end - left.end), collapsedNotes: 0 } : collapseMidiChords(sourceNotes, parsed.division);
  const melody = collapsed.notes;
  const transpose = Number.isFinite(transposeOverride) ? transposeOverride : chooseMidiTransposeForTracks(parsed, indexes);
  const notes = [];
  const ticksToBeats = (ticks) => Math.round((ticks / parsed.division) * 1000000) / 1000000;
  let cursor = 0;
  melody.forEach((source, index) => {
    const start = Math.max(cursor, source.start);
    if (start > cursor) notes.push({ note: "0", modifier: null, beats: ticksToBeats(start - cursor), line: Math.floor(notes.length / 8) + 1 });
    const nextStart = melody[index + 1]?.start;
    const end = nextStart ? Math.min(source.end, Math.max(start + 1, nextStart)) : source.end;
    const midi = source.midi + transpose;
    const mapped = PLAYABLE_PITCHES.find((candidate) => candidate.midi === midi);
    if (mapped) notes.push({ note: mapped.note, modifier: mapped.modifier, beats: ticksToBeats(Math.max(1, end - start)), line: Math.floor(notes.length / 8) + 1 });
    cursor = Math.max(cursor, end);
  });
  if (!notes.length) throw new Error("MIDI 主旋律没有落在可转换的音域内。");
  const firstTempo = [...parsed.tempos].sort((left, right) => left.tick - right.tick || left.trackIndex - right.trackIndex)[0]?.value || 500000;
  const bpm = Math.max(30, Math.min(300, Math.round(60000000 / firstTempo)));
  const sequence = enrichNotes(notes, bpm);
  if (sequence.error) throw new Error(sequence.error.message);
  const meter = [...parsed.meters].sort((left, right) => left.tick - right.tick || left.trackIndex - right.trackIndex)[0];
  const key = [...parsed.keys].sort((left, right) => left.tick - right.tick || left.trackIndex - right.trackIndex)[0];
  return {
    sequence,
    bpm,
    meter: meter ? `${meter.numerator}/${meter.denominator}` : "4/4",
    key: key ? midiKeySignature(key.sharpsFlats, key.isMinor) : "1=C",
    trackName: indexes.map((index) => midiTrackDisplayName(parsed.tracks[index], index)).join(" + "),
    trackIndexes: indexes,
    selectedNotes: melody.length,
    sourceNoteCount: sourceNotes.length,
    startTick: from,
    endTick: to,
    collapsedChordNotes: collapsed.collapsedNotes,
    precisionSelection: hasPreciseSelection,
    ignoredInvalidNonNoteEvents: parsed.ignoredInvalidNonNoteEvents,
    transpose,
    hasTempoChanges: parsed.tempos.length > 1
  };
}

function smoothMidiSequence(sequence, bpm) {
  const notes = sequence.notes.map((item) => ({ note: item.note, modifier: item.modifier, beats: item.beats, line: item.line }));
  let connectedGaps = 0;
  notes.forEach((item, index) => {
    const previous = notes[index - 1];
    const next = notes[index + 1];
    if (item.note !== "0" || !previous || previous.note === "0" || !next || next.note === "0" || item.beats > 1) return;
    const breathBeats = Math.min(item.beats, 0.04);
    previous.beats += item.beats - breathBeats;
    item.beats = breathBeats;
    connectedGaps += 1;
  });
  const smoothed = enrichNotes(notes, bpm);
  if (smoothed.error) throw new Error(smoothed.error.message);
  return { sequence: smoothed, connectedGaps };
}

function describeIgnoredMidiEvents(events = {}) {
  const descriptions = [];
  if (events.controller) descriptions.push(`${events.controller} 个无效控制器事件`);
  if (events.program) descriptions.push(`${events.program} 个无效程序切换事件`);
  if (events.other) descriptions.push(`${events.other} 个无效非音符事件`);
  return descriptions.length ? ` · 已忽略 ${descriptions.join("、")}` : "";
}

function midiStartBpm(parsed) {
  const tempo = [...parsed.tempos].sort((left, right) => left.tick - right.tick || left.trackIndex - right.trackIndex)[0]?.value || 500000;
  return Math.max(30, Math.min(300, Math.round(60000000 / tempo)));
}

function midiTickToTime(parsed, tick) {
  return formatTime((Math.max(0, tick) / parsed.division) * (60000 / midiStartBpm(parsed)));
}

function midiTickToMilliseconds(parsed, tick) {
  return (Math.max(0, tick) / parsed.division) * (60000 / midiStartBpm(parsed));
}

function midiPitchLabel(midi) {
  const names = ["C", "C♯", "D", "D♯", "E", "F", "F♯", "G", "G♯", "A", "A♯", "B"];
  return `${names[((midi % 12) + 12) % 12]}${Math.floor(midi / 12) - 1}`;
}

function midiTrackBounds(parsed, trackIndex, durationTicks = midiDurationTicks(parsed), selectedNoteIds = null) {
  const selectedIds = selectedNoteIds ? new Set(selectedNoteIds) : null;
  const notes = (parsed.tracks[trackIndex]?.notes || []).filter((note) => note.channel !== 9 && (!selectedIds || selectedIds.has(note.id)));
  if (!notes.length) return { startTick: 0, endTick: durationTicks };
  return {
    startTick: Math.min(...notes.map((note) => note.start)),
    endTick: Math.max(...notes.map((note) => note.end))
  };
}

function midiSelectionBounds(parsed, trackIndexes, durationTicks = midiDurationTicks(parsed)) {
  const bounds = trackIndexes
    .map((trackIndex) => midiTrackBounds(parsed, trackIndex, durationTicks))
    .filter((item) => item.endTick > item.startTick);
  if (!bounds.length) return { startTick: 0, endTick: durationTicks };
  return {
    startTick: Math.min(...bounds.map((item) => item.startTick)),
    endTick: Math.max(...bounds.map((item) => item.endTick))
  };
}

function resetMidiTrackPicker() {
  if (elements.midiNotePickerDialog.open) elements.midiNotePickerDialog.close();
  midiNotePickerState = null;
  midiImportState = null;
  elements.midiTrackPicker.hidden = true;
  elements.midiTrackList.innerHTML = "";
}

function updateMidiRangeUi() {
  if (!midiImportState) return;
  const { parsed, durationTicks } = midiImportState;
  let startTick = Number(elements.midiRangeStartInput.value);
  let endTick = Number(elements.midiRangeEndInput.value);
  if (startTick >= endTick) {
    if (document.activeElement === elements.midiRangeStartInput) startTick = Math.max(0, endTick - 1);
    else endTick = Math.min(durationTicks, startTick + 1);
  }
  midiImportState.startTick = startTick;
  midiImportState.endTick = endTick;
  elements.midiRangeStartInput.value = startTick;
  elements.midiRangeEndInput.value = endTick;
  const left = (startTick / durationTicks) * 100;
  const width = ((endTick - startTick) / durationTicks) * 100;
  const windowBar = elements.midiRangeSliders.querySelector(".midi-range-window");
  windowBar.style.left = `${left}%`;
  windowBar.style.width = `${width}%`;
  elements.midiRangeStart.textContent = `开始 ${midiTickToTime(parsed, startTick)}`;
  elements.midiRangeEnd.textContent = `结束 ${midiTickToTime(parsed, endTick)}`;
  elements.midiRangeSummary.textContent = `截取 ${midiTickToTime(parsed, endTick - startTick)}`;
}

function renderMidiTrackPicker() {
  if (!midiImportState) return;
  const { parsed, selectedTrackIndex, selectedTrackIndexes, durationTicks } = midiImportState;
  const playableTracks = midiTrackCandidates(parsed.tracks);
  const tracks = parsed.tracks.map((track, index) => ({ ...track, index, playableNotes: track.notes.filter((note) => note.channel !== 9) }));
  const pitches = tracks.flatMap((track) => track.notes.map((note) => note.midi));
  const lowestPitch = Math.floor((Math.min(...pitches) - 2) / 12) * 12;
  const highestPitch = Math.ceil((Math.max(...pitches) + 2) / 12) * 12;
  const pitchSpan = Math.max(12, highestPitch - lowestPitch);
  elements.midiTrackPicker.hidden = false;
  const rangeHint = midiImportState.rangeAutoTrimmed ? "已自动裁去所选轨首尾空白" : "已手动调整范围";
  const sharedTranspose = chooseMidiTransposeForTracks(parsed, selectedTrackIndexes);
  const transposeHint = sharedTranspose ? ` · 统一移调 ${sharedTranspose > 0 ? "+" : ""}${sharedTranspose}` : " · 保持原调高";
  elements.midiPickerStatus.textContent = `${tracks.length} 条音轨 · ${playableTracks.length} 条可转换 · 已选 ${selectedTrackIndexes.length} 条${transposeHint} · ${rangeHint}`;
  elements.midiTrackList.innerHTML = tracks.map((track) => {
    const noteBars = track.notes.map((note) => {
      const left = (note.start / durationTicks) * 100;
      const width = Math.max(.35, ((note.end - note.start) / durationTicks) * 100);
      const top = Math.max(2, Math.min(94, ((highestPitch - note.midi) / pitchSpan) * 100));
      return `<i style="left:${left.toFixed(3)}%;width:${width.toFixed(3)}%;top:${top.toFixed(3)}%"></i>`;
    }).join("");
    const label = midiTrackDisplayName(track, track.index);
    const selectable = track.playableNotes.length > 0;
    const selected = selectable && selectedTrackIndexes.includes(track.index);
    const focused = selectable && track.index === selectedTrackIndex;
    const preciseSelection = midiImportState.preciseSelections?.[track.index];
    const preciseCount = Array.isArray(preciseSelection) ? preciseSelection.length : null;
    const noteDescription = selectable ? `${track.playableNotes.length} 个可转换音符${preciseCount !== null ? ` · 已精确选 ${preciseCount} 音` : ""}` : track.notes.length ? "仅打击乐，无法转换" : "无音符";
    return `<div class="midi-track-row"><button class="midi-track${selected ? " selected" : ""}" data-midi-track-select-index="${track.index}" type="button" role="checkbox" aria-checked="${selected}" aria-label="${selected ? "取消导入" : "导入"}${escapeHtml(label)}，${noteDescription}"${selectable ? "" : " disabled"}><span class="midi-track-index">${selected ? "✓" : String(track.index + 1).padStart(2, "0")}</span><span class="midi-track-name">${escapeHtml(label)}${focused ? " <em>当前</em>" : ""}<small>${noteDescription}</small></span><span class="midi-track-bar" aria-hidden="true"><b>${midiPitchLabel(highestPitch)}</b>${noteBars}<b>${midiPitchLabel(lowestPitch)}</b></span><span class="midi-track-count">${track.notes.length} NOTES</span></button><button class="midi-track-precise" data-midi-track-precise-index="${track.index}" type="button" aria-haspopup="dialog" aria-label="精确选择 ${escapeHtml(label)} 的音符"${selectable ? "" : " disabled"}><span>精确选中</span><b>⌖</b></button></div>`;
  }).join("");
  [elements.midiRangeStartInput, elements.midiRangeEndInput].forEach((input) => {
    input.max = durationTicks;
    input.value = input === elements.midiRangeStartInput ? midiImportState.startTick : midiImportState.endTick;
  });
  updateMidiRangeUi();
}

function openMidiTrackPicker(file, parsed) {
  const defaultTrack = selectMidiMelodyTrack(parsed.tracks);
  const durationTicks = midiDurationTicks(parsed);
  const playableTrackIndexes = midiTrackCandidates(parsed.tracks).map((track) => track.index);
  const selectedTrackIndexes = playableTrackIndexes.length > 1 ? playableTrackIndexes : [defaultTrack.index];
  const bounds = midiSelectionBounds(parsed, selectedTrackIndexes, durationTicks);
  midiImportState = { file, parsed, title: file.name.replace(/\.(?:mid|midi)$/i, "").trim() || "MIDI 导入曲目", selectedTrackIndex: defaultTrack.index, selectedTrackIndexes, durationTicks, preciseSelections: {}, ...bounds, rangeAutoTrimmed: true };
  renderMidiTrackPicker();
  elements.midiTrackPicker.scrollIntoView({ behavior: "smooth", block: "nearest" });
  toast("请选择需要转换的音轨与片段，然后点击“确定并生成谱子”。");
}

function midiTrackLabel(trackIndex) {
  const track = midiImportState?.parsed.tracks[trackIndex];
  return midiTrackDisplayName(track, trackIndex);
}

function updateMidiNotePickerSelectionUi() {
  if (!midiNotePickerState) return;
  const { selection } = midiNotePickerState;
  elements.midiNotePickerCount.textContent = `已选 ${selection.size} 音`;
  elements.midiNoteRoll.querySelectorAll("[data-midi-note-id]").forEach((button) => {
    const selected = selection.has(Number(button.dataset.midiNoteId));
    button.classList.toggle("selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
}

function midiOverlapGapRange() {
  const minimum = Number(elements.midiOverlapMinGap.value);
  const maximum = Number(elements.midiOverlapMaxGap.value);
  const minGapMs = Number.isFinite(minimum) ? Math.max(0, Math.min(60000, Math.round(minimum))) : 0;
  const maxGapMs = Number.isFinite(maximum) ? Math.max(minGapMs, Math.min(60000, Math.round(maximum))) : minGapMs;
  elements.midiOverlapMinGap.value = minGapMs;
  elements.midiOverlapMaxGap.value = maxGapMs;
  return { minGapMs, maxGapMs };
}

function midiNoteSelectionGroupIds(noteId) {
  return midiNotePickerState?.groupsById.get(noteId) || [noteId];
}

function midiNoteSelectionTargets(candidateIds, notesById, direction) {
  const targetByGroup = new Map();
  candidateIds.forEach((id) => {
    const note = notesById.get(id);
    if (!note) return;
    const groupIds = midiNoteSelectionGroupIds(id);
    const groupKey = groupIds.join(",");
    const current = targetByGroup.get(groupKey);
    const startsBefore = direction === "earlier" ? note.start < current?.start : note.start > current?.start;
    const sameStartHigher = note.start === current?.start && note.midi > (current?.midi ?? -1);
    if (!current || startsBefore || sameStartHigher) targetByGroup.set(groupKey, note);
  });
  return new Set([...targetByGroup.values()].map((note) => note.id));
}

function applyMidiOverlapChoice(choice) {
  if (!midiNotePickerState || !midiImportState) return;
  const { parsed } = midiImportState;
  const { trackIndex, selection } = midiNotePickerState;
  const notes = parsed.tracks[trackIndex].notes.filter((note) => note.channel !== 9);
  const notesById = new Map(notes.map((note) => [note.id, note]));
  const { minGapMs, maxGapMs } = midiOverlapGapRange();
  const ordered = [...notes].sort((left, right) => left.start - right.start || left.end - right.end || left.midi - right.midi);
  const earlierTargets = new Set();
  const laterTargets = new Set();
  let matchedPairs = 0;

  for (let leftIndex = 0; leftIndex < ordered.length; leftIndex += 1) {
    const left = ordered[leftIndex];
    for (let rightIndex = leftIndex + 1; rightIndex < ordered.length; rightIndex += 1) {
      const right = ordered[rightIndex];
      if (right.start >= left.end) break;
      if (right.start === left.start) continue;
      const gapMs = midiTickToMilliseconds(parsed, right.start - left.start);
      if (gapMs < minGapMs || gapMs > maxGapMs) continue;
      matchedPairs += 1;
      earlierTargets.add(left.id);
      laterTargets.add(right.id);
    }
  }

  if (!matchedPairs) {
    elements.midiOverlapStatus.textContent = `当前范围内没有找到起点间隔 ${minGapMs}–${maxGapMs} 毫秒的重叠音对`;
    return;
  }

  const targetCandidates = choice === "later" ? laterTargets : earlierTargets;
  const targetIds = midiNoteSelectionTargets(targetCandidates, notesById, choice === "later" ? "later" : "earlier");
  const idsToClear = new Set();
  [...earlierTargets, ...laterTargets].forEach((id) => midiNoteSelectionGroupIds(id).forEach((groupId) => idsToClear.add(groupId)));
  idsToClear.forEach((id) => selection.delete(id));
  targetIds.forEach((id) => selection.add(id));
  updateMidiNotePickerSelectionUi();
  const direction = choice === "later" ? "后一个" : "前一个";
  elements.midiOverlapStatus.textContent = `已批量保留${direction}：处理 ${matchedPairs} 对重叠音，范围 ${minGapMs}–${maxGapMs} 毫秒`;
}

function renderMidiNotePicker() {
  if (!midiNotePickerState || !midiImportState) return;
  const { parsed } = midiImportState;
  const { trackIndex, selection } = midiNotePickerState;
  const notes = parsed.tracks[trackIndex].notes.filter((note) => note.channel !== 9);
  const firstTick = Math.min(...notes.map((note) => note.start));
  const lastTick = Math.max(...notes.map((note) => note.end));
  const tickSpan = Math.max(parsed.division, lastTick - firstTick);
  const lowestPitch = Math.max(0, Math.min(...notes.map((note) => note.midi)) - 1);
  const highestPitch = Math.min(127, Math.max(...notes.map((note) => note.midi)) + 1);
  const rows = highestPitch - lowestPitch + 1;
  const rowHeight = 25;
  const rollWidth = Math.max(860, Math.ceil((tickSpan / parsed.division) * 76));
  const beatWidth = rollWidth / (tickSpan / parsed.division);
  const noteButtons = notes.map((note) => {
    const left = ((note.start - firstTick) / tickSpan) * rollWidth;
    const width = Math.max(9, ((note.end - note.start) / tickSpan) * rollWidth);
    const top = (highestPitch - note.midi) * rowHeight + 2;
    const selected = selection.has(note.id);
    const label = `${midiPitchLabel(note.midi)} · ${midiTickToTime(parsed, note.start)} · ${midiTickToTime(parsed, note.end - note.start)}${selected ? "，已选中" : "，未选中"}`;
    return `<button class="midi-note-block${selected ? " selected" : ""}" data-midi-note-id="${note.id}" type="button" aria-pressed="${selected}" aria-label="${label}" title="${label}" style="left:${left.toFixed(1)}px;width:${width.toFixed(1)}px;top:${top}px"></button>`;
  }).join("");
  const pitchLabels = Array.from({ length: rows }, (_, index) => {
    const pitch = highestPitch - index;
    return `<span class="midi-note-pitch" style="top:${index * rowHeight + 6}px">${midiPitchLabel(pitch)}</span>`;
  }).join("");
  const rulerMarks = [];
  const beatStep = tickSpan / parsed.division > 80 ? 16 : tickSpan / parsed.division > 32 ? 8 : 4;
  for (let beat = 0; beat <= tickSpan / parsed.division; beat += beatStep) {
    const left = beat * beatWidth;
    rulerMarks.push(`<span style="left:${left.toFixed(1)}px">${midiTickToTime(parsed, firstTick + beat * parsed.division)}</span>`);
  }
  elements.midiNotePickerTitle.textContent = `精确选择 · ${midiTrackLabel(trackIndex)}`;
  elements.midiNotePickerCopy.textContent = `点击 ${notes.length} 个原始 MIDI 音符中的任一项以保留或取消。相同起始时刻附近的和弦只能保留一个音，选择其他音会自动替换。`;
  elements.midiNoteRuler.style.width = `${rollWidth}px`;
  elements.midiNoteRuler.innerHTML = rulerMarks.join("");
  elements.midiNoteRoll.style.width = `${rollWidth}px`;
  elements.midiNoteRoll.style.height = `${rows * rowHeight}px`;
  elements.midiNoteRoll.innerHTML = `${pitchLabels}${noteButtons}`;
  updateMidiNotePickerSelectionUi();
}

function openMidiNotePicker(trackIndex, opener) {
  if (!midiImportState) return;
  const notes = midiImportState.parsed.tracks[trackIndex]?.notes.filter((note) => note.channel !== 9) || [];
  if (!notes.length) { toast("这条音轨没有可精确选择的非打击乐音符。 "); return; }
  const saved = midiImportState.preciseSelections?.[trackIndex];
  const availableIds = new Set(notes.map((note) => note.id));
  const selection = new Set(Array.isArray(saved) ? saved.filter((id) => availableIds.has(id)) : defaultMidiNoteSelection(notes, midiImportState.parsed.division));
  const groupsById = new Map();
  midiChordGroups(notes, midiImportState.parsed.division).forEach((group) => {
    const ids = group.map((note) => note.id);
    ids.forEach((id) => groupsById.set(id, ids));
  });
  midiNotePickerState = { trackIndex, selection, groupsById, opener };
  elements.midiOverlapMinGap.value = 0;
  elements.midiOverlapMaxGap.value = 100;
  elements.midiOverlapStatus.textContent = "设置范围后，选择批量保留方向";
  renderMidiNotePicker();
  elements.midiNotePickerDialog.showModal();
  window.requestAnimationFrame(() => elements.midiNoteScroll.focus({ preventScroll: true }));
}

function applyMidiNotePickerSelection() {
  if (!midiImportState || !midiNotePickerState) return;
  const { trackIndex, selection } = midiNotePickerState;
  if (!selection.size) { toast("请至少保留一个音符后再应用。 "); return; }
  midiImportState.preciseSelections[trackIndex] = [...selection];
  midiImportState.selectedTrackIndex = trackIndex;
  const selectedTrackIndexes = new Set(midiImportState.selectedTrackIndexes || []);
  selectedTrackIndexes.add(trackIndex);
  midiImportState.selectedTrackIndexes = [...selectedTrackIndexes].sort((left, right) => left - right);
  Object.assign(midiImportState, midiSelectionBounds(midiImportState.parsed, midiImportState.selectedTrackIndexes, midiImportState.durationTicks));
  midiImportState.rangeAutoTrimmed = true;
  midiImportState.applied = false;
  renderMidiTrackPicker();
  elements.midiNotePickerDialog.close();
  toast(`已为${midiTrackLabel(trackIndex)}应用 ${selection.size} 个精确选择音符。`);
}

function formatTime(milliseconds) {
  const ms = Math.max(0, Math.round(milliseconds));
  const minutes = Math.floor(ms / 60000);
  const seconds = Math.floor((ms % 60000) / 1000);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${String(ms % 1000).padStart(3, "0")}`;
}

const editorLineNumberPairs = [
  [elements.score, elements.lineNumbers],
  [elements.jianpuScore, elements.jianpuLineNumbers],
  [elements.keyboardScore, elements.keyboardLineNumbers]
];

function syncLineNumbers(textarea, gutter) {
  if (!textarea || !gutter) return;
  if (gutter.scrollTop !== textarea.scrollTop) gutter.scrollTop = textarea.scrollTop;
}

function updateLineNumbers() {
  editorLineNumberPairs.forEach(([textarea, gutter]) => {
    const lines = Math.max(1, textarea.value.split("\n").length);
    gutter.textContent = Array.from({ length: lines }, (_, index) => index + 1).join("\n");
    syncLineNumbers(textarea, gutter);
  });
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[character]));
}

function parseLegacyDetail(detail = "") {
  const parts = String(detail).split(" · ").map((part) => part.trim()).filter(Boolean);
  const key = parts.find((part) => /^(?:1=)?[A-G](?:[#b♯♭])?$/i.test(part)) || "调待补";
  const meter = parts.find((part) => /^\d{1,2}\/\d{1,2}$/.test(part)) || "拍号待补";
  const bpmIndex = parts.findIndex((part) => /^\d{2,3}\s*BPM$/i.test(part));
  const artist = bpmIndex >= 0
    ? parts.slice(bpmIndex + 1).filter((part) => !/^自动移调/.test(part)).join(" · ")
    : "";
  return { key, meter, artist };
}

function normalizeStoredRemixCode(value = "") {
  const code = String(value || "").trim().toUpperCase();
  return /^[0-9A-F]{21}$/.test(code) ? code : "";
}

function normalizeSong(song) {
  const builtin = BUILTIN_SONG_METADATA[song.title] || {};
  const legacy = parseLegacyDetail(song.detail);
  const displayUrl = validateDisplayUrl(song.displayUrl);
  return {
    ...song,
    title: String(song.title || "未命名曲目").trim() || "未命名曲目",
    artist: String(song.artist || builtin.artist || legacy.artist || "未署名").trim() || "未署名",
    sharedBy: String(song.sharedBy || "Jiko").trim() || "Jiko",
    sponsor: String(song.sponsor || "").trim(),
    key: String(song.key || builtin.key || legacy.key || "调待补").trim() || "调待补",
    meter: String(song.meter || builtin.meter || legacy.meter || "拍号待补").trim() || "拍号待补",
    bpm: Number(song.bpm) || 120,
    createdAt: typeof song.createdAt === "string" ? song.createdAt.trim() : "",
    displayUrl: displayUrl.value || "",
    remixCode: normalizeStoredRemixCode(song.remixCode)
  };
}

const REMIX_CODE_LENGTH = 21;
const REMIX_CODE_PATTERN = new RegExp(`^[0-9a-f]{${REMIX_CODE_LENGTH}}$`, "i");
const remixCodeCache = new Map();
const remixCodePending = new Map();

function remixCodePayload(song) {
  return JSON.stringify([
    String(song.title || "").trim(),
    String(song.artist || "").trim(),
    String(song.sharedBy || "").trim(),
    String(song.key || "").trim(),
    String(song.meter || "").trim(),
    Number(song.bpm) || 120,
    song.jianpu ? "jianpu" : "score",
    String(song.jianpu || song.score || "")
  ]);
}

function fallbackRemixCode(value) {
  const seeds = [2166136261, 2654435761, 2246822519];
  return seeds.map((seed) => {
    let hash = seed;
    for (const character of value) {
      hash ^= character.codePointAt(0);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, "0");
  }).join("").slice(0, REMIX_CODE_LENGTH);
}

async function remixCodeForSong(song) {
  const storedCode = normalizeStoredRemixCode(song.remixCode);
  if (storedCode) {
    song.remixCode = storedCode;
    return storedCode;
  }
  const payload = remixCodePayload(song);
  if (remixCodeCache.has(payload)) {
    song.remixCode = remixCodeCache.get(payload);
    return song.remixCode;
  }
  if (remixCodePending.has(payload)) {
    song.remixCode = await remixCodePending.get(payload);
    return song.remixCode;
  }
  const pending = (async () => {
    let code = "";
    if (globalThis.crypto?.subtle && globalThis.TextEncoder) {
      try {
        const digest = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(payload));
        code = Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("").slice(0, REMIX_CODE_LENGTH);
      } catch {
        code = fallbackRemixCode(payload);
      }
    } else {
      code = fallbackRemixCode(payload);
    }
    code = code.toUpperCase();
    remixCodeCache.set(payload, code);
    return code;
  })();
  remixCodePending.set(payload, pending);
  try {
    song.remixCode = await pending;
    return song.remixCode;
  } finally {
    remixCodePending.delete(payload);
  }
}

async function ensureRemixCodes() {
  const songs = [...SONG_LIBRARY, ...mySongLibrary];
  await Promise.all(songs.map((song) => remixCodeForSong(song)));
}

function remixCodeFromInput(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return { value: "", state: "empty" };
  let candidate = raw;
  try {
    const url = new URL(raw, window.location.href);
    if (url.searchParams.has("code")) candidate = url.searchParams.get("code") || "";
  } catch {}
  candidate = candidate.trim().toUpperCase();
  if (!REMIX_CODE_PATTERN.test(candidate)) return { value: candidate, state: "invalid" };
  return { value: candidate, state: "valid" };
}

function remixCodeSong(code) {
  return [...SONG_LIBRARY, ...mySongLibrary].find((song) => song.remixCode === code) || null;
}

// 未解锁的公共曲谱只能试听：不进编辑器、不给导出。载入前统一走这里判定。
function songUnlockState(song) {
  if (songAnalyticsOrigin(song) !== "community" || !song?.remixCode) return "free";
  if (!authState.available) return "free";
  // 服务器状态未确认（网络异常）时不拦；正常匿名会得到 401 并把 statusKnown 置真。
  if (!authState.account && !authState.statusKnown) return "free";
  const points = authState.account?.points;
  if (!authState.account) return "locked";
  if (points?.unlimited) return "free";
  if (points?.owned?.includes(song.remixCode) || points?.unlocked?.includes(song.remixCode)) return "free";
  return "locked";
}

// ============ 卡片试听（载入播放器，不改编辑器） ============
// 试听不再自己播一份：把曲目载入播放器（MONITOR.EXE）播放，编辑器与导出内容保持不变。

// 播放器当前的谱子来源：有卡片载入的曲目就用它，否则用编辑器内容。
function playerSourceSequence() {
  return playerSongSequence || currentSequence;
}

function playerSongPlaying() {
  return Boolean(activePreview && playerSongSequence && activePreview.sequence === playerSongSequence);
}

function updatePlayerSourceHint() {
  if (!elements.previewSource) return;
  elements.previewSource.hidden = !playerSongSequence;
  elements.previewSource.textContent = playerSongSequence
    ? `正在试听《${playerSongTitle}》· 播放器试听，不改动编辑器与导出内容。`
    : "";
}

function clearPlayerSong() {
  if (!playerSongSequence && !playerSongCode) return;
  playerSongSequence = null;
  playerSongCode = "";
  playerSongTitle = "";
  updatePlayerSourceHint();
  refreshCardPreviewButtons();
}

function refreshCardPreviewButtons() {
  const playing = playerSongPlaying();
  document.querySelectorAll("[data-song-action='preview']").forEach((button) => {
    const same = Boolean(playerSongCode) && button.closest("[data-remix-code]")?.dataset.remixCode === playerSongCode;
    button.textContent = same && playing ? "停止" : "试听";
    button.classList.toggle("is-playing", same && playing);
  });
  const dialogButton = elements.scoreUnlockPreview;
  if (dialogButton) {
    const same = Boolean(playerSongCode) && pendingUnlockRequest?.song?.remixCode === playerSongCode;
    dialogButton.textContent = same && playing ? "停止试听" : "试听";
    dialogButton.classList.toggle("is-playing", same && playing);
  }
}

// 曲目卡片与推送卡片共用：把曲目载入播放器，只更新播放面板、时间线与进度。
function songPreviewSequence(song) {
  const sourceText = song.jianpu ? String(song.sourceJianpu || song.jianpu || "") : String(song.score || "");
  const sequence = song.jianpu ? parseJianpu(sourceText, song.bpm) : parseScore(sourceText, song.bpm);
  if (sequence.error) return null;
  sequence.notes.forEach((item, index) => { item.index = index; });
  return sequence;
}

async function loadSongIntoPlayer(song) {
  const sequence = songPreviewSequence(song);
  if (!sequence) { toast(`《${song.title}》的曲库数据无法试听。`); return false; }
  playerSongSequence = sequence;
  playerSongCode = song.remixCode || "";
  playerSongTitle = song.title || "当前曲目";
  stopPreview();
  updateMonitor(sequence);
  updatePlayerSourceHint();
  refreshCardPreviewButtons();
  document.querySelector("#playback")?.scrollIntoView({ behavior: "smooth", block: "start" });
  await playPreview(0, { analytics: false });
  trackScoreAnalytics("preview_started", { origin: songAnalyticsOrigin(song) }, analyticsScoreIdForSong(song), song);
  return true;
}

async function toggleSongPreview(song) {
  const code = song.remixCode || "";
  if (code && playerSongCode === code && playerSongPlaying()) { stopPreview(); return; }
  await loadSongIntoPlayer(song);
}

// ============ 解锁确认弹窗 ============

function openScoreUnlockDialog(song, { destination = "editor" } = {}) {
  pendingUnlockRequest = { song, destination };
  const points = authState.account?.points;
  const cost = points?.rules?.unlock ?? 10;
  const balance = points?.unlimited ? "∞" : `${points?.balance ?? 0}`;
  elements.scoreUnlockTitle.textContent = `解锁《${song.title}》`;
  elements.scoreUnlockCopy.textContent = authState.account
    ? `这是社区曲谱，首次解锁消耗 ${cost} 积分（当前余额 ${balance}）。解锁后可永久载入编辑器与导出宏；解锁前可以先试听整曲。`
    : "这是社区曲谱，需要登录后用积分解锁才能载入编辑器（新账号自动获得 30 积分）。解锁前可以先试听整曲。";
  elements.scoreUnlockConfirm.querySelector("span").textContent = authState.account ? `解锁并载入 · ${cost} 积分` : "登录 / 注册";
  setAuthStatus(elements.scoreUnlockStatus);
  refreshCardPreviewButtons();
  if (!elements.scoreUnlockDialog.open) elements.scoreUnlockDialog.showModal();
}

async function confirmScoreUnlock() {
  const request = pendingUnlockRequest;
  if (!request) return;
  if (!authState.account) {
    elements.scoreUnlockDialog.close();
    showAuthDialog();
    return;
  }
  elements.scoreUnlockConfirm.disabled = true;
  setAuthStatus(elements.scoreUnlockStatus, "正在解锁…", true);
  try {
    const result = await authRequest("./api/points/unlock", { method: "POST", body: { remixCode: request.song.remixCode } });
    authState.account.points = result;
    renderPointsUi();
    elements.scoreUnlockDialog.close();
    renderSongLibrary(elements.songSearch.value);
    renderRecommendationBoard();
    if (result.charged) toast(`已解锁《${request.song.title}》，消耗 ${result.rules?.unlock ?? 10} 积分。`);
    loadSong(request.song, { destination: request.destination });
  } catch (error) {
    setAuthStatus(elements.scoreUnlockStatus, error.message || "解锁失败，请稍后重试。");
    if (error.status === 402) {
      trackAnalytics("points_insufficient");
      elements.scoreUnlockDialog.close();
      await refreshPointsUi();
      setAuthStatus(elements.pointsTaskStatus, "积分不足：完成下方任务即可获得积分。");
      if (!elements.pointsTaskDialog.open) elements.pointsTaskDialog.showModal();
    }
  } finally {
    elements.scoreUnlockConfirm.disabled = false;
  }
}

function remixCodeLink(code) {
  const url = new URL(window.location.href);
  url.search = "";
  url.searchParams.set("code", code);
  url.hash = "";
  return url.toString();
}

async function copyRemixCodeLink(code) {
  if (!code) return;
  const link = remixCodeLink(code);
  try {
    await navigator.clipboard.writeText(link);
    toast("改曲码链接已复制");
  } catch {
    toast("复制失败，请手动复制改曲码链接");
  }
}

function songsForLibraryView() {
  if (activeLibraryView === "recommended") {
    return recommendedSongIdentities
      .map((identity) => SONG_LIBRARY.find((song) => recommendationKey(song) === recommendationKey(identity)))
      .filter(Boolean);
  }
  if (activeLibraryView === "hot") {
    return [...SONG_LIBRARY]
      .filter((song) => hotScoreRanks.has(analyticsScoreIdForSong(song)))
      .sort((left, right) => (hotScoreRanks.get(analyticsScoreIdForSong(left)) || Number.MAX_SAFE_INTEGER)
        - (hotScoreRanks.get(analyticsScoreIdForSong(right)) || Number.MAX_SAFE_INTEGER)
        || compareLibrarySongs(left, right))
      .slice(0, 10);
  }
  const songs = activeLibraryView === "mine" ? mySongLibrary : SONG_LIBRARY;
  return activeLibraryView === "all"
    ? [...songs].sort(compareLibrarySongsByCreation)
    : [...songs].sort(compareLibrarySongs);
}

function scoreExportCount(song) {
  return scoreExportCounts.get(analyticsScoreIdForSong(song)) || 0;
}

function songActionCount(song) {
  const bpm = Number(song.bpm) || 120;
  const source = String(song.sourceJianpu || song.jianpu || song.score || "");
  if (!source.trim()) return 0;
  const sequence = song.jianpu || song.sourceJianpu ? parseJianpu(source, bpm) : parseScore(source, bpm);
  return sequence?.error ? 0 : sequence?.events || 0;
}

function compareLibrarySongs(left, right) {
  return LIBRARY_TITLE_COLLATOR.compare(left.title, right.title)
    || LIBRARY_TITLE_COLLATOR.compare(left.artist, right.artist)
    || LIBRARY_TITLE_COLLATOR.compare(left.sharedBy, right.sharedBy);
}

function compareLibrarySongsByCreation(left, right) {
  const leftCreatedAt = Date.parse(left.createdAt || "");
  const rightCreatedAt = Date.parse(right.createdAt || "");
  const leftHasCreatedAt = Number.isFinite(leftCreatedAt);
  const rightHasCreatedAt = Number.isFinite(rightCreatedAt);
  if (leftHasCreatedAt && rightHasCreatedAt && leftCreatedAt !== rightCreatedAt) return rightCreatedAt - leftCreatedAt;
  if (leftHasCreatedAt !== rightHasCreatedAt) return rightHasCreatedAt ? 1 : -1;
  return SONG_LIBRARY.indexOf(left) - SONG_LIBRARY.indexOf(right);
}

function songLibraryIndex(song) {
  return SONG_LIBRARY.findIndex((candidate) => candidate.title === song.title && candidate.artist === song.artist && candidate.sharedBy === song.sharedBy);
}

function renderSongCard(song, { libraryView = activeLibraryView } = {}) {
  const index = songLibraryIndex(song);
  // 共享人挂了 ID 特效时，卡片底部那个"共享：xxx"的框也一起换风格。
  const sharedByEffect = String(song.sharedBy || "").trim() ? userIdEffectValue(song.sharedBy) : "default";
  const sponsor = String(song.sponsor || "").trim();
  const sponsorEffect = sponsor ? userIdEffectValue(sponsor) : "default";
  const isRecommended = recommendedSongKeys.has(recommendationKey(song));
  const canManageRecommendations = Boolean(authState.account?.isAdmin);
  const recommendationAction = isRecommended ? "unrecommend" : "recommend";
  const recommendationLabel = isRecommended ? "取消推荐" : "推荐";
  const needsPoints = songAnalyticsOrigin(song) === "community" && Boolean(song.remixCode);
  const unlocked = authState.account?.points?.unlocked?.includes(song.remixCode);
  const owned = authState.account?.points?.owned?.includes(song.remixCode);
  const priceLabel = needsPoints ? (owned ? "我的谱子·免费" : unlocked ? "已解锁" : authState.account?.points?.unlimited ? "无限使用" : "首次 10 积分") : "";
  // 正在播放器里试听这首曲目时，卡片按钮显示「停止」。
  const previewPlaying = Boolean(playerSongCode) && playerSongCode === (song.remixCode || "") && playerSongPlaying();
  return `
    <article class="song-card" data-song-index="${index}" data-remix-code="${escapeHtml(song.remixCode || "")}" data-index="${String(index + 1).padStart(2, "0")}">
      <div class="song-card-main" data-song-action="card-export-copy-remix" role="button" tabindex="0" aria-label="导出《${escapeHtml(song.title)}》并复制改曲码链接">
      <span class="song-number">TRACK ${String(index + 1).padStart(2, "0")}</span>
      <div class="song-title-row"><h3>${escapeHtml(song.title)}</h3>${song.displayUrl ? `<a class="song-showcase-link" href="${escapeHtml(song.displayUrl)}" target="_blank" rel="noopener noreferrer">展示视频 <span aria-hidden="true">↗</span></a>` : ""}</div>
      <p class="song-artist"><span class="song-artist-link" data-song-action="search-artist" data-artist="${escapeHtml(song.artist)}" title="在曲库中查看这位作者的作品">${escapeHtml(song.artist)}</span></p>
      <div class="song-meta"><div class="song-meta-primary"><span>${escapeHtml(song.key)}</span><span>${escapeHtml(song.meter)}</span><span>${escapeHtml(song.bpm)} BPM</span><span class="song-action-count" title="脚本执行的键盘/鼠标动作总数">动作 ${song.actionCount ?? songActionCount(song)} 次</span>${priceLabel ? `<span class="song-points-label">${priceLabel}</span>` : ""}</div><span class="song-export-count" title="统计周期内总导出量">导出 ${song.exportCount ?? scoreExportCount(song)}</span></div>
      ${song.declaration ? `<p class="song-declaration" title="上传者声明">声明：${escapeHtml(song.declaration)}</p>` : ""}
      </div>
      <div class="song-card-footer"><button class="song-share${sharedByEffect === "default" ? "" : ` song-share--${sharedByEffect}`}" data-song-action="search-sharer" type="button" title="在曲库中查看这位共享人的作品" aria-label="在曲库中查看共享人 ${escapeHtml(song.sharedBy)} 的作品">共享：${userIdMarkup(song.sharedBy)}</button>${sponsor ? `<button class="song-share song-sponsor${sponsorEffect === "default" ? "" : ` song-share--${sponsorEffect}`}" data-song-action="search-sponsor" type="button" title="在曲库中查看这位赞助人的作品" aria-label="在曲库中查看赞助人 ${escapeHtml(sponsor)} 的作品">赞助人：${userIdMarkup(sponsor)}</button>` : ""}${song.remixCode ? `<button class="song-remix-code" data-song-action="copy-remix-code" data-remix-code="${escapeHtml(song.remixCode)}" type="button" title="复制改曲码链接" aria-label="复制《${escapeHtml(song.title)}》的改曲码链接"><span>${escapeHtml(song.remixCode)}</span><span class="song-remix-copy-icon" aria-hidden="true">⧉</span></button>` : ""}</div>
      <div class="song-card-actions" aria-label="曲目操作">
        <div class="song-card-actions-main">
          <button class="song-card-action" data-song-action="view" type="button">查看</button>
          ${needsPoints ? `<button class="song-card-action preview${previewPlaying ? " is-playing" : ""}" data-song-action="preview" type="button">${previewPlaying ? "停止" : "试听"}</button>` : ""}
          ${libraryView === "mine" ? '<button class="song-card-action edit" data-song-action="edit" type="button">编辑</button>' : ""}
          <button class="song-card-action export" data-song-action="export" type="button">导出</button>
          ${libraryView === "mine" ? '<button class="song-card-action delete" data-song-action="delete" type="button">删除</button>' : ""}
          ${canManageRecommendations ? `<button class="song-card-action recommendation-action${isRecommended ? " is-recommended" : ""}" data-song-action="${recommendationAction}" type="button">${recommendationLabel}</button>` : ""}
        </div>
      </div>
    </article>
  `;
}

function renderSongLibrary(query = "") {
  const sourceSongs = songsForLibraryView();
  elements.libraryCount.textContent = `${sourceSongs.length} TRACK${sourceSongs.length === 1 ? "" : "S"}`;
  const normalizedQuery = query.trim().toLocaleLowerCase();
  const songs = sourceSongs.map((song) => ({ ...song, index: songLibraryIndex(song), exportCount: scoreExportCount(song), actionCount: songActionCount(song) })).filter((song) => `${song.title} ${song.artist} ${song.sharedBy} ${song.sponsor || ""} ${song.key} ${song.meter} ${song.bpm} ${song.actionCount} ${song.remixCode || ""}`.toLocaleLowerCase().includes(normalizedQuery));
  if (activeLibraryView === "mine" && !authState.account) {
    elements.songGrid.innerHTML = '<p class="library-empty">登录后查看当前账号上传的曲目。<button class="library-empty-action" data-library-login type="button">登录</button></p>';
    return;
  }
  if (songs.length) {
    elements.songGrid.innerHTML = songs.map((song) => renderSongCard(song)).join("");
    return;
  }
  if (normalizedQuery) {
    elements.songGrid.innerHTML = '<p class="library-empty library-empty--search">没有找到匹配的曲目。<span>你可以成为第一个上传人。</span><button class="library-empty-action" data-library-upload type="button">去编辑器上传</button></p>';
    return;
  }
  elements.songGrid.innerHTML = '<p class="library-empty">当前分类暂无曲目。</p>';
}

// 推荐板块：第一排从管理员推荐名单中随机抽取，第二排从全部曲库中随机抽取且不与第一排重复。
const RECOMMENDATION_BOARD_MAX_PICKS = 4;
const RECOMMENDATION_BOARD_CARD_MIN_WIDTH = 232;
const RECOMMENDATION_BOARD_CARD_GAP = 10;
let recommendationBoardRowSize = 0;
let recommendationBoardReflowTimer = 0;

function recommendedSongsForBoard() {
  const songs = [];
  const seen = new Set();
  recommendedSongIdentities.forEach((identity) => {
    const key = recommendationKey(identity);
    if (seen.has(key)) return;
    const song = SONG_LIBRARY.find((candidate) => recommendationKey(candidate) === key);
    if (!song) return;
    seen.add(key);
    songs.push(song);
  });
  return songs;
}

function uniqueSongsByKey(songs) {
  const seen = new Set();
  return songs.filter((song) => {
    const key = recommendationKey(song);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function sampleSongs(songs, count, excludedKeys = new Set()) {
  const pool = uniqueSongsByKey(songs).filter((song) => !excludedKeys.has(recommendationKey(song)));
  for (let index = pool.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [pool[index], pool[swapIndex]] = [pool[swapIndex], pool[index]];
  }
  return pool.slice(0, Math.max(0, count));
}

// 每排展示数量跟随 .recommendation-row 的 auto-fill 列数，避免卡片折行。
function recommendationBoardPickCount() {
  const width = elements.recommendationPrimaryRow?.clientWidth || elements.recommendationSecondaryRow?.clientWidth || window.innerWidth;
  return Math.max(1, Math.min(RECOMMENDATION_BOARD_MAX_PICKS, Math.floor((width + RECOMMENDATION_BOARD_CARD_GAP) / (RECOMMENDATION_BOARD_CARD_MIN_WIDTH + RECOMMENDATION_BOARD_CARD_GAP))));
}

function scheduleRecommendationBoardReflow() {
  window.clearTimeout(recommendationBoardReflowTimer);
  recommendationBoardReflowTimer = window.setTimeout(() => {
    if (recommendationBoardPickCount() !== recommendationBoardRowSize) renderRecommendationBoard();
  }, 220);
}

function renderRecommendationBoard() {
  const primaryRow = elements.recommendationPrimaryRow;
  const secondaryRow = elements.recommendationSecondaryRow;
  if (!primaryRow || !secondaryRow) return;
  const pickCount = recommendationBoardPickCount();
  recommendationBoardRowSize = pickCount;
  const recommendedPool = recommendedSongsForBoard();
  const primaryPicks = sampleSongs(recommendedPool, pickCount);
  const primaryKeys = new Set(primaryPicks.map(recommendationKey));
  const secondaryPicks = sampleSongs(SONG_LIBRARY, pickCount, primaryKeys);
  primaryRow.innerHTML = primaryPicks.length
    ? primaryPicks.map((song) => renderSongCard(song, { libraryView: "board" })).join("")
    : '<p class="library-empty">推荐名单还没有曲目。管理员可以在曲库中把喜欢的曲目加入推荐。</p>';
  secondaryRow.innerHTML = secondaryPicks.length
    ? secondaryPicks.map((song) => renderSongCard(song, { libraryView: "board" })).join("")
    : '<p class="library-empty">曲库暂时没有可以抽取的曲目。</p>';
  if (elements.recommendationStatus) {
    elements.recommendationStatus.textContent = `推荐池 ${recommendedPool.length} 首 · 曲库 ${SONG_LIBRARY.length} 首`;
  }
}

async function refreshLibraryViews() {
  await ensureRemixCodes();
  renderSongLibrary(elements.songSearch.value);
  renderRecommendationBoard();
}

function applyRemixCodeFromUrl() {
  const url = new URL(window.location.href);
  const parsed = remixCodeFromInput(url.searchParams.get("code") || "");
  if (parsed.state !== "valid") return;
  elements.songSearch.value = parsed.value;
  setLibraryView("all");
  window.requestAnimationFrame(() => window.requestAnimationFrame(() => {
    document.querySelector("#library")?.scrollIntoView({ behavior: "auto", block: "start" });
    elements.songSearch.focus({ preventScroll: true });
  }));
}

function beatsToJianpu(beats) {
  const known = new Map([[0.25, "__"], [0.375, "__."], [0.5, "_"], [0.75, "_."], [1, ""], [1.5, "."], [1.75, ".."], [2, "-"], [2.5, ".-"], [3, "--"], [4, "---"]]);
  return known.get(beats) ?? `:${formatRecordedBeat(beats)}`;
}

function jianpuPitch(note, modifier) {
  if (note === "0") return "0";
  if (note === "1'" && modifier && (modifier.includes("L") || modifier.includes("R"))) return `${modifier}${note}`;
  return modifier === "LM" || modifier === "ML" ? `#,${note}` : modifier === "RM" || modifier === "MR" ? `#${note}'` : modifier === "M" ? `#${note}` : modifier === "L" ? `,${note}` : modifier === "R" ? `${note}'` : note;
}

function preciseToJianpu(source) {
  return source.split("\n").map((line) => line.split(/\s+/).filter(Boolean).map((token) => {
    if (token === "|") return token;
    const found = token.match(/^([LMR]{0,2})(0|1'|[1-7])\/(\d+(?:\.\d+)?)$/i);
    if (!found) return token;
    const modifier = found[1].toUpperCase();
    const note = found[2];
    const beats = Number(found[3]);
    const pitch = jianpuPitch(note, modifier);
    const rhythm = beatsToJianpu(beats);
    return `${pitch}${rhythm}`;
  }).join(" ")).join("\n");
}

function serializeSequence(sequence, formatItem) {
  const lines = [];
  sequence.notes.forEach((item) => {
    const lineIndex = Math.max(0, (item.line || 1) - 1);
    if (!lines[lineIndex]) lines[lineIndex] = [];
    lines[lineIndex].push(formatItem(item));
  });
  return lines.filter(Boolean).map((line) => `${line.join(" ")} |`).join("\n");
}

function sequenceToPrecise(sequence) {
  return serializeSequence(sequence, (item) => `${item.modifier || ""}${item.note}/${formatRecordedBeat(item.beats)}`);
}

function standardJianpuPitch(item) {
  if (item.note === "0") return "0";
  const midi = Number.isFinite(item.midi) ? item.midi : macroMidi(item);
  if (!Number.isFinite(midi)) return jianpuPitch(item.note, item.modifier);
  const candidates = [];
  ["", "#", "b"].forEach((accidental) => {
    ["", "'", "''", ",", ",,"].forEach((octaveMark) => {
      for (let digit = 1; digit <= 7; digit += 1) {
        const candidate = encodeJianpuPitch(accidental, octaveMark.startsWith(",") ? octaveMark : "", String(digit), octaveMark.startsWith("'") ? octaveMark : "");
        if (candidate?.midi !== midi) continue;
        // Keep repeated octave marks.  A double high mark is a real playable
        // pitch (for example 1''), and dropping one here changes the exported
        // note by an entire octave after MIDI import or transposition.
        const text = `${accidental}${octaveMark.startsWith(",") ? octaveMark : ""}${digit}${octaveMark.startsWith("'") ? octaveMark : ""}`;
        candidates.push({ text, score: (accidental ? 1 : 0) + (octaveMark ? 1 : 0) });
      }
    });
  });
  candidates.sort((left, right) => left.score - right.score || left.text.localeCompare(right.text));
  return candidates[0]?.text || jianpuPitch(item.note, item.modifier);
}

function sequenceToJianpu(sequence) {
  return serializeSequence(sequence, (item) => `${item.sourcePitch || standardJianpuPitch(item)}${beatsToJianpu(item.beats)}`);
}

function uploadCompatibilityIssue(sequence) {
  const item = sequence?.notes?.find((candidate) => candidate.physicalSourcePitch && candidate.note === "1'" && /[LR]/.test(candidate.modifier || ""));
  if (!item) return null;
  const token = jianpuPitch(item.note, item.modifier);
  const legacyHint = token === "R1'" ? "；如果这是旧文件由 #7' 产生的，请改回 #7'" : "";
  return {
    message: `${token} 是物理键位写法，可试听和导出宏，但暂不支持曲库上传${legacyHint}。`,
    line: item.line || 1,
    column: item.column || 1
  };
}

function editorForMode(mode = inputMode) {
  return {
    jianpu: elements.jianpuScore,
    record: elements.recordedScore,
    precise: elements.score,
    keyboard: elements.keyboardScore
  }[mode] || null;
}

function parseEditorSource(source, bpm, mode = inputMode) {
  if (mode === "jianpu") return parseJianpu(source, bpm);
  if (mode === "keyboard") return parseKeyboardScore(source, bpm);
  return parseScore(source, bpm);
}

function formatNoteForMode(item, mode) {
  if (mode === "jianpu") return `${item.sourcePitch || standardJianpuPitch(item)}${beatsToJianpu(item.beats)}`;
  if (mode === "keyboard") return `${keyboardLabel(item)} / ${item.durationMs}ms`;
  return `${item.modifier || ""}${item.note}/${formatRecordedBeat(item.beats)}`;
}

function sequenceToMode(sequence, mode) {
  if (mode === "keyboard") return sequenceToKeyboard(sequence);
  return serializeSequence(sequence, (item) => formatNoteForMode(item, mode));
}

function isIgnorableMixedToken(token, isLinePrefix = false) {
  if (/^(?:\d{1,2})\/(?:1|2|4|8|16)$/.test(token)) return isLinePrefix && Number(token.split("/")[0]) > 1;
  return /^(?:\|+|\|\|:|:\|\||:|\(|\)|\[|\]|\{|\}|[1-7]=[A-G](?:[#b♯♭])?|(?:♩|♪)=?\d+)$/i.test(token);
}

function parseMixedFragment(fragment, start, line, column, bpm, preferredMode) {
  const modes = [preferredMode, "jianpu", "record", "precise", "keyboard"].filter((mode, index, all) => all.indexOf(mode) === index);
  for (const mode of modes) {
    const parsed = parseEditorSource(fragment, bpm, mode);
    if (parsed.error || !parsed.notes?.length) continue;
    return parsed.notes.map((item) => ({ ...item, start, line, column }));
  }
  return null;
}

function parseMixedEditorSource(source, bpm, preferredMode) {
  const notes = [];
  const invalid = [];
  const repairedLines = [];
  const lines = source.split("\n");
  lines.forEach((rawLine, lineIndex) => {
    const line = lineIndex + 1;
    const trimmed = rawLine.trim();
    if (!trimmed) {
      repairedLines.push(rawLine);
      return;
    }

    const keyboard = parseEditorSource(trimmed, bpm, "keyboard");
    if (!keyboard.error && keyboard.notes?.length && /\/\s*\d+\s*ms\s*$/i.test(trimmed)) {
      const column = rawLine.indexOf(trimmed) + 1;
      const rebased = keyboard.notes.map((item) => ({ ...item, line, column, start: rawLine.indexOf(trimmed) }));
      notes.push(...rebased);
      repairedLines.push(formatNoteForMode(rebased[0], preferredMode));
      return;
    }

    const tokenMatches = [...rawLine.matchAll(/\S+/g)];
    const repairedTokens = [];
    tokenMatches.forEach((match) => {
      const token = match[0];
      if (isIgnorableMixedToken(token, match.index === rawLine.search(/\S/))) {
        repairedTokens.push(token);
        return;
      }
      const parsed = parseMixedFragment(token, match.index, line, match.index + 1, bpm, preferredMode);
      if (!parsed) {
        repairedTokens.push(token);
        invalid.push({ token, line, column: match.index + 1 });
        return;
      }
      notes.push(...parsed);
      repairedTokens.push(parsed.map((item) => formatNoteForMode(item, preferredMode)).join(" "));
    });
    repairedLines.push(repairedTokens.join(" "));
  });
  return { notes, invalid, repairedText: repairedLines.join("\n") };
}

function applyRepairedSequence(sequence, mode, { currentText = null } = {}) {
  sequence.notes.forEach((item, index) => { item.index = index; });
  clearPlayerSong();
  currentSequence = sequence;
  syncSequenceToEditors(sequence, { except: mode });
  const editor = editorForMode(mode);
  if (editor) editor.value = currentText ?? sequenceToMode(sequence, mode);
  updateLineNumbers();
  updateMonitor(sequence);
  updateTransposeControls(sequence);
  elements.status.textContent = "序列已就绪";
}

function setRepairValidation(sequence, invalid = []) {
  const uploadIssue = suppressUploadCompatibilityWarning ? null : uploadCompatibilityIssue(sequence);
  const invalidMessage = invalid.length
    ? `保留无法识别内容：${invalid.map((item) => `${item.token}（${item.line}:${item.column}）`).join("、")}。请修正后再导出或上传。`
    : "";
  const compatibilityMessage = uploadIssue
    ? `校验提醒 · 第 ${uploadIssue.line} 行，第 ${uploadIssue.column} 列：${uploadIssue.message}`
    : "";
  const messages = [invalidMessage, compatibilityMessage].filter(Boolean);
  setValidation(messages.length
    ? `试验性修复完成 · ${messages.join(" ")}`
    : `试验性修复完成 · 已按${MODE_LABELS[inputMode]}同步四种谱子。`, messages.length ? "warning" : "success");
  return messages.length;
}

function repairCurrentMode() {
  const editor = editorForMode();
  if (!editor) return;
  const source = editor.value;
  const bpm = Number(elements.bpm.value);
  const strict = parseEditorSource(source, bpm, inputMode);
  if (!strict.error && strict.notes?.length) {
    applyRepairedSequence(strict, inputMode);
    const hasWarning = setRepairValidation(strict);
    toast(hasWarning ? "已修复当前曲谱，但仍有上传兼容性提醒。" : `已按${MODE_LABELS[inputMode]}修复并同步当前曲谱。`);
    return;
  }

  const mixed = parseMixedEditorSource(source, bpm, inputMode);
  if (!mixed.notes.length) {
    setValidation(`试验性修复失败 · ${strict.error?.message || "没有找到可转换的谱子内容。"}`, "error");
    toast("没有找到可修复的谱子内容。 ");
    return;
  }
  const sequence = enrichNotes(mixed.notes, bpm);
  if (sequence.error) {
    setValidation(`试验性修复失败 · ${sequence.error.message}`, "error");
    return;
  }
  applyRepairedSequence(sequence, inputMode, { currentText: mixed.repairedText });
  const hasWarning = setRepairValidation(sequence, mixed.invalid);
  toast(hasWarning ? `已修复可识别内容，仍有 ${mixed.invalid.length ? `${mixed.invalid.length} 项需要手动处理` : "上传兼容性问题"}。` : `已按${MODE_LABELS[inputMode]}修复并同步当前曲谱。`);
}

function keyboardLabel(item) {
  if (item.isRest) return "等待";
  const modifiers = [...(item.modifier || "")].map((modifier) => KEYBOARD_MODIFIER_LABELS[modifier]);
  return [...modifiers, item.key.toUpperCase()].join(" + ");
}

function sequenceToKeyboard(sequence) {
  return sequence.notes.map((item) => `${keyboardLabel(item)} / ${item.durationMs}ms`).join("\n");
}

function syncSequenceToEditors(sequence, { except = null, sourceMode = null, sourceText = "" } = {}) {
  if (except !== "jianpu") elements.jianpuScore.value = sourceMode === "jianpu" ? sourceText : sequenceToJianpu(sequence);
  const precise = sequenceToPrecise(sequence);
  if (except !== "precise") elements.score.value = sourceMode === "precise" ? sourceText : precise;
  if (except !== "record") elements.recordedScore.value = sourceMode === "precise" ? sourceText : precise;
  if (except !== "keyboard") elements.keyboardScore.value = sequenceToKeyboard(sequence);
  updateLineNumbers();
  resetScoreHistory();
}

function loadSong(song, { destination = "editor", scroll = true, focusEditor = true, analytics = true, editMode = false } = {}) {
  // 门禁：未解锁的社区曲谱不进编辑器，改为弹解锁确认（可先试听）。
  if (!editMode && songUnlockState(song) === "locked") {
    openScoreUnlockDialog(song, { destination });
    return;
  }
  clearPlayerSong();
  stopPreview();
  finishRecording({ apply: false });
  lastMidiFile = null;
  resetMidiTrackPicker();
  suppressUploadCompatibilityWarning = song.title === "口琴按键映射测试";
  elements.macroName.value = song.title;
  elements.artistName.value = song.artist || "";
  elements.keySignature.value = song.key || "1=C";
  elements.timeSignature.value = song.meter || "4/4";
  elements.bpm.value = song.bpm;
  currentScoreEditMode = Boolean(editMode);
  currentScoreCredit = { artist: song.artist || "", sharedBy: song.sharedBy || "", displayUrl: song.displayUrl || "", declaration: song.declaration || "", remixCode: editMode ? normalizeStoredRemixCode(song.remixCode) : "" };
  activeAnalyticsScoreOrigin = songAnalyticsOrigin(song);
  currentPublicScoreCode = activeAnalyticsScoreOrigin === "community" ? normalizeStoredRemixCode(song.remixCode) : "";
  activeAnalyticsScoreId = analyticsScoreIdForSong(song, activeAnalyticsScoreOrigin);
  const sourceMode = song.jianpu ? "jianpu" : song.score ? "precise" : null;
  const sourceText = sourceMode === "jianpu" ? String(song.sourceJianpu || song.jianpu || "") : String(song.score || "");
  const sequence = sourceMode === "jianpu" ? parseJianpu(sourceText, song.bpm) : parseScore(sourceText, song.bpm);
  if (sequence.error) {
    toast(`《${song.title}》的曲库数据无法载入。`);
    return;
  }
  sequence.notes.forEach((item, index) => { item.index = index; });
  syncSequenceToEditors(sequence, { sourceMode, sourceText });
  [elements.jianpuScore, elements.score, elements.recordedScore, elements.keyboardScore].forEach((editor) => { editor.scrollTop = 0; });
  elements.jianpuLineNumbers.scrollTop = 0;
  elements.lineNumbers.scrollTop = 0;
  elements.keyboardLineNumbers.scrollTop = 0;
  setInputMode(song.inputMode || "jianpu", { force: true, silent: true });
  if (focusEditor) elements.jianpuScore.focus({ preventScroll: !scroll });
  syncLineNumbers(elements.jianpuScore, elements.jianpuLineNumbers);
  if (scroll && destination === "export") elements.macroExportSection.scrollIntoView({ behavior: "smooth", block: "start" });
  else if (scroll) document.querySelector(".workbench")?.scrollIntoView({ behavior: "smooth", block: "start" });
  if (analytics) trackScoreAnalytics("song_loaded", { origin: songAnalyticsOrigin(song) }, activeAnalyticsScoreId, song);
  if (analytics && destination === "export") trackAnalytics("macro_section_opened");
  toast(`已载入《${song.title}》· ${song.bpm} BPM。`);
}

function initializeBlankEditor() {
  stopPreview();
  clearPlayerSong();
  finishRecording({ apply: false });
  lastMidiFile = null;
  resetMidiTrackPicker();
  currentSequence = null;
  currentScoreCredit = { artist: "", sharedBy: "", displayUrl: "", declaration: "", remixCode: "" };
  currentScoreEditMode = false;
  activeAnalyticsScoreOrigin = "editor";
  currentPublicScoreCode = "";
  activeAnalyticsScoreId = "";
  suppressUploadCompatibilityWarning = false;
  elements.macroName.value = "自定义曲目";
  elements.artistName.value = "";
  elements.keySignature.value = "1=C";
  elements.timeSignature.value = "4/4";
  elements.bpm.value = "120";
  [elements.jianpuScore, elements.score, elements.recordedScore, elements.keyboardScore].forEach((editor) => {
    editor.value = "";
    editor.scrollTop = 0;
  });
  updateLineNumbers();
  updateMonitor(null);
  updateTransposeControls(null);
  elements.status.textContent = "等待输入";
  setValidation("等待输入");
  resetScoreHistory();
}

const MODE_LABELS = { jianpu: "简谱模式", record: "录制模式", precise: "精确模式", keyboard: "三角洲键盘模式" };

function setInputMode(mode, { force = false, silent = false } = {}) {
  if (!MODE_LABELS[mode]) return false;
  if (mode === inputMode && !force) return true;
  if (inputMode === "record" && mode !== "record" && recording) finishRecording({ apply: true });
  stopPreview();
  if (!force) {
    const sequence = convert();
    if (!sequence) {
      toast("当前谱子有错误，修正后才能切换模式。");
      return false;
    }
    syncSequenceToEditors(sequence, { except: inputMode });
  }
  inputMode = mode;
  elements.inputPanes.forEach((pane) => { pane.hidden = pane.dataset.inputPane !== mode; });
  elements.inputModeButtons.forEach((button) => {
    const active = button.dataset.inputMode === mode;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
  });
  if (!silent) trackAnalytics("input_mode_selected", { mode });
  const sequence = convert();
  if (sequence) elements.status.textContent = `已同步 · ${MODE_LABELS[mode]}`;
  if (!silent && sequence) toast(`已转换为${MODE_LABELS[mode]}，曲谱内容保持同步。`);
  return Boolean(sequence);
}

function formatRecordedBeat(value) {
  const rounded = Math.round(Number(value) * 1000000) / 1000000;
  return Number.isInteger(rounded) ? String(rounded) : String(rounded).replace(/0+$/, "").replace(/\.$/, "");
}

function quantizeRecordedBeat(rawBeat) {
  const safeBeat = Math.max(0.1, Math.min(4, rawBeat));
  return RECORD_BEATS.reduce((closest, candidate) => Math.abs(candidate - safeBeat) < Math.abs(closest - safeBeat) ? candidate : closest, RECORD_BEATS[0]);
}

function updateRecordUi() {
  const isRecording = Boolean(recording);
  const count = recording?.events.length || 0;
  const holding = Boolean(recording?.activePress);
  elements.recordToggle.classList.toggle("live", isRecording);
  elements.recordToggle.querySelector("span").textContent = isRecording ? "完成并写入谱子" : "开始录制";
  elements.recordState.textContent = isRecording ? "RECORDING" : "IDLE";
  elements.recordState.classList.toggle("live", isRecording);
  elements.recordCount.textContent = isRecording ? `已录入 ${count} 个音符${holding ? " · 正在按住" : ""}` : "尚未录入音符";
}

function beginRecording() {
  stopPreview();
  releaseLiveRecordingVoice();
  recording = { events: [], startedAt: performance.now(), activePress: null };
  updateRecordUi();
  toast("录制开始：按住 Z–M、, 或页面琴键；松开即结束，直接按下一音会自动切换。 ");
}

function scoreFromRecording(events, bpm) {
  const beatMs = 60000 / bpm;
  const durations = events.map((event) => quantizeRecordedBeat((event.durationMs || beatMs * 0.25) / beatMs));
  const tokens = events.map((event, index) => `${event.modifier}${event.note}/${formatRecordedBeat(durations[index])}`);
  return tokens.reduce((lines, token, index) => {
    const lineIndex = Math.floor(index / 8);
    lines[lineIndex] = lines[lineIndex] ? `${lines[lineIndex]} ${token}` : token;
    return lines;
  }, []).join("\n");
}

function finishRecording({ apply = true } = {}) {
  if (!recording) return;
  finishActiveRecordPress();
  const captured = recording.events;
  releaseLiveRecordingVoice();
  recording = null;
  updateRecordUi();
  if (!apply) return;
  if (!captured.length) { toast("未录到音符，原谱子没有改动。 "); return; }
  elements.recordedScore.value = scoreFromRecording(captured, Number(elements.bpm.value));
  updateLineNumbers();
  const sequence = convert();
  if (sequence) {
    syncSequenceToEditors(sequence, { except: "record" });
    toast(`已写入 ${captured.length} 个音符，并同步到全部模式。`);
  }
  elements.recordedScore.focus();
}

function flashRecordedKey(note) {
  const button = [...elements.recordKeyboard.querySelectorAll("[data-record-note]")].find((key) => key.dataset.recordNote === note);
  if (!button) return;
  button.classList.add("hit");
  window.setTimeout(() => button.classList.remove("hit"), 125);
}

function finishActiveRecordPress(at = performance.now(), { releaseAudio = true } = {}) {
  if (!recording?.activePress) return;
  const event = recording.activePress;
  event.durationMs = Math.max(1, at - event.at);
  recording.activePress = null;
  if (releaseAudio) releaseLiveRecordingVoice();
  updateRecordUi();
}

function startRecordingNote(note, source) {
  if (!recording) { toast("请先点击“开始录制”。 "); return; }
  if (recording.activePress?.source === source) return;
  const now = performance.now();
  finishActiveRecordPress(now, { releaseAudio: false });
  const event = { note, modifier: selectedRecordModifier, at: now, source, durationMs: 0 };
  recording.events.push(event);
  recording.activePress = event;
  playLiveRecordingNote(note);
  flashRecordedKey(note);
  updateRecordUi();
}

function endRecordingNote(source) {
  if (recording?.activePress?.source !== source) return;
  finishActiveRecordPress();
}

function setValidation(message, type = "") {
  elements.validation.textContent = message;
  elements.validation.className = `validation ${type}`;
}

function setPreviewProgress(positionMs = 0, sequence = playerSourceSequence()) {
  const totalMs = sequence?.totalMs || 0;
  const safePosition = Math.max(0, Math.min(totalMs, Math.round(positionMs)));
  previewCursorMs = safePosition;
  elements.previewProgress.max = totalMs;
  elements.previewProgress.value = safePosition;
  elements.previewProgress.disabled = !totalMs;
  elements.previewProgressLabel.textContent = `${formatTime(safePosition)} / ${totalMs ? formatTime(totalMs) : "--:--.---"}`;
}

function highlightTimelinePosition(positionMs, { scroll = false } = {}) {
  const sequence = playerSourceSequence();
  if (!sequence) return;
  const index = timelineNoteIndexAt(sequence, positionMs);
  setTimelinePlaybackPosition(sequence, index, { scroll });
}

function timelineNoteIndexAt(sequence, positionMs) {
  if (!sequence?.notes?.length) return -1;
  const safePosition = Math.max(0, Math.min(sequence.totalMs, Number(positionMs) || 0));
  const index = sequence.notes.findIndex((item) => safePosition >= item.timeMs && safePosition < item.timeMs + item.durationMs);
  // Keep the final note selected when the cursor reaches the end of the range.
  return index >= 0 ? index : safePosition >= sequence.totalMs ? sequence.notes.length - 1 : -1;
}

function updateMonitor(sequence) {
  if (!sequence) {
    elements.totalTime.textContent = "--:--.---";
    elements.noteCount.textContent = "--";
    elements.eventCount.textContent = "--";
    elements.beatMs.textContent = "-- MS / BEAT";
    elements.timeline.innerHTML = '<li class="empty-state">转换后将在这里显示每个音符的按键时刻。</li>';
    setPreviewProgress(0, null);
    return;
  }
  elements.totalTime.textContent = formatTime(sequence.totalMs);
  elements.noteCount.textContent = sequence.notes.length;
  elements.eventCount.textContent = sequence.events;
  elements.beatMs.textContent = `${sequence.beatMs} MS / BEAT`;
  elements.timeline.innerHTML = sequence.notes.map((item) => {
    const modifier = item.modifier ? `${item.modifier} + ` : "";
    const modifierLead = item.inputLeadMs ? `变调准备 ${item.inputLeadMs}ms · ` : "";
    const keyHoldMs = Math.max(0, item.pressMs - (item.inputLeadMs || 0));
    const detail = item.isRest ? `休止 ${item.durationMs}ms` : `${modifier}${item.key.toUpperCase()} · ${modifierLead}按住 ${keyHoldMs}ms${item.waitMs ? ` · 气口 ${item.waitMs}ms` : ""}`;
    return `<li data-note-index="${item.index ?? 0}" data-time-ms="${item.timeMs}" tabindex="0" role="button" aria-label="跳转到 ${formatTime(item.timeMs)}，${escapeHtml(detail)}"><span class="time">${formatTime(item.timeMs)}</span><span class="timeline-key${item.isRest ? " rest" : item.modifier ? " modifier" : ""}">${item.isRest ? "休" : item.note}</span><span class="event-detail">${detail}</span></li>`;
  }).join("");
  setPreviewProgress(0, sequence);
}

function convert() {
  updateLineNumbers();
  clearPlayerSong();
  const bpm = Number(elements.bpm.value);
  const sequence = inputMode === "jianpu"
    ? parseJianpu(elements.jianpuScore.value, bpm)
    : inputMode === "keyboard"
      ? parseKeyboardScore(elements.keyboardScore.value, bpm)
      : parseScore(inputMode === "record" ? elements.recordedScore.value : elements.score.value, bpm);
  if (sequence.error) {
    currentSequence = null;
    updateMonitor(null);
    updateTransposeControls(null);
    elements.status.textContent = `错误 · ${sequence.error.line}:${sequence.error.column}`;
    setValidation(`第 ${sequence.error.line} 行，第 ${sequence.error.column} 列：${sequence.error.message}`, "error");
    return null;
  }
  sequence.notes.forEach((item, index) => { item.index = index; });
  currentSequence = sequence;
  updateMonitor(sequence);
  updateTransposeControls(sequence);
  elements.status.textContent = "序列已就绪";
  const uploadIssue = suppressUploadCompatibilityWarning ? null : uploadCompatibilityIssue(sequence);
  setValidation(uploadIssue
    ? `校验提醒 · 第 ${uploadIssue.line} 行，第 ${uploadIssue.column} 列：${uploadIssue.message}`
    : `校验通过 · ${sequence.notes.length} 个音符，预计播放 ${formatTime(sequence.totalMs)}。`, uploadIssue ? "warning" : "success");
  return sequence;
}

function openKeyboardMacroDialog() {
  const sequence = convert();
  if (!sequence) {
    toast("请先修正谱子错误。");
    return;
  }
  elements.keyboardMacroTitle.textContent = `${elements.macroName.value.trim() || "当前曲谱"} · 手动输入宏`;
  elements.keyboardMacroMeta.textContent = `三角洲键盘模式 · ${sequence.notes.length} 个事件 · ${formatTime(sequence.totalMs)}`;
  elements.keyboardMacroOutput.value = sequenceToKeyboard(sequence);
  elements.keyboardMacroDialog.showModal();
}

function normalizeRecordingHelperManifest(manifest) {
  if (!manifest || typeof manifest !== "object" || typeof manifest.version !== "string" || !manifest.version.trim()) return null;
  const prefixes = Array.isArray(manifest.compatibleHelperPrefixes)
    ? manifest.compatibleHelperPrefixes.filter((prefix) => typeof prefix === "string" && prefix.trim()).map((prefix) => prefix.trim())
    : [];
  const links = {
    github: typeof manifest.githubDownloadUrl === "string" ? manifest.githubDownloadUrl.trim() : "",
    server: typeof manifest.serverDownloadUrl === "string" ? manifest.serverDownloadUrl.trim() : ""
  };
  if (!links.github && typeof manifest.downloadUrl === "string") links.github = manifest.downloadUrl.trim();
  return Object.freeze({
    ...manifest,
    version: manifest.version.trim(),
    compatibleHelperPrefixes: Object.freeze(prefixes),
    links: Object.freeze(links),
    compatibilityLabel: prefixes.length ? prefixes.map((prefix) => `v${prefix}.x`).join(" / ") : "未声明"
  });
}

function loadRecordingHelperManifest() {
  if (recorderHelperManifestPromise) return recorderHelperManifestPromise;
  recorderHelperManifestPromise = (async () => {
    try {
      const response = await fetch(`${RECORDER_HELPER_MANIFEST_URL}?t=${Date.now()}`, { headers: { Accept: "application/json" }, cache: "no-store" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const manifest = normalizeRecordingHelperManifest(await response.json());
      if (!manifest) throw new Error("invalid manifest");
      recorderHelperManifest = manifest;
      recorderHelperVersion = manifest.version;
      recorderHelperCompatibility = Object.freeze({ label: manifest.compatibilityLabel, prefixes: manifest.compatibleHelperPrefixes });
      syncRecordingHelperVersionBoards();
      return manifest;
    } catch {
      recorderHelperManifest = null;
      return null;
    } finally {
      recorderHelperManifestPromise = null;
    }
  })();
  return recorderHelperManifestPromise;
}

function syncRecordingHelperVersionBoards() {
  elements.recordingHelperVersionBoards.forEach((board) => {
    board.querySelector('[data-recording-helper-field="web"]')?.replaceChildren(`WEB v${WEBSITE_VERSION}`);
    board.querySelector('[data-recording-helper-field="helper"]')?.replaceChildren(`HELPER v${recorderHelperVersion}`);
  });
  elements.recordingHelperDownloadLinks.forEach((link) => {
    const url = recorderHelperManifest?.links?.[link.dataset.recordingHelperDownload] || "";
    link.hidden = !url;
    if (url) link.href = url;
    else link.removeAttribute("href");
  });
}

function openRecordingHelperDialog() {
  syncRecordingHelperVersionBoards();
  elements.recordingHelperDownloadVersion.textContent = `HELPER v${recorderHelperVersion}`;
  elements.recordingHelperDialog.showModal();
}

function openSectionGuide(key) {
  const guide = SECTION_GUIDES[key];
  if (!guide) return;
  elements.sectionGuideWindowTitle.textContent = guide.windowTitle;
  elements.sectionGuideIndex.textContent = guide.index;
  elements.sectionGuideHeading.textContent = guide.title;
  elements.sectionGuideIntro.textContent = guide.intro;
  elements.sectionGuideSteps.innerHTML = guide.steps.map(([number, title, copy]) => `
    <article class="section-guide-step">
      <b>${number}</b>
      <div><h3>${title}</h3><p>${copy}</p></div>
    </article>
  `).join("");
  elements.sectionGuideDialog.showModal();
}

function openAiScoreDialog() {
  elements.aiScorePrompt.value = AI_SCORE_PROMPT;
  if (typeof elements.aiScoreDialog.showModal !== "function") {
    toast("当前浏览器不支持 AI 打谱提示词窗口。 ");
    return;
  }
  elements.aiScoreDialog.showModal();
  window.requestAnimationFrame(() => elements.copyAiScorePrompt.focus({ preventScroll: true }));
}

async function copyAiScorePrompt() {
  try {
    await navigator.clipboard.writeText(AI_SCORE_PROMPT);
    toast("AI 打谱提示词已复制，去 AI 对话中粘贴并附上曲谱材料吧。 ");
  } catch {
    elements.aiScorePrompt.focus({ preventScroll: true });
    elements.aiScorePrompt.select();
    toast("无法自动复制，提示词已选中，请手动复制。 ");
  }
}

function handleBpmChange() {
  stopPreview();
  if (inputMode !== "keyboard" || !currentSequence) {
    convert();
    return;
  }
  const sequence = enrichNotes(currentSequence.notes, Number(elements.bpm.value));
  if (sequence.error) {
    elements.status.textContent = `错误 · ${sequence.error.line}:${sequence.error.column}`;
    setValidation(`第 ${sequence.error.line} 行，第 ${sequence.error.column} 列：${sequence.error.message}`, "error");
    return;
  }
  sequence.notes.forEach((item, index) => { item.index = index; });
  clearPlayerSong();
  currentSequence = sequence;
  syncSequenceToEditors(sequence);
  updateMonitor(sequence);
  updateTransposeControls(sequence);
  elements.status.textContent = "序列已就绪";
  const uploadIssue = suppressUploadCompatibilityWarning ? null : uploadCompatibilityIssue(sequence);
  setValidation(uploadIssue
    ? `校验提醒 · 第 ${uploadIssue.line} 行，第 ${uploadIssue.column} 列：${uploadIssue.message}`
    : `校验通过 · ${sequence.notes.length} 个音符，预计播放 ${formatTime(sequence.totalMs)}。`, uploadIssue ? "warning" : "success");
}

function getAudioEngine() {
  // Browsers can close an AudioContext after an output-device change or a
  // long background suspension. Do not keep reusing that dead instance.
  if (audioContext && audioContext.state !== "closed" && masterGain) return audioContext;
  const Context = window.AudioContext || window.webkitAudioContext;
  if (!Context) throw new Error("当前浏览器不支持音频试听。");
  audioContext = new Context();
  masterGain = audioContext.createGain();
  masterGain.gain.value = Number(elements.volume.value) / 100;
  const compressor = audioContext.createDynamicsCompressor();
  compressor.threshold.value = -18;
  compressor.knee.value = 12;
  compressor.ratio.value = 7;
  masterGain.connect(compressor).connect(audioContext.destination);
  const contextForStateChange = audioContext;
  audioContext.addEventListener("statechange", () => {
    if (audioContext !== contextForStateChange) return;
    if (contextForStateChange.state === "closed") {
      audioContext = null;
      masterGain = null;
      if (activePreview?.context === contextForStateChange) stopPreview({ resetProgress: false });
    }
  });
  return audioContext;
}

function resetAudioEngine() {
  const context = audioContext;
  audioContext = null;
  masterGain = null;
  if (context && context.state !== "closed") void context.close().catch(() => {});
}

function handleAudioOutputChange() {
  const wasPlaying = activePreview?.state === "playing";
  if (activePreview) stopPreview({ resetProgress: false });
  if (liveRecordingVoice) releaseLiveRecordingVoice();
  resetAudioEngine();
  if (wasPlaying) toast("音频输出设备已变化，请再次点击试听。 ");
}

async function wakeAudioEngine() {
  let context = getAudioEngine();
  if (context.state === "running") return Promise.resolve(context);
  try {
    await context.resume();
  } catch (error) {
    // A closed context cannot be resumed. Recreate it so the next click can
    // recover from an audio-device or browser lifecycle interruption.
    if (context.state !== "closed") throw error;
    audioContext = null;
    masterGain = null;
    context = getAudioEngine();
    await context.resume();
  }
  if (context.state !== "running") throw new Error("Safari 音频仍处于暂停状态，请再次点击试听按钮或取消标签页静音。");
  return context;
}

function prewarmAudioEngine() {
  try {
    void wakeAudioEngine().catch((error) => toast(error.message || "无法启动音频试听。 "));
  } catch (error) {
    toast(error.message || "无法启动音频试听。 ");
  }
}

function previewFrequency(item) {
  const midi = macroMidi(item);
  if (!Number.isFinite(midi)) throw new Error("谱子中存在无法试听的音符，请先修正谱面。");
  return 440 * (2 ** ((midi - 69) / 12));
}

function closestHarmonicaSample(sampleBank, midi) {
  return HARMONICA_SAMPLE_ANCHORS.reduce((closest, anchor) => {
    if (!closest || Math.abs(anchor - midi) < Math.abs(closest.anchor - midi)) {
      return { anchor, buffer: sampleBank.get(anchor) };
    }
    return closest;
  }, null);
}

async function loadHarmonicaSampleBank(context) {
  if (harmonicaSampleBankCache.has(context)) return harmonicaSampleBankCache.get(context);
  const bankPromise = Promise.all(HARMONICA_SAMPLE_ANCHORS.map(async (midi) => {
    const response = await fetch(`${HARMONICA_SAMPLE_ROOT}/${midi}.wav`);
    if (!response.ok) throw new Error(`口琴采样 ${midi}.wav 加载失败（${response.status}）。`);
    const audioData = await response.arrayBuffer();
    const buffer = await context.decodeAudioData(audioData);
    return [midi, buffer];
  })).then((entries) => new Map(entries)).catch((error) => {
    harmonicaSampleBankCache.delete(context);
    throw error;
  });
  harmonicaSampleBankCache.set(context, bankPromise);
  return bankPromise;
}

function getHarmonicaSustainWave(context, buffer, anchor) {
  let contextCache = harmonicaSustainWaveCache.get(context);
  if (!contextCache) {
    contextCache = new WeakMap();
    harmonicaSustainWaveCache.set(context, contextCache);
  }
  if (contextCache.has(buffer)) return contextCache.get(buffer);

  const data = buffer.getChannelData(0);
  const sampleRate = buffer.sampleRate;
  const anchorFrequency = 440 * (2 ** ((anchor - 69) / 12));
  const periodFrames = sampleRate / anchorFrequency;
  const targetFrame = Math.floor(sampleRate * 0.34);
  const radius = Math.floor(sampleRate * 0.06);
  const firstFrame = Math.max(1, targetFrame - radius);
  const lastFrame = Math.min(data.length - 2, targetFrame + radius);
  let startFrame = targetFrame;
  let closestDistance = Infinity;
  for (let frame = firstFrame; frame <= lastFrame; frame += 1) {
    if (data[frame - 1] <= 0 && data[frame] > 0) {
      const distance = Math.abs(frame - targetFrame);
      if (distance < closestDistance) {
        closestDistance = distance;
        startFrame = frame;
      }
    }
  }

  // Build one mathematically continuous wavetable from the stable part of the
  // recording. Unlike looping a long recording, this has no recorded-noise or
  // room-tone discontinuity at the sustain boundary.
  const tableLength = 2048;
  const averagedCycles = 12;
  const samples = new Float32Array(tableLength);
  let sampleTotal = 0;
  for (let index = 0; index < tableLength; index += 1) {
    const phase = index / tableLength;
    let value = 0;
    let count = 0;
    for (let cycle = 0; cycle < averagedCycles; cycle += 1) {
      const position = startFrame + (cycle + phase) * periodFrames;
      const left = Math.floor(position);
      if (left < 0 || left + 1 >= data.length) continue;
      const fraction = position - left;
      value += data[left] + (data[left + 1] - data[left]) * fraction;
      count += 1;
    }
    samples[index] = count ? value / count : 0;
    sampleTotal += samples[index];
  }
  const mean = sampleTotal / tableLength;
  let peak = 0;
  for (let index = 0; index < tableLength; index += 1) {
    samples[index] -= mean;
    peak = Math.max(peak, Math.abs(samples[index]));
  }

  const real = new Float32Array(65);
  const imag = new Float32Array(65);
  const maxHarmonics = Math.max(8, Math.min(64, Math.floor((sampleRate * 0.45) / anchorFrequency)));
  for (let harmonic = 1; harmonic <= maxHarmonics; harmonic += 1) {
    let realSum = 0;
    let imagSum = 0;
    for (let index = 0; index < tableLength; index += 1) {
      const phase = (2 * Math.PI * harmonic * index) / tableLength;
      realSum += samples[index] * Math.cos(phase);
      imagSum -= samples[index] * Math.sin(phase);
    }
    real[harmonic] = (2 * realSum) / tableLength;
    imag[harmonic] = (2 * imagSum) / tableLength;
  }

  const wave = context.createPeriodicWave(real, imag);
  const result = { wave, peak: Math.max(0.04, Math.min(1, peak)) };
  contextCache.set(buffer, result);
  return result;
}

function createSampleHarmonicaVoice(context, startAt, duration, midi, sampleBank) {
  const selected = closestHarmonicaSample(sampleBank, midi);
  if (!selected?.buffer) return null;
  const gain = context.createGain();
  const source = context.createOscillator();
  const hasScheduledEnd = Number.isFinite(duration) && duration > 0;
  const endAt = hasScheduledEnd ? startAt + duration : null;
  const sustainWave = getHarmonicaSustainWave(context, selected.buffer, selected.anchor);
  const noteFrequency = 440 * (2 ** ((midi - 69) / 12));
  const lowRegisterAmount = Math.max(0, Math.min(1, (60 - midi) / 12));
  const mainsHumNotch = context.createBiquadFilter();
  const mainsHumHarmonicNotch = context.createBiquadFilter();
  const cleanupHighpass = context.createBiquadFilter();
  const cleanupLowpass = context.createBiquadFilter();

  // Pitching the C4 sample down makes its quiet 50Hz room hum and top-end
  // resampling grit much more obvious in the low register. Keep the note's
  // fundamental, notch the mains hum, and gently roll off the harshness.
  mainsHumNotch.type = "notch";
  mainsHumNotch.frequency.setValueAtTime(50, startAt);
  mainsHumNotch.Q.setValueAtTime(8, startAt);
  mainsHumHarmonicNotch.type = "notch";
  mainsHumHarmonicNotch.frequency.setValueAtTime(100, startAt);
  mainsHumHarmonicNotch.Q.setValueAtTime(8, startAt);
  cleanupHighpass.type = "highpass";
  cleanupHighpass.frequency.setValueAtTime(Math.max(38, Math.min(72, noteFrequency * 0.28)), startAt);
  cleanupHighpass.Q.setValueAtTime(0.45, startAt);
  cleanupLowpass.type = "lowpass";
  cleanupLowpass.frequency.setValueAtTime(
    Math.max(2400, Math.min(5600, noteFrequency * (10.5 + (1 - lowRegisterAmount) * 3))),
    startAt
  );
  cleanupLowpass.Q.setValueAtTime(0.45, startAt);

  source.setPeriodicWave(sustainWave.wave);
  source.frequency.setValueAtTime(noteFrequency, startAt);
  source.connect(mainsHumNotch).connect(mainsHumHarmonicNotch).connect(cleanupHighpass).connect(cleanupLowpass).connect(gain).connect(masterGain);

  const attackAt = hasScheduledEnd ? Math.min(endAt - 0.01, startAt + 0.04) : startAt + 0.04;
  const safeAttackAt = Math.max(startAt + 0.005, attackAt);
  gain.gain.setValueAtTime(0.0001, startAt);
  gain.gain.exponentialRampToValueAtTime(0.62, safeAttackAt);
  if (hasScheduledEnd) {
    const releaseAt = Math.max(safeAttackAt, endAt - 0.045);
    gain.gain.setValueAtTime(0.62, releaseAt);
    gain.gain.exponentialRampToValueAtTime(0.0001, endAt);
  }
  source.start(startAt);
  if (hasScheduledEnd) source.stop(endAt + 0.06);
  return { context, gain, nodes: [source] };
}

function getHarmonicaWave(context) {
  if (harmonicaWaveCache.has(context)) return harmonicaWaveCache.get(context);
  const real = new Float32Array(12);
  const imag = new Float32Array([0, 1, 0.42, 0.23, 0.14, 0.085, 0.052, 0.034, 0.022, 0.015, 0.01, 0.007]);
  const wave = context.createPeriodicWave(real, imag);
  harmonicaWaveCache.set(context, wave);
  return wave;
}

function getHarmonicaNoiseBuffer(context) {
  if (harmonicaNoiseCache.has(context)) return harmonicaNoiseCache.get(context);
  const length = Math.ceil(context.sampleRate * 0.35);
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const data = buffer.getChannelData(0);
  let seed = 0x6d2b79f5;
  let filtered = 0;
  for (let index = 0; index < data.length; index += 1) {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    const white = (seed / 0xffffffff) * 2 - 1;
    filtered = filtered * 0.94 + white * 0.06;
    data[index] = (white * 0.3 + filtered * 0.7) * 0.6;
  }
  harmonicaNoiseCache.set(context, buffer);
  return buffer;
}

function createHarmonicaVoice(context, startAt, duration, frequency) {
  const gain = context.createGain();
  const toneFilter = context.createBiquadFilter();
  const resonance = context.createBiquadFilter();
  const reed = context.createOscillator();
  const reedColor = context.createOscillator();
  const reedGain = context.createGain();
  const colorGain = context.createGain();
  const breath = context.createBufferSource();
  const breathFilter = context.createBiquadFilter();
  const breathGain = context.createGain();
  const hasScheduledEnd = Number.isFinite(duration) && duration > 0;
  const endAt = hasScheduledEnd ? startAt + duration : null;
  const wave = getHarmonicaWave(context);
  const noiseBuffer = getHarmonicaNoiseBuffer(context);

  reed.setPeriodicWave(wave);
  reed.frequency.setValueAtTime(frequency, startAt);
  reed.detune.setValueAtTime(-2, startAt);
  reedColor.type = "sine";
  reedColor.frequency.setValueAtTime(frequency * 2.003, startAt);
  reedColor.detune.setValueAtTime(3, startAt);
  reedGain.gain.value = 0.78;
  colorGain.gain.value = 0.12;
  toneFilter.type = "lowpass";
  toneFilter.frequency.setValueAtTime(Math.min(6200, Math.max(2200, frequency * 10.5)), startAt);
  toneFilter.Q.value = 0.8;
  resonance.type = "peaking";
  resonance.frequency.setValueAtTime(Math.min(3400, Math.max(900, frequency * 2.2)), startAt);
  resonance.Q.value = 1.1;
  resonance.gain.setValueAtTime(3.5, startAt);
  breath.buffer = noiseBuffer;
  breath.loop = true;
  breathFilter.type = "bandpass";
  breathFilter.frequency.setValueAtTime(Math.min(5200, Math.max(1800, frequency * 3.6)), startAt);
  breathFilter.Q.value = 0.7;

  const attackAt = hasScheduledEnd ? Math.min(endAt - 0.008, startAt + 0.02) : startAt + 0.02;
  const sustainAt = hasScheduledEnd
    ? Math.min(endAt - 0.005, Math.max(attackAt + 0.005, startAt + 0.11))
    : startAt + 0.11;
  gain.gain.setValueAtTime(0.0001, startAt);
  gain.gain.exponentialRampToValueAtTime(0.15, attackAt);
  if (sustainAt < endAt || !hasScheduledEnd) gain.gain.exponentialRampToValueAtTime(0.095, sustainAt);
  if (hasScheduledEnd) gain.gain.exponentialRampToValueAtTime(0.0001, endAt);
  breathGain.gain.setValueAtTime(0.0001, startAt);
  breathGain.gain.exponentialRampToValueAtTime(0.018, startAt + 0.012);
  breathGain.gain.exponentialRampToValueAtTime(0.006, hasScheduledEnd ? Math.min(endAt - 0.012, startAt + 0.09) : startAt + 0.09);
  if (hasScheduledEnd) breathGain.gain.exponentialRampToValueAtTime(0.0001, endAt);

  reed.connect(reedGain).connect(toneFilter);
  reedColor.connect(colorGain).connect(toneFilter);
  toneFilter.connect(resonance).connect(gain).connect(masterGain);
  breath.connect(breathFilter).connect(breathGain).connect(gain);
  reed.start(startAt);
  reedColor.start(startAt);
  breath.start(startAt);
  if (hasScheduledEnd) {
    reed.stop(endAt + 0.025);
    reedColor.stop(endAt + 0.025);
    breath.stop(endAt + 0.025);
  }
  return { context, gain, nodes: [reed, reedColor, breath] };
}

function scheduleHarmonicaTone(context, startAt, duration, midi, sampleBank = null) {
  const sampleVoice = sampleBank && createSampleHarmonicaVoice(context, startAt, duration, midi, sampleBank);
  if (sampleVoice) return sampleVoice.nodes;
  const frequency = 440 * (2 ** ((midi - 69) / 12));
  return createHarmonicaVoice(context, startAt, duration, frequency).nodes;
}

function releaseLiveRecordingVoice() {
  if (!liveRecordingVoice) return;
  const { context, gain, nodes } = liveRecordingVoice;
  const now = context.currentTime;
  const releaseLevel = Math.max(0.0001, gain.gain.value);
  gain.gain.cancelScheduledValues(now);
  gain.gain.setValueAtTime(releaseLevel, now);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.025);
  nodes.forEach((node) => { try { node.stop(now + 0.045); } catch {} });
  liveRecordingVoice = null;
}

async function playLiveRecordingNote(note) {
  try {
    const context = await wakeAudioEngine();
    masterGain.gain.setTargetAtTime(Number(elements.volume.value) / 100, context.currentTime, 0.01);
    const midi = macroMidi({ note, modifier: selectedRecordModifier || null });
    let sampleBank = null;
    try {
      sampleBank = await loadHarmonicaSampleBank(context);
    } catch (error) {
      console.warn("口琴采样加载失败，录制试听回退到电子音：", error);
    }
    const voice = sampleBank
      ? createSampleHarmonicaVoice(context, context.currentTime, null, midi, sampleBank)
      : createHarmonicaVoice(context, context.currentTime, null, previewFrequency({ note, modifier: selectedRecordModifier || null }));
    releaseLiveRecordingVoice();
    liveRecordingVoice = voice;
  } catch (error) {
    toast(error.message || "无法启动录制试听。 ");
  }
}

function clearTimelinePlayback() {
  elements.timeline.querySelectorAll(".playing").forEach((row) => {
    row.classList.remove("playing");
    row.removeAttribute("aria-current");
  });
}

function setTimelinePlaybackPosition(sequence, index, { scroll = false } = {}) {
  const note = sequence?.notes[index];
  clearTimelinePlayback();
  if (!note) return false;
  const rowIndex = note.index ?? index;
  const row = elements.timeline.querySelector(`[data-note-index="${rowIndex}"]`);
  if (!row) return false;
  row.classList.add("playing");
  row.setAttribute("aria-current", "true");
  if (scroll) keepTimelineRowVisible(row);
  return true;
}

function keepTimelineRowVisible(row) {
  if (!row) return;
  const timelineRect = elements.timeline.getBoundingClientRect();
  const rowRect = row.getBoundingClientRect();
  if (rowRect.top < timelineRect.top || rowRect.bottom > timelineRect.bottom) {
    const centeredOffset = rowRect.top - timelineRect.top - (elements.timeline.clientHeight - rowRect.height) / 2;
    elements.timeline.scrollTop = Math.max(0, elements.timeline.scrollTop + centeredOffset);
  }
}

function setPreviewUi(state = "ready") {
  const isPlaying = state === "playing";
  const isPaused = state === "paused";
  const label = elements.previewButton.querySelector("span");
  const icon = elements.previewButton.querySelector("b");
  elements.previewButton.disabled = false;
  icon.textContent = isPlaying ? "Ⅱ" : "▶";
  label.textContent = isPlaying ? "暂停" : isPaused ? "继续" : "试听整段";
  elements.previewButton.setAttribute("aria-label", isPlaying ? "暂停试听" : isPaused ? "继续试听" : "试听整段简谱");
  elements.stopButton.disabled = !isPlaying && !isPaused;
  elements.previewState.textContent = isPlaying ? "PLAYING" : isPaused ? "PAUSED" : "READY";
  elements.previewState.classList.toggle("live", isPlaying);
  refreshCardPreviewButtons();
}

function clearPreviewTimers(preview) {
  preview.timers.forEach((timer) => window.clearTimeout(timer));
  preview.timers = [];
}

function stopPreviewNodes(preview) {
  preview.nodes.forEach((node) => { try { node.stop(); } catch {} });
  preview.nodes.clear();
}

function clearPreviewScheduler(preview) {
  if (!preview.schedulerTimer) return;
  window.clearInterval(preview.schedulerTimer);
  preview.schedulerTimer = null;
}

function stopPreview({ resetProgress = true } = {}) {
  previewProgressSeeking = false;
  if (!activePreview) return;
  stopPreviewNodes(activePreview);
  clearPreviewTimers(activePreview);
  clearPreviewScheduler(activePreview);
  activePreview = null;
  window.cancelAnimationFrame(previewProgressFrame);
  clearTimelinePlayback();
  if (resetProgress) setPreviewProgress(0);
  setPreviewUi("ready");
}

function previewPositionMs(preview) {
  const elapsedMs = Math.max(0, (preview.context.currentTime - preview.startAt) * 1000);
  return Math.max(preview.positionMs, Math.min(preview.sequence.totalMs, preview.positionMs + elapsedMs));
}

function nextPreviewNoteIndex(sequence, positionMs) {
  const index = sequence.notes.findIndex((item) => item.timeMs + item.pressMs > positionMs);
  return index < 0 ? sequence.notes.length : index;
}

function updatePreviewTimeline(preview, positionMs) {
  const { notes } = preview.sequence;
  let index = preview.timelineIndex;
  if (!Number.isInteger(index) || positionMs < notes[index]?.timeMs || positionMs >= notes[index]?.timeMs + notes[index]?.durationMs) {
    index = timelineNoteIndexAt(preview.sequence, positionMs);
  }
  if (index < 0 || index === preview.timelineIndex) return;
  if (setTimelinePlaybackPosition(preview.sequence, index, { scroll: true })) preview.timelineIndex = index;
}

function registerPreviewNodes(preview, nodes) {
  nodes.forEach((node) => {
    preview.nodes.add(node);
    node.addEventListener("ended", () => preview.nodes.delete(node), { once: true });
  });
}

function schedulePreviewWindow(preview) {
  if (activePreview !== preview || preview.state !== "playing") return;
  const positionMs = previewPositionMs(preview);
  const windowEndMs = Math.min(preview.sequence.totalMs, positionMs + PREVIEW_SCHEDULE_AHEAD_MS);
  while (preview.nextNoteIndex < preview.sequence.notes.length) {
    const item = preview.sequence.notes[preview.nextNoteIndex];
    if (item.timeMs > windowEndMs) break;
    preview.nextNoteIndex += 1;
    const noteStart = item.timeMs + (item.inputLeadMs || 0);
    const noteEnd = item.timeMs + item.pressMs;
    if (item.isRest || noteEnd <= preview.positionMs) continue;
    const skippedMs = Math.max(0, preview.positionMs - noteStart);
    const noteLength = Math.max(0.035, (item.pressMs - (item.inputLeadMs || 0) - skippedMs) / 1000);
    const startAt = preview.startAt + Math.max(0, noteStart - preview.positionMs) / 1000;
    const midi = macroMidi(item);
    registerPreviewNodes(preview, scheduleHarmonicaTone(preview.context, startAt, noteLength, midi, preview.sampleBank));
  }
  if (positionMs >= preview.sequence.totalMs) stopPreview();
}

function startPreviewScheduler(preview) {
  schedulePreviewWindow(preview);
  preview.schedulerTimer = window.setInterval(() => schedulePreviewWindow(preview), PREVIEW_SCHEDULER_INTERVAL_MS);
}

function refreshPreviewProgress() {
  if (!activePreview || activePreview.state !== "playing") return;
  if (!previewProgressSeeking) {
    const position = previewPositionMs(activePreview);
    setPreviewProgress(position, activePreview.sequence);
    updatePreviewTimeline(activePreview, position);
  }
  previewProgressFrame = window.requestAnimationFrame(refreshPreviewProgress);
}

async function pausePreview() {
  if (!activePreview || activePreview.state !== "playing") return;
  const preview = activePreview;
  const positionMs = previewPositionMs(preview);
  stopPreviewNodes(preview);
  clearPreviewScheduler(preview);
  window.cancelAnimationFrame(previewProgressFrame);
  try {
    await preview.context.suspend();
    preview.positionMs = positionMs;
    preview.nextNoteIndex = nextPreviewNoteIndex(preview.sequence, positionMs);
    setPreviewProgress(preview.positionMs, preview.sequence);
    preview.state = "paused";
    setPreviewUi("paused");
  } catch (error) {
    startPreviewScheduler(preview);
    toast(error.message || "无法暂停试听。 ");
  }
}

async function resumePreview() {
  if (!activePreview || activePreview.state !== "paused") return;
  const preview = activePreview;
  try {
    await preview.context.resume();
    preview.startAt = preview.context.currentTime;
    preview.state = "playing";
    preview.nextNoteIndex = nextPreviewNoteIndex(preview.sequence, preview.positionMs);
    startPreviewScheduler(preview);
    previewProgressFrame = window.requestAnimationFrame(refreshPreviewProgress);
    setPreviewUi("playing");
  } catch (error) {
    toast(error.message || "无法继续试听。 ");
  }
}

function togglePreview() {
  if (!activePreview) return playPreview(previewCursorMs);
  if (activePreview.state === "playing") return pausePreview();
  return resumePreview();
}

async function playPreview(positionMs = 0, { analytics = true } = {}) {
  if (recording) { toast("请先完成录制，再播放谱子。 "); return; }
  const sequence = playerSongSequence || convert();
  if (!sequence) { toast("请先修正谱子错误。 "); return; }
  const startPosition = Math.max(0, Math.min(sequence.totalMs, Number(positionMs) || 0));
  stopPreview({ resetProgress: false });
  try {
    const context = await wakeAudioEngine();
    masterGain.gain.setTargetAtTime(Number(elements.volume.value) / 100, context.currentTime, 0.01);
    let sampleBank = null;
    try {
      sampleBank = await loadHarmonicaSampleBank(context);
    } catch (error) {
      console.warn("口琴采样加载失败，播放器试听回退到电子音：", error);
      toast("口琴采样加载失败，已暂时使用电子音试听。 ");
    }
    const startAt = context.currentTime + 0.045;
    activePreview = {
      context, sampleBank, nodes: new Set(), timers: [], schedulerTimer: null, sequence, startAt, positionMs: startPosition,
      state: "playing", nextNoteIndex: nextPreviewNoteIndex(sequence, startPosition), timelineIndex: -1
    };
    setPreviewProgress(startPosition, sequence);
    updatePreviewTimeline(activePreview, startPosition);
    startPreviewScheduler(activePreview);
    window.cancelAnimationFrame(previewProgressFrame);
    previewProgressFrame = window.requestAnimationFrame(refreshPreviewProgress);
    setPreviewUi("playing");
    if (analytics) trackAnalytics("preview_started");
  } catch (error) {
    stopPreview({ resetProgress: false });
    setPreviewUi("ready");
    toast(error.message || "无法启动试听。 ");
  }
}

function escapedXml(value) {
  return String(value).replace(/[<>&'\"]/g, (character) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", "'": "&apos;", '"': "&quot;" }[character]));
}

function safeName() {
  return (elements.macroName.value.trim() || "Delta Harmonica").replace(/[\\/:*?"<>|]/g, "-").slice(0, 48);
}

function makeUuid() {
  if (globalThis.crypto?.randomUUID) return crypto.randomUUID();
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (character) => {
    const random = Math.random() * 16 | 0;
    return (character === "x" ? random : random & 3 | 8).toString(16);
  });
}

function setMacroTriggerValidation(message = "", invalidFields = []) {
  elements.macroTriggerValidation.textContent = message;
  elements.macroTriggerValidation.hidden = !message;
  [
    elements.macroTriggerButton,
    elements.macroStopButton,
    elements.macroLowButton,
    elements.macroMiddleButton,
    elements.macroHighButton
  ].forEach((field) => field.setAttribute("aria-invalid", String(invalidFields.includes(field))));
}

function clearMacroTriggerValidation() {
  setMacroTriggerValidation("");
}

function readMacroTriggerSettings() {
  const rawTriggerEventButton = String(elements.macroTriggerButton.value).trim();
  const triggerEventButton = Number(rawTriggerEventButton);
  const rawStopStateButton = String(elements.macroStopButton.value).trim();
  const stopStateButton = rawStopStateButton ? Number(rawStopStateButton) : 0;
  const pitchButtonFields = { L: elements.macroLowButton, M: elements.macroMiddleButton, R: elements.macroHighButton };
  const pitchButtons = Object.fromEntries(Object.entries(pitchButtonFields).map(([modifier, field]) => [modifier, Number(String(field.value).trim())]));
  if (!rawTriggerEventButton || !Number.isInteger(triggerEventButton) || triggerEventButton < 1) {
    setMacroTriggerValidation("开始键必须填写正整数。", [elements.macroTriggerButton]);
    return null;
  }
  if (!rawStopStateButton || !Number.isInteger(stopStateButton) || ![4, 5].includes(stopStateButton)) {
    setMacroTriggerValidation("停止键只能填写 4 或 5。", [elements.macroStopButton]);
    return null;
  }
  const invalidPitchFields = Object.entries(pitchButtons).filter(([, mappedButton]) => !Number.isInteger(mappedButton) || mappedButton < 1 || mappedButton > 5).map(([modifier]) => pitchButtonFields[modifier]);
  if (invalidPitchFields.length) {
    setMacroTriggerValidation("低音、半音和高音的模拟映射必须分别填写 1 到 5 的整数。", invalidPitchFields);
    return null;
  }
  const pitchModifierButtons = new Set(Object.values(pitchButtons));
  if (pitchModifierButtons.size !== 3) {
    setMacroTriggerValidation("低音、半音和高音必须使用三个不同的鼠标键。", Object.values(pitchButtonFields));
    return null;
  }
  clearMacroTriggerValidation();
  return { triggerEventButton, stopStateButton, pitchButtons };
}

function requireMacroTriggerSettings() {
  const settings = readMacroTriggerSettings();
  if (settings) return settings;
  elements.macroSettings.scrollIntoView({ behavior: "smooth", block: "center" });
  const invalidField = [
    elements.macroTriggerButton,
    elements.macroStopButton,
    elements.macroLowButton,
    elements.macroMiddleButton,
    elements.macroHighButton
  ].find((field) => field.getAttribute("aria-invalid") === "true") || elements.macroTriggerButton;
  invalidField.focus();
  toast("请先完成 G HUB 宏触发设置。 ");
  return null;
}

function generateLua(sequence, triggerSettings) {
  const { triggerEventButton, stopStateButton, pitchButtons = { L: 1, M: 2, R: 3 } } = triggerSettings;
  const lines = [
    "-- Harmonica Deck · Delta Force harmonica sequence",
    `-- Score: ${safeName()} | ${sequence.notes.length} notes | ${elements.bpm.value} BPM`,
    `-- Start event: ${triggerEventButton}; stop state: ${stopStateButton || "disabled"} · play once`,
    `-- Harmonica modifiers: L=${pitchButtons.L} (low), M=${pitchButtons.M} (semitone), R=${pitchButtons.R} (high)`,
    "-- The start event plays the score once. The optional stop state can interrupt playback.",
    "-- Stop handling releases the current note and any mouse modifier buttons.",
    `local TRIGGER_EVENT_BUTTON = ${triggerEventButton}`,
    `local STOP_STATE_BUTTON = ${stopStateButton}`,
    "local isPlaying = false",
    "local stopRequested = false",
    "local activeKey = nil",
    "local activeModifiers = {}",
    "local activePlaybackGeneration = 0",
    "local playbackStartedAt = 0",
    "local playbackGeneration = 0",
    `local PLAYBACK_START_GUARD_MS = ${LUA_PLAYBACK_START_GUARD_MS}`,
    "",
    "local function ReleaseHeldInputs(ownerGeneration)",
    "  if ownerGeneration ~= nil and activePlaybackGeneration ~= ownerGeneration then return end",
    "  if activeKey ~= nil then",
    "    ReleaseKey(activeKey)",
    "    activeKey = nil",
    "  end",
    "  for index = #activeModifiers, 1, -1 do",
    "    ReleaseMouseButton(activeModifiers[index])",
    "  end",
    "  activeModifiers = {}",
    "  activePlaybackGeneration = 0",
    "end",
    "",
    "local function RequestStop()",
    "  playbackGeneration = playbackGeneration + 1",
    "  stopRequested = true",
    "  ReleaseHeldInputs()",
    "  isPlaying = false",
    "  playbackStartedAt = 0",
    "end",
    "",
    "local function StopButtonPressed()",
    "  return STOP_STATE_BUTTON > 0 and IsMouseButtonPressed(STOP_STATE_BUTTON)",
    "end",
    "",
    "-- Wait against absolute score time so driver call overhead cannot accumulate.",
    "local function WaitUntil(targetMs, ownerGeneration)",
    "  targetMs = targetMs + PLAYBACK_START_GUARD_MS",
    "  while true do",
    "    if stopRequested or playbackGeneration ~= ownerGeneration then return false end",
    "    if StopButtonPressed() then",
    "      RequestStop()",
    "      return false",
    "    end",
    "    local remaining = targetMs - (GetRunningTime() - playbackStartedAt)",
    "    if remaining <= 0 then return true end",
    "    -- Sleep coarsely when far away, then use 1ms slices near the target.",
    "    local slice = remaining > 8 and remaining - 4 or math.min(remaining, 1)",
    "    Sleep(slice)",
    "  end",
    "end",
    "",
    "function PlayHarmonica()",
    "  if isPlaying then return end",
    "  playbackGeneration = playbackGeneration + 1",
    "  local ownerGeneration = playbackGeneration",
    "  isPlaying = true",
    "  stopRequested = false",
    "  playbackStartedAt = GetRunningTime()",
  ];
  sequence.notes.forEach((item, index) => {
    lines.push(`  if not WaitUntil(${item.timeMs}, ownerGeneration) then`);
    lines.push("    if playbackGeneration == ownerGeneration then stopRequested = true end");
    lines.push("  end");
    lines.push("  if not stopRequested and playbackGeneration == ownerGeneration then");
    lines.push(`    -- ${String(index + 1).padStart(2, "0")}: ${item.modifier ? `${item.modifier}+` : ""}${item.note}, ${item.beats} beat(s)`);
    if (item.isRest) {
      lines.push(`    if not WaitUntil(${item.timeMs + item.durationMs}, ownerGeneration) then`);
      lines.push("      if playbackGeneration == ownerGeneration then stopRequested = true end");
      lines.push("    end");
    } else {
      const modifierButtons = [...(item.modifier || "")].map((modifier) => pitchButtons[modifier]);
      lines.push(`    activeModifiers = {${modifierButtons.join(", ")}}`);
      lines.push("    activePlaybackGeneration = ownerGeneration");
      lines.push("    for index = 1, #activeModifiers do");
      lines.push("      PressMouseButton(activeModifiers[index])");
      lines.push("    end");
      if (item.inputLeadMs > 0) {
        lines.push(`    if not WaitUntil(${item.timeMs + item.inputLeadMs}, ownerGeneration) then`);
        lines.push("      if playbackGeneration == ownerGeneration then stopRequested = true end");
        lines.push("    end");
        lines.push("    if not stopRequested and playbackGeneration == ownerGeneration then");
      }
      lines.push(`    activeKey = ${JSON.stringify(GHUB_KEY_NAMES[item.key] || item.key)}`);
      lines.push("    PressKey(activeKey)");
      lines.push(`    if not WaitUntil(${item.timeMs + item.pressMs}, ownerGeneration) then`);
      lines.push("      if playbackGeneration == ownerGeneration then stopRequested = true end");
      lines.push("    end");
      if (item.inputLeadMs > 0) lines.push("    end");
      lines.push("    ReleaseHeldInputs(ownerGeneration)");
    }
    lines.push("  end");
  });
  lines.push(
    "  if playbackGeneration == ownerGeneration then",
    "    ReleaseHeldInputs(ownerGeneration)",
    "    isPlaying = false",
    "    stopRequested = false",
    "    playbackStartedAt = 0",
    "  end",
    "end",
    "",
    "function OnEvent(event, arg)",
    "  if event == \"PROFILE_ACTIVATED\" then",
    "    -- Required for button 1 because it is the primary mouse button.",
    "    EnablePrimaryMouseButtonEvents(true)",
    "    playbackGeneration = playbackGeneration + 1",
    "    isPlaying = false",
    "    stopRequested = true",
    "    ReleaseHeldInputs()",
    "    AbortMacro()",
    "    stopRequested = false",
    "    playbackStartedAt = 0",
    "    return",
    "  end",
    "  if event == \"MOUSE_BUTTON_PRESSED\" and arg == TRIGGER_EVENT_BUTTON then",
    "    PlayHarmonica()",
    "  end",
    "end",
    ""
  );
  return lines.join("\n");
}

function encodeUrlSafePayload(payload) {
  const bytes = new TextEncoder().encode(JSON.stringify(payload));
  let binary = "";
  const chunkSize = 0x8000;
  for (let start = 0; start < bytes.length; start += chunkSize) binary += String.fromCharCode(...bytes.subarray(start, start + chunkSize));
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
}

function recorderPayloadFromSequence(sequence) {
  return {
    v: 1,
    wv: WEBSITE_VERSION,
    title: safeName(),
    events: [
      { w: RECORDER_STARTUP_GUARD_MS },
      ...sequence.notes.map((item) => item.isRest
        ? { w: item.durationMs }
        : { k: item.key, m: item.modifier || "", l: item.inputLeadMs || 0, h: item.pressMs, w: item.waitMs || 0 })
    ],
    hc: recorderHelperCompatibility.prefixes
  };
}

function recorderPayloadKey(payload) {
  return JSON.stringify(payload);
}

function warmRecorderCompression(payload) {
  const key = recorderPayloadKey(payload);
  if (recorderCompressionCache.key === key || recorderCompressionPending.key === key) return;
  recorderCompressionPending = { key, promise: encodeGzipUrlPayload(payload).then((compressed) => {
    if (recorderCompressionPending.key === key && compressed) recorderCompressionCache = { key, payload: compressed };
    return compressed;
  }).catch(() => null) };
}

function requestRecorderProtocol(url) {
  const link = document.createElement("a");
  link.href = url;
  link.hidden = true;
  document.body.append(link);
  try {
    // Keep this synchronous: Chromium and Edge may reject a custom protocol
    // navigation after an awaited fetch/compression step loses user activation.
    link.click();
    return true;
  } finally {
    link.remove();
  }
}

async function encodeGzipUrlPayload(payload) {
  if (typeof CompressionStream !== "function") return null;
  try {
    const source = new TextEncoder().encode(JSON.stringify(payload));
    const compressedStream = new Blob([source]).stream().pipeThrough(new CompressionStream("gzip"));
    const compressed = new Uint8Array(await new Response(compressedStream).arrayBuffer());
    let binary = "";
    const chunkSize = 0x8000;
    for (let start = 0; start < compressed.length; start += chunkSize) binary += String.fromCharCode(...compressed.subarray(start, start + chunkSize));
    return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
  } catch {
    return null;
  }
}

async function launchIndependentRecorder(sequence) {
  if (!recorderHelperManifest) {
    void loadRecordingHelperManifest();
    toast("正在读取宏录制助手信息，请稍后再次点击导出。 ");
    return;
  }
  const payload = recorderPayloadFromSequence(sequence);
  const payloadKey = recorderPayloadKey(payload);
  const compressedPayload = recorderCompressionCache.key === payloadKey ? recorderCompressionCache.payload : null;
  const plainUrl = `harmonica-recorder://play?payload=${encodeUrlSafePayload(payload)}`;
  const url = compressedPayload
    ? `harmonica-recorder://play?encoding=gzip&payload=${compressedPayload}`
    : plainUrl;
  if (url.length > RECORDER_PROTOCOL_MAX_LENGTH) {
    if (compressedPayload) {
      toast("当前曲谱压缩后仍超过系统导入上限，请拆分为较短的段落。 ");
      return;
    }
    if (typeof CompressionStream !== "function") {
      toast("当前浏览器不支持压缩导入，且曲谱过长；请拆分为较短的段落。 ");
      return;
    }
    warmRecorderCompression(payload);
    toast("当前曲谱较长，正在准备压缩导入，请稍后再次点击。 ");
    return;
  }
  const reservation = await reserveMacroExportSlot();
  if (!reservation) return;
  try {
    requestRecorderProtocol(url);
  } catch {
    reservation.release();
    toast("无法启动宏录制助手，请确认助手已安装。 ");
    return;
  }
  reservation.commit();
  trackMacroExport("recorder");
  toast(`网页 v${WEBSITE_VERSION} 已请求助手。若未显示曲谱，请重新运行 Install.cmd。 `);
}

function razerKeyboardEvent(type, delay, makeCode) {
  return `    <MacroEvent><Type>${type}</Type><Delay>${delay}</Delay><Keyboard><KeyboardEvent><Type>${type}</Type><Makecode>${makeCode}</Makecode></KeyboardEvent></Keyboard></MacroEvent>`;
}

function razerMouseEvent(type, delay, button) {
  return `    <MacroEvent><Type>${type}</Type><Delay>${delay}</Delay><Mouse><MouseEvent><Type>${type}</Type><Button>${button}</Button></MouseEvent></Mouse></MacroEvent>`;
}

function generateRazerXml(sequence, version) {
  const events = [];
  sequence.notes.forEach((item) => {
    if (item.isRest) {
      events.push(`    <MacroEvent><Type>0</Type><Delay>${item.durationMs}</Delay></MacroEvent>`);
      return;
    }
    [...(item.modifier || "")].forEach((modifier) => events.push(razerMouseEvent(1, 0, MOUSE_BUTTONS[modifier].razer)));
    const inputLeadMs = item.inputLeadMs || 0;
    events.push(razerKeyboardEvent(1, inputLeadMs, MAKE_CODES[item.key]));
    events.push(razerKeyboardEvent(2, item.pressMs - inputLeadMs, MAKE_CODES[item.key]));
    [...(item.modifier || "")].reverse().forEach((modifier) => events.push(razerMouseEvent(2, 0, MOUSE_BUTTONS[modifier].razer)));
    if (item.waitMs > 0) events.push(`    <MacroEvent><Type>0</Type><Delay>${item.waitMs}</Delay></MacroEvent>`);
  });
  const name = escapedXml(`${safeName()} · Synapse ${version}`);
  return `<?xml version="1.0" encoding="utf-8"?>\n<!-- Harmonica Deck experimental Synapse ${version} macro. Synapse 3 and 4 files are not interchangeable. -->\n<Macro xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema">\n  <Name>${name}</Name>\n  <Guid>${makeUuid()}</Guid>\n  <MacroEvents>\n${events.join("\n")}\n  </MacroEvents>\n  <IsFolder>false</IsFolder>\n  <FolderGuid>00000000-0000-0000-0000-000000000000</FolderGuid>\n</Macro>\n`;
}

function razer4DelayEvent(milliseconds, selected = false) {
  const seconds = (Math.max(0, Math.round(milliseconds)) / 1000).toFixed(3);
  return `    <MacroEvent><Type>0</Type><Number>${seconds}</Number><selected>${selected}</selected></MacroEvent>`;
}

function razer4KeyboardEvent(state, codes, id, selected = false) {
  return `    <MacroEvent><Type>1</Type><Id>${id}</Id><KeyEvent><Makecode>${codes.makeCode}</Makecode><State>${state}</State></KeyEvent><flag>0</flag><selected>${selected}</selected><isPairing>false</isPairing><ScanCode>${codes.scanCode}</ScanCode></MacroEvent>`;
}

function razer4MouseEvent(state, button, id, selected = false) {
  return `    <MacroEvent><Type>2</Type><Id>${id}</Id><MouseEvent><MouseButton>${button}</MouseButton><State>${state}</State></MouseEvent><flag>0</flag><selected>${selected}</selected><isPairing>false</isPairing></MacroEvent>`;
}

function generateRazer4Xml(sequence) {
  const events = [];
  let nextEventId = Date.now();
  const eventId = () => String(nextEventId++);
  const selected = false;
  const pushDelay = (milliseconds) => events.push(razer4DelayEvent(milliseconds, selected));

  sequence.notes.forEach((item) => {
    if (item.isRest) {
      pushDelay(item.durationMs);
      return;
    }
    const codes = RAZER4_KEY_CODES[item.key];
    if (!codes) return;
    const modifiers = [...(item.modifier || "")];
    const modifierIds = modifiers.map(() => eventId());
    modifiers.forEach((modifier, index) => {
      pushDelay(0);
      events.push(razer4MouseEvent(0, MOUSE_BUTTONS[modifier].razer4, modifierIds[index], selected));
    });
    const inputLeadMs = item.inputLeadMs || 0;
    const keyId = eventId();
    pushDelay(inputLeadMs);
    events.push(razer4KeyboardEvent(0, codes, keyId, selected));
    pushDelay(item.pressMs - inputLeadMs);
    events.push(razer4KeyboardEvent(1, codes, keyId, selected));
    modifiers.slice().reverse().forEach((modifier, index) => {
      pushDelay(0);
      const originalIndex = modifiers.length - 1 - index;
      events.push(razer4MouseEvent(1, MOUSE_BUTTONS[modifier].razer4, modifierIds[originalIndex], selected));
    });
    if (item.waitMs > 0) pushDelay(item.waitMs);
  });
  if (events.length) pushDelay(0);
  const name = escapedXml(`${safeName()} · Synapse 4`);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<Macro>\n  <Name>${name}</Name>\n  <MacroEvents>\n${events.join("\n")}\n  </MacroEvents>\n  <DelaySetting>0</DelaySetting>\n  <Guid>${makeUuid()}</Guid>\n  <Version>4</Version>\n  <MouseMoveType>none</MouseMoveType>\n</Macro>\n`;
}

function mchoseAction(val, type, press) {
  return { val, type, press, hover: false };
}

function mchoseTime(delay) {
  return { val: Math.max(0, Math.round(delay)), type: "time", press: null, hover: false };
}

function generateMchoseActionGroups(sequence) {
  const groups = [];
  sequence.notes.forEach((item) => {
    const group = [];
    const addTime = (delay) => {
      const value = Math.max(0, Math.round(delay));
      if (value > 0) group.push(mchoseTime(value));
    };
    if (item.isRest) {
      addTime(item.durationMs);
      groups.push(group);
      return;
    }
    [...(item.modifier || "")].forEach((modifier) => {
      group.push(mchoseAction(MCHOSE_MOUSE_BUTTONS[modifier], "mouse", "down"));
    });
    addTime(item.inputLeadMs || 0);
    group.push(mchoseAction(item.key, "key", "down"));
    addTime(item.pressMs - (item.inputLeadMs || 0));
    group.push(mchoseAction(item.key, "key", "up"));
    [...(item.modifier || "")].reverse().forEach((modifier) => {
      group.push(mchoseAction(MCHOSE_MOUSE_BUTTONS[modifier], "mouse", "up"));
    });
    addTime(item.waitMs || 0);
    groups.push(group);
  });
  return groups;
}

function countMchoseOperations(events) {
  return events.reduce((count, event) => count + (event.type === "key" || event.type === "mouse" ? 1 : 0), 0);
}

function splitMchoseOperations(sequence, maxOperations = MCHOSE_MAX_OPERATIONS) {
  const batches = [];
  let batch = [];
  generateMchoseActionGroups(sequence).forEach((group) => {
    if (batch.length && countMchoseOperations(batch) + countMchoseOperations(group) > maxOperations) {
      batches.push(batch);
      batch = [];
    }
    batch.push(...group);
  });
  if (batch.length || !batches.length) batches.push(batch);
  return batches;
}

function generateMchoseJson(keyList, macroName = safeName()) {
  return `${JSON.stringify({
    name: macroName,
    type: 1,
    delay: 50,
    info: { keyList },
    uid: makeUuid(),
    updateTime: Date.now(),
    orderNum: 3,
    editRecordStatus: true
  }, null, 2)}\n`;
}

function normalizeOperationsPerFile(value, fallback, max) {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(max, Math.max(MCHOSE_MIN_OPERATIONS, parsed));
}

function normalizeMchoseOperationsPerFile(value) {
  return normalizeOperationsPerFile(value, MCHOSE_DEFAULT_OPERATIONS_PER_FILE, MCHOSE_MAX_OPERATIONS);
}

function normalizeRogOperationsPerFile(value) {
  return normalizeOperationsPerFile(value, DEFAULT_OPERATIONS_PER_FILE, ROG_MAX_OPERATIONS);
}

function readMchoseOperationsPerFile() {
  try {
    return normalizeMchoseOperationsPerFile(window.localStorage.getItem(MCHOSE_OPERATIONS_PER_FILE_KEY));
  } catch {
    return MCHOSE_DEFAULT_OPERATIONS_PER_FILE;
  }
}

function readMchoseSplitEnabled() {
  try {
    return window.localStorage.getItem(MCHOSE_SPLIT_ENABLED_KEY) !== "false";
  } catch {
    return true;
  }
}

function syncMchoseOperationsPerFileSetting({ persist = false } = {}) {
  const value = normalizeMchoseOperationsPerFile(elements.mchoseOperationsPerFile?.value || readMchoseOperationsPerFile());
  const splitEnabled = elements.mchoseSplitEnabled ? elements.mchoseSplitEnabled.checked : readMchoseSplitEnabled();
  if (elements.mchoseOperationsPerFile) elements.mchoseOperationsPerFile.value = String(value);
  if (elements.mchoseOperationsPerFile) elements.mchoseOperationsPerFile.disabled = !splitEnabled;
  if (elements.mchoseSplitStatus) elements.mchoseSplitStatus.textContent = splitEnabled
    ? `当前为分段导出；每个文件最多 ${value} 个键盘／鼠标操作，等待时间不计入，按完整音符分段。`
    : "当前为单文件导出；整首曲谱会导出到一个 JSON 文件，等待时间不计入操作数。";
  if (elements.mchoseDownloadButton) elements.mchoseDownloadButton.textContent = splitEnabled
    ? "下载 MCHOSE JSON ZIP（按设置分段）"
    : "下载 MCHOSE JSON（单文件）";
  if (persist) {
    try { window.localStorage.setItem(MCHOSE_OPERATIONS_PER_FILE_KEY, String(value)); } catch {}
    try { window.localStorage.setItem(MCHOSE_SPLIT_ENABLED_KEY, String(splitEnabled)); } catch {}
  }
  return { value, splitEnabled };
}

function initializeMchoseOperationsPerFileSetting() {
  if (elements.mchoseSplitEnabled) elements.mchoseSplitEnabled.checked = readMchoseSplitEnabled();
  if (elements.mchoseOperationsPerFile) elements.mchoseOperationsPerFile.value = String(readMchoseOperationsPerFile());
  syncMchoseOperationsPerFileSetting();
}

function readRogOperationsPerFile() {
  try {
    return normalizeRogOperationsPerFile(window.localStorage.getItem(ROG_OPERATIONS_PER_FILE_KEY));
  } catch {
    return DEFAULT_OPERATIONS_PER_FILE;
  }
}

function readRogSplitEnabled() {
  try {
    return window.localStorage.getItem(ROG_SPLIT_ENABLED_KEY) !== "false";
  } catch {
    return true;
  }
}

function syncRogOperationsPerFileSetting({ persist = false } = {}) {
  const value = normalizeRogOperationsPerFile(elements.rogOperationsPerFile?.value || readRogOperationsPerFile());
  const splitEnabled = elements.rogSplitEnabled ? elements.rogSplitEnabled.checked : readRogSplitEnabled();
  if (elements.rogOperationsPerFile) elements.rogOperationsPerFile.value = String(value);
  if (elements.rogOperationsPerFile) elements.rogOperationsPerFile.disabled = !splitEnabled;
  if (elements.rogSplitStatus) elements.rogSplitStatus.textContent = splitEnabled
    ? `当前为分段导出；每个文件最多 ${value} 个键盘／鼠标操作，延迟不计入，按完整音符分段。`
    : "当前为单文件导出；整首曲谱会导出到一个 GMAC 文件，延迟不计入操作数。";
  if (elements.rogDownloadButton) elements.rogDownloadButton.textContent = splitEnabled
    ? "下载 ROG GMAC ZIP（按设置分段）"
    : "下载 ROG GMAC（单文件）";
  if (persist) {
    try { window.localStorage.setItem(ROG_OPERATIONS_PER_FILE_KEY, String(value)); } catch {}
    try { window.localStorage.setItem(ROG_SPLIT_ENABLED_KEY, String(splitEnabled)); } catch {}
  }
  return { value, splitEnabled };
}

function initializeRogOperationsPerFileSetting() {
  if (elements.rogSplitEnabled) elements.rogSplitEnabled.checked = readRogSplitEnabled();
  if (elements.rogOperationsPerFile) elements.rogOperationsPerFile.value = String(readRogOperationsPerFile());
  syncRogOperationsPerFileSetting();
}

function generateMchoseJsonFiles(sequence, fileBase, maxOperations = MCHOSE_MAX_OPERATIONS, splitEnabled = true) {
  const batches = splitEnabled
    ? splitMchoseOperations(sequence, normalizeMchoseOperationsPerFile(maxOperations))
    : [generateMchoseActionGroups(sequence).flat()];
  const digits = String(batches.length).length;
  const macroBase = safeName();
  return batches.map((batch, index) => ({
    content: generateMchoseJson(batch, batches.length === 1 ? macroBase : `${macroBase} - ${index + 1}/${batches.length}`),
    filename: batches.length === 1
      ? `${fileBase}-mchose.json`
      : `${fileBase}-mchose-${String(index + 1).padStart(digits, "0")}-of-${batches.length}.json`
  }));
}

function rogGmacEvent(action, input) {
  return `${action},${input.name},${input.linuxCode},${input.windowsCode}`;
}

function rogDelay(delay) {
  return delay > 0 ? `Delay,${Math.round(delay)}` : "";
}

function countRogOperations(events) {
  return events.reduce((count, event) => count + (event.startsWith("Press,") || event.startsWith("Release,") ? 1 : 0), 0);
}

function generateRogGmacEventGroups(sequence) {
  const groups = [];
  sequence.notes.forEach((item) => {
    const events = [];
    if (item.isRest) {
      events.push(rogDelay(item.durationMs));
    } else {
      [...(item.modifier || "")].forEach((modifier) => events.push(rogGmacEvent("Press", ROG_MOUSE_BUTTONS[modifier])));
      const inputLeadMs = item.inputLeadMs || 0;
      events.push(rogDelay(inputLeadMs));
      const key = ROG_KEYS[item.key];
      events.push(rogGmacEvent("Press", key));
      events.push(rogDelay(item.pressMs - inputLeadMs));
      events.push(rogGmacEvent("Release", key));
      [...(item.modifier || "")].reverse().forEach((modifier) => events.push(rogGmacEvent("Release", ROG_MOUSE_BUTTONS[modifier])));
      events.push(rogDelay(item.waitMs));
    }
    groups.push(events.filter(Boolean));
  });
  return groups;
}

function splitRogGmacOperations(sequence, maxOperations = ROG_MAX_OPERATIONS) {
  const batches = [];
  let batch = [];

  generateRogGmacEventGroups(sequence).forEach((group) => {
    if (batch.length && countRogOperations(batch) + countRogOperations(group) > maxOperations) {
      batches.push(batch);
      batch = [];
    }
    batch.push(...group);
  });
  if (batch.length || !batches.length) batches.push(batch);
  return batches;
}

function formatRogGmac(events) {
  // The final value is Armoury Crate's repeat setting: 1 means play once.
  return `${events.join("\n")}\n1\n`;
}

function generateRogGmac(sequence) {
  return formatRogGmac(generateRogGmacEventGroups(sequence).flat());
}

function generateRogGmacFiles(sequence, fileBase, maxOperations = ROG_MAX_OPERATIONS, splitEnabled = true) {
  const batches = splitEnabled
    ? splitRogGmacOperations(sequence, maxOperations)
    : [generateRogGmacEventGroups(sequence).flat()];
  const digits = String(batches.length).length;
  return batches.map((batch, index) => ({
    content: formatRogGmac(batch),
    filename: batches.length === 1
      ? `${fileBase}-rog.gmac`
      : `${fileBase}-rog-${String(index + 1).padStart(digits, "0")}-of-${batches.length}.gmac`
  }));
}

const ZIP_UTF8_FLAG = 0x0800;

function crc32(bytes) {
  let value = 0xffffffff;
  for (let index = 0; index < bytes.length; index += 1) {
    value ^= bytes[index];
    for (let bit = 0; bit < 8; bit += 1) value = (value >>> 1) ^ (value & 1 ? 0xedb88320 : 0);
  }
  return (value ^ 0xffffffff) >>> 0;
}

function createZipArchive(files) {
  const encoder = new TextEncoder();
  const entries = files.map((file) => ({
    name: encoder.encode(file.filename),
    data: encoder.encode(file.content)
  })).map((entry) => ({ ...entry, checksum: crc32(entry.data) }));
  const parts = [];
  let offset = 0;

  entries.forEach((entry) => {
    entry.offset = offset;
    const header = new Uint8Array(30);
    const view = new DataView(header.buffer);
    view.setUint32(0, 0x04034b50, true);
    view.setUint16(4, 20, true);
    view.setUint16(6, ZIP_UTF8_FLAG, true);
    view.setUint32(14, entry.checksum, true);
    view.setUint32(18, entry.data.length, true);
    view.setUint32(22, entry.data.length, true);
    view.setUint16(26, entry.name.length, true);
    parts.push(header, entry.name, entry.data);
    offset += header.length + entry.name.length + entry.data.length;
  });

  const centralDirectoryOffset = offset;
  entries.forEach((entry) => {
    const header = new Uint8Array(46);
    const view = new DataView(header.buffer);
    view.setUint32(0, 0x02014b50, true);
    view.setUint16(4, 20, true);
    view.setUint16(6, 20, true);
    view.setUint16(8, ZIP_UTF8_FLAG, true);
    view.setUint32(16, entry.checksum, true);
    view.setUint32(20, entry.data.length, true);
    view.setUint32(24, entry.data.length, true);
    view.setUint16(28, entry.name.length, true);
    view.setUint32(42, entry.offset, true);
    parts.push(header, entry.name);
    offset += header.length + entry.name.length;
  });

  const end = new Uint8Array(22);
  const endView = new DataView(end.buffer);
  endView.setUint32(0, 0x06054b50, true);
  endView.setUint16(8, entries.length, true);
  endView.setUint16(10, entries.length, true);
  endView.setUint32(12, offset - centralDirectoryOffset, true);
  endView.setUint32(16, centralDirectoryOffset, true);
  parts.push(end);
  return new Blob(parts, { type: "application/zip" });
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 500);
}

function download(content, filename, type) {
  downloadBlob(new Blob([content], { type: `${type};charset=utf-8` }), filename);
}

const MACRO_DOWNLOAD_CONFIG = {
  "download-lua": {
    suffix: ".lua",
    type: "text/plain",
    requiresTriggerSettings: true,
    build: (sequence, triggerSettings) => generateLua(sequence, triggerSettings),
    success: "Lua 脚本已下载。"
  },
  "download-rz3": {
    suffix: "-synapse-3.xml",
    type: "application/xml",
    requiresTriggerSettings: false,
    build: (sequence) => generateRazerXml(sequence, 3),
    success: "Synapse 3 XML 已下载。"
  },
  "download-rz4": {
    suffix: "-synapse-4.xml",
    type: "application/xml",
    requiresTriggerSettings: false,
    build: (sequence) => generateRazer4Xml(sequence),
    success: "Synapse 4 XML 已下载。"
  },
  "download-mchose": {
    suffix: "-mchose-json.zip",
    singleSuffix: "-mchose.json",
    type: "application/zip",
    requiresTriggerSettings: false,
    buildFiles: (sequence, fileBase) => {
      const setting = syncMchoseOperationsPerFileSetting();
      return generateMchoseJsonFiles(sequence, fileBase, setting.value, setting.splitEnabled);
    },
    getSplitEnabled: () => syncMchoseOperationsPerFileSetting().splitEnabled,
    buildArchive: (files) => createZipArchive(files),
    archiveEntryLabel: "个 JSON",
    success: ({ files, splitEnabled }) => splitEnabled
      ? (files.length === 1 ? "迈从 MCHOSE JSON ZIP 已下载。" : `迈从 MCHOSE JSON 已分段并打包为 ZIP（内含 ${files.length} 个文件）。`)
      : "迈从 MCHOSE JSON 单文件已下载。"
  },
  "download-rog": {
    suffix: "-rog-gmac.zip",
    singleSuffix: "-rog.gmac",
    type: "text/plain",
    requiresTriggerSettings: false,
    buildFiles: (sequence, fileBase) => {
      const setting = syncRogOperationsPerFileSetting();
      return generateRogGmacFiles(sequence, fileBase, setting.value, setting.splitEnabled);
    },
    getSplitEnabled: () => syncRogOperationsPerFileSetting().splitEnabled,
    buildArchive: (files) => createZipArchive(files),
    archiveEntryLabel: "个 GMAC",
    success: ({ files, splitEnabled }) => splitEnabled
      ? (files.length === 1 ? "ROG Armoury Crate GMAC ZIP 已下载。" : `ROG Armoury Crate GMAC 已分段并打包为 ZIP（内含 ${files.length} 个文件）。`)
      : "ROG Armoury Crate GMAC 单文件已下载。"
  },
};

function clearMacroDownloadTimers() {
  window.clearInterval(macroDownloadTimer);
  window.clearTimeout(macroDownloadFinalizeTimer);
  macroDownloadTimer = null;
  macroDownloadFinalizeTimer = null;
}

function resetMacroDownloadProgress() {
  clearMacroDownloadTimers();
  elements.macroDownloadProgress.value = 0;
  elements.macroDownloadProgressLabel.textContent = "等待确认";
  elements.confirmMacroDownload.disabled = false;
}

async function openMacroDownloadDialog(action) {
  const config = MACRO_DOWNLOAD_CONFIG[action];
  if (!config) return;
  const sequence = convert();
  if (!sequence) {
    toast("请先修正谱子错误。 ");
    return;
  }
  const triggerSettings = config.requiresTriggerSettings ? requireMacroTriggerSettings() : null;
  if (config.requiresTriggerSettings && !triggerSettings) return;
  const fileBase = safeName().replace(/\s+/g, "-").toLowerCase();
  const normalizedFileBase = fileBase || "delta-harmonica";
  const files = config.buildFiles
    ? config.buildFiles(sequence, normalizedFileBase, triggerSettings)
    : [{
      content: config.build(sequence, triggerSettings),
      filename: `${normalizedFileBase}${config.suffix}`
    }];
  const splitEnabled = config.getSplitEnabled ? config.getSplitEnabled() : true;
  const archive = config.buildArchive && splitEnabled
    ? { blob: config.buildArchive(files), filename: `${normalizedFileBase}${config.suffix}` }
    : null;
  const reservation = await reserveMacroExportSlot();
  if (!reservation) return;
  pendingMacroDownload = {
    action,
    config,
    files,
    archive,
    sequence,
    triggerSettings,
    splitEnabled,
    exportReservation: reservation
  };
  resetMacroDownloadProgress();
  elements.macroDownloadFilename.textContent = archive
    ? `${archive.filename}（内含 ${files.length} ${config.archiveEntryLabel || "个文件"}）`
    : (splitEnabled ? files[0].filename : `${normalizedFileBase}${config.singleSuffix || config.suffix}`);
  if (typeof elements.macroDownloadDialog.showModal === "function") {
    elements.macroDownloadDialog.showModal();
    elements.confirmMacroDownload.focus();
    return;
  }
  startMacroDownload();
}

function startMacroDownload() {
  if (!pendingMacroDownload) return;
  const pending = pendingMacroDownload;
  clearMacroDownloadTimers();
  elements.confirmMacroDownload.disabled = true;
  let progress = 0;
  elements.macroDownloadProgress.value = progress;
  elements.macroDownloadProgressLabel.textContent = "正在生成文件 · 0%";
  macroDownloadTimer = window.setInterval(() => {
    progress = Math.min(100, progress + 10);
    elements.macroDownloadProgress.value = progress;
    elements.macroDownloadProgressLabel.textContent = progress < 100 ? `正在生成文件 · ${progress}%` : "文件已生成，准备下载…";
    if (progress < 100) return;
    clearMacroDownloadTimers();
    macroDownloadFinalizeTimer = window.setTimeout(() => {
      if (pendingMacroDownload !== pending) return;
      try {
        if (pending.archive) downloadBlob(pending.archive.blob, pending.archive.filename);
        else pending.files.forEach((file) => download(file.content, file.filename, pending.config.type));
      } catch {
        pending.exportReservation.release();
        if (elements.macroDownloadDialog.open) {
          elements.macroDownloadDialog.close();
        } else {
          pendingMacroDownload = null;
          resetMacroDownloadProgress();
        }
        toast("宏文件生成失败，请稍后重试。 ");
        return;
      }
      const format = ({ "download-lua": "lua", "download-rz3": "synapse_3", "download-rz4": "synapse_4", "download-mchose": "mchose", "download-rog": "rog" })[pending.action] || "lua";
      pending.exportReservation.commit();
      trackScoreAnalytics("macro_downloaded", { format });
      trackMacroExport(format);
      if (elements.macroDownloadDialog.open) {
        elements.macroDownloadDialog.close();
      } else {
        pendingMacroDownload = null;
        resetMacroDownloadProgress();
      }
      toast(typeof pending.config.success === "function"
        ? pending.config.success({ files: pending.files, splitEnabled: pending.splitEnabled })
        : pending.config.success);
    }, 180);
  }, 70);
}

async function authRequest(path, { method = "GET", body } = {}) {
  const response = await fetch(path, {
    method,
    headers: body ? { "Content-Type": "application/json", Accept: "application/json" } : { Accept: "application/json" },
    body: body ? JSON.stringify(body) : undefined,
    credentials: "same-origin"
  });
  const text = await response.text();
  let payload = {};
  try { payload = text ? JSON.parse(text) : {}; } catch {}
  if (!response.ok) {
    const error = new Error(payload.error || "账户服务暂时不可用。 ");
    error.status = response.status;
    throw error;
  }
  return payload;
}

function setAuthStatus(target, message = "", success = false) {
  target.textContent = message;
  target.hidden = !message;
  target.classList.toggle("success", Boolean(message && success));
}

const OAUTH_PROVIDER_LABELS = { qq: "QQ", wechat: "微信", github: "GitHub" };

function setOAuthProviders(providers = [], { github = false } = {}) {
  // GitHub 快捷登录只看服务端是否配置了 GitHub OAuth 应用；QQ / 微信入口仍由
  // THIRD_PARTY_LOGIN_UI_ENABLED 控制，避免恢复未完成的后端入口。
  const available = new Set();
  if (github) available.add("github");
  if (THIRD_PARTY_LOGIN_UI_ENABLED && Array.isArray(providers)) {
    providers.filter((provider) => ["qq", "wechat"].includes(provider)).forEach((provider) => available.add(provider));
  }
  authState.providers = [...available];
  elements.oauthLoginButtons.forEach((button) => {
    button.hidden = !available.has(button.dataset.oauthProvider);
  });
  elements.oauthLogin.hidden = authState.providers.length === 0;
}

function startOAuthLogin(provider) {
  if (!authState.providers.includes(provider)) {
    setAuthStatus(elements.authStatus, `${OAUTH_PROVIDER_LABELS[provider] || provider}登录尚未配置。`);
    return;
  }
  // GitHub 的 Star 验证与快捷登录共用一个回调地址，入口按用途区分。
  if (provider === "github") {
    window.location.assign("./api/auth/github/start");
    return;
  }
  const referral = document.querySelector("#authReferral")?.value.trim();
  window.location.assign(`./api/auth/oauth/${provider}/start${referral ? `?ref=${encodeURIComponent(referral)}` : ""}`);
}

function handleOAuthRedirectStatus() {
  const url = new URL(window.location.href);
  const result = url.searchParams.get("auth");
  if (!result) return;
  const message = url.searchParams.get("message") || "";
  url.searchParams.delete("auth");
  url.searchParams.delete("message");
  window.history.replaceState({}, document.title, `${url.pathname}${url.search}${url.hash}`);
  if (result === "success") toast("第三方登录成功。 ");
  else if (result === "error") toast(message || "第三方登录失败，请重试。 ");
}

function replaceCommunitySongs(songs) {
  if (!Array.isArray(songs)) return;
  SONG_LIBRARY.splice(0, SONG_LIBRARY.length, ...[...BUILTIN_SONGS_FOR_LIBRARY(), ...songs].map((song) => normalizeSong(song)));
  void refreshLibraryViews();
}

function setLibraryView(view = "recommended") {
  const selectedView = ["all", "recommended", "hot", "mine"].includes(view) ? view : "recommended";
  activeLibraryView = selectedView;
  elements.libraryTabs.forEach((tab) => {
    const selected = tab.dataset.libraryView === selectedView;
    tab.classList.toggle("active", selected);
    tab.setAttribute("aria-selected", String(selected));
    tab.tabIndex = selected ? 0 : -1;
  });
  renderSongLibrary(elements.songSearch.value);
}

async function updateSongRecommendation(song, shouldRecommend, button) {
  if (!authState.account?.isAdmin) {
    toast("只有管理员可以配置推荐曲库。 ");
    return;
  }
  button.disabled = true;
  try {
    const result = await authRequest("./api/public-library/recommendations", {
      method: shouldRecommend ? "POST" : "DELETE",
      body: recommendationIdentityForSong(song)
    });
    if (!Array.isArray(result.recommendations)) throw new Error("服务器返回的推荐曲库数据无效。");
    setRecommendedSongIdentities(result.recommendations);
    toast(shouldRecommend ? `《${song.title}》已加入推荐曲库。` : `《${song.title}》已取消推荐。`);
  } catch (error) {
    toast(error.message || (shouldRecommend ? "加入推荐失败，请稍后重试。" : "取消推荐失败，请稍后重试。"));
  } finally {
    button.disabled = false;
  }
}

async function loadMySongLibrary() {
  if (!authState.account) {
    mySongLibrary = [];
    renderSongLibrary(elements.songSearch.value);
    return;
  }
  try {
    const result = await authRequest("./api/public-library/songs");
    if (!Array.isArray(result.songs)) throw new Error("服务器返回的我的曲库数据无效。");
    mySongLibrary = result.songs.map((song) => normalizeSong(song));
    mySongLibrary.forEach((song) => {
      if (songLibraryIndex(song) < 0) SONG_LIBRARY.push(song);
    });
  } catch {
    mySongLibrary = [];
  }
  void refreshLibraryViews();
}

function setSongEditStatus(message = "", success = false) {
  elements.songEditStatusMessage.textContent = message;
  elements.songEditStatusMessage.hidden = !message;
  elements.songEditStatusMessage.classList.toggle("success", Boolean(message && success));
}

function updateSongEditLineNumbers() {
  if (!elements.songEditScore || !elements.songEditLineNumbers) return;
  const lines = Math.max(1, elements.songEditScore.value.split("\n").length);
  elements.songEditLineNumbers.textContent = Array.from({ length: lines }, (_, index) => index + 1).join("\n");
  elements.songEditLineNumbers.scrollTop = elements.songEditScore.scrollTop;
}

function editSongKeySignature(semitones) {
  const match = String(elements.songEditKey.value).trim().match(/^(1=)?([A-G])([#♯b♭])?$/i);
  if (!match) return;
  const accidental = match[3] === "#" || match[3] === "♯" ? 1 : match[3] === "b" || match[3] === "♭" ? -1 : 0;
  const natural = KEY_SIGNATURE_SEMITONES[match[2].toUpperCase()];
  if (!Number.isFinite(natural)) return;
  const pitch = (natural + accidental + semitones + 120) % 12;
  elements.songEditKey.value = `${match[1] || ""}${KEY_SIGNATURE_NAMES[pitch]}`;
}

function updateSongEditTransposeControls(sequence = null) {
  const pitchValues = sequence?.notes?.filter((item) => !item.isRest && item.note !== "0").map(macroMidi).filter(Number.isFinite) || [];
  if (!pitchValues.length) {
    elements.songEditTransposeDown.disabled = true;
    elements.songEditTransposeUp.disabled = true;
    elements.songEditTransposeStatus.textContent = sequence ? "仅休止" : "等待曲谱";
    return;
  }
  elements.songEditTransposeDown.disabled = !transposeSequence(sequence, -1);
  elements.songEditTransposeUp.disabled = !transposeSequence(sequence, 1);
  elements.songEditTransposeStatus.textContent = `${midiPitchLabel(Math.min(...pitchValues))} ↔ ${midiPitchLabel(Math.max(...pitchValues))}`;
}

function transposeSongEdit(semitones) {
  const sequence = parseJianpu(elements.songEditScore.value, Number(elements.songEditBpm.value));
  if (sequence.error) {
    setSongEditStatus(`请先修正简谱：${sequence.error.message}`);
    return;
  }
  const shifted = transposeSequence(sequence, semitones);
  if (!shifted || shifted.error) {
    setSongEditStatus(semitones > 0 ? "已到达口琴可演奏的最高音。" : "已到达口琴可演奏的最低音。");
    return;
  }
  elements.songEditScore.value = sequenceToJianpu(shifted);
  editSongKeySignature(semitones);
  updateSongEditLineNumbers();
  updateSongEditTransposeControls(shifted);
  setSongEditStatus(`已将整首谱子${semitones > 0 ? "升高" : "降低"}半音。`, true);
}

function setEditJianpuModifier(button) {
  const modifier = button.dataset.editJianpuModifier;
  if (!modifier) return;
  editJianpuModifierState[modifier] = button.dataset.value || "";
  document.querySelectorAll(`[data-edit-jianpu-modifier="${modifier}"]`).forEach((choice) => {
    choice.setAttribute("aria-checked", String(choice === button));
  });
}

function resetEditJianpuModifiers() {
  Object.keys(editJianpuModifierState).forEach((modifier) => { editJianpuModifierState[modifier] = ""; });
  document.querySelectorAll("[data-edit-jianpu-modifier]").forEach((button) => {
    button.setAttribute("aria-checked", String(button.dataset.value === ""));
  });
}

function editJianpuTokenForKey(key, baseOctave = "") {
  if (!/^[0-7]$/.test(key)) return key;
  const { octave, duration, dot, accidental } = editJianpuModifierState;
  if (key === "0") return `0${duration}${dot}`;
  const selectedOctave = octave.startsWith(",") ? -octave.length : octave.startsWith("'") ? octave.length : 0;
  const baseLevel = baseOctave === "'" ? 1 : 0;
  const octaveLevel = selectedOctave + baseLevel;
  const lowMark = octaveLevel < 0 ? ",".repeat(-octaveLevel) : "";
  const highMark = octaveLevel > 0 ? "'".repeat(octaveLevel) : "";
  return `${accidental}${lowMark}${key}${highMark}${duration}${dot}`;
}

function insertSongEditSoftKey(key, baseOctave = "") {
  const editor = elements.songEditScore;
  const token = editJianpuTokenForKey(key, baseOctave);
  editor.setRangeText(`${token} `, editor.selectionStart, editor.selectionEnd, "end");
  updateSongEditLineNumbers();
  updateSongEditTransposeControls(parseJianpu(editor.value, Number(elements.songEditBpm.value)));
  editor.focus({ preventScroll: true });
}

function openSongEditDialog(song) {
  if (!authState.account) {
    showAuthDialog();
    return;
  }
  pendingSongEdit = { song, original: { remixCode: normalizeStoredRemixCode(song.remixCode), title: song.title, artist: song.artist } };
  trackScoreAnalytics("score_edit_opened", {}, analyticsScoreIdForSong(song), song);
  elements.songEditName.value = song.title;
  elements.songEditArtist.value = song.artist;
  elements.songEditKey.value = song.key || "1=C";
  elements.songEditMeter.value = song.meter || "4/4";
  elements.songEditBpm.value = song.bpm || 120;
  elements.songEditDisplayUrl.value = song.displayUrl || "";
  elements.songEditDeclaration.value = song.declaration || "";
  elements.songEditScore.value = String(song.sourceJianpu || song.jianpu || song.score || "");
  resetEditJianpuModifiers();
  setSongEditStatus();
  updateSongEditLineNumbers();
  updateSongEditTransposeControls(parseJianpu(elements.songEditScore.value, Number(elements.songEditBpm.value)));
  if (typeof elements.songEditDialog.showModal === "function") {
    elements.songEditDialog.showModal();
    elements.songEditName.focus();
    return;
  }
  toast("当前浏览器不支持曲目编辑窗口。 ");
}

async function saveSongEdit() {
  if (!pendingSongEdit || !authState.account) return;
  const bpm = Number(elements.songEditBpm.value);
  const sequence = parseJianpu(elements.songEditScore.value, bpm);
  if (sequence.error) {
    setSongEditStatus(`第 ${sequence.error.line} 行，第 ${sequence.error.column} 列：${sequence.error.message}`);
    return;
  }
  const uploadIssue = uploadCompatibilityIssue(sequence);
  if (uploadIssue) {
    setSongEditStatus(uploadIssue.message);
    return;
  }
  const metadata = validateScoreMetadata({
    title: elements.songEditName.value,
    artist: elements.songEditArtist.value,
    sharedBy: pendingSongEdit.song.sharedBy,
    key: elements.songEditKey.value,
    meter: elements.songEditMeter.value,
    bpm,
    displayUrl: elements.songEditDisplayUrl.value,
    declaration: elements.songEditDeclaration.value
  });
  if (metadata.error) {
    setSongEditStatus(metadata.error);
    return;
  }
  elements.songEditSave.disabled = true;
  setSongEditStatus("正在保存到我的曲库…");
  try {
    const response = await authRequest("./api/public-library/songs", {
      method: "PATCH",
      body: {
        original: pendingSongEdit.original,
        ...metadata.value,
        remixCode: normalizeStoredRemixCode(pendingSongEdit.song.remixCode),
        jianpu: sequenceToJianpu(sequence)
      }
    });
    if (!Array.isArray(response.songs)) throw new Error("服务器返回的曲库数据无效。");
    replaceCommunitySongs(response.songs);
    await loadMySongLibrary();
    const editedScoreId = analyticsScoreIdForSong(pendingSongEdit.song);
    elements.songEditDialog.close();
    trackScoreAnalytics("score_edit_saved", {}, editedScoreId, metadata.value);
    pendingSongEdit = null;
    toast(`《${metadata.value.title}》已保存。`);
  } catch (error) {
    setSongEditStatus(error.message || "保存曲目失败，请稍后重试。 ");
  } finally {
    elements.songEditSave.disabled = false;
  }
}

function openLibraryDeleteDialog(song) {
  pendingLibrarySong = song;
  elements.libraryDeleteTitle.textContent = `删除《${song.title}》`;
  elements.libraryDeleteDescription.textContent = `确定删除《${song.title}》吗？删除后无法恢复。`;
  if (typeof elements.libraryDeleteDialog.showModal === "function") elements.libraryDeleteDialog.showModal();
}

async function confirmLibraryDelete() {
  const song = pendingLibrarySong;
  if (!song) return;
  elements.libraryDeleteConfirm.disabled = true;
  try {
    const result = await authRequest("./api/public-library/songs", {
      method: "DELETE",
      body: { remixCode: normalizeStoredRemixCode(song.remixCode), title: song.title, artist: song.artist, sharedBy: song.sharedBy }
    });
    if (!Array.isArray(result.songs)) throw new Error("服务器返回的曲库数据无效。");
    pendingLibrarySong = null;
    replaceCommunitySongs(result.songs);
    await loadMySongLibrary();
    elements.libraryDeleteDialog.close();
    toast(`《${song.title}》已从我的曲库删除。`);
  } catch (error) {
    toast(error.message || "删除曲目失败，请稍后重试。 ");
  } finally {
    elements.libraryDeleteConfirm.disabled = false;
  }
}

const USER_ID_EFFECT_META = [
  { id: "default", name: "默认效果", tier: "基础", detail: "所有用户可用" },
  { id: "ice", name: "冰蓝流光", tier: "一级成就", threshold: 50, detail: "贡献达到 50 次解锁" },
  { id: "violet", name: "紫电流光", tier: "二级成就", threshold: 100, detail: "贡献达到 100 次解锁" },
  { id: "ember", name: "红橙流光", tier: "三级成就", threshold: 500, detail: "贡献达到 500 次解锁" },
  { id: "aurora", name: "青碧流光", tier: "打赏成就", detail: "进入打赏名单（收到打赏）后解锁" }
];

function userIdEffectClass(effect) {
  const value = typeof effect === "string" ? effect.trim() : "";
  if (!value || value === "default" || !/^[a-z][a-z0-9-]{1,23}$/.test(value)) return "";
  return `user-id--${value}`;
}

// 自己的特效以账号状态为准，其他人的特效来自公开榜单里的 userEffects。
function userIdEffectValue(name) {
  const trimmed = String(name ?? "").trim();
  if (!trimmed) return "default";
  if (authState.account && authState.account.userId === trimmed) return authState.account.effectState?.effect || "default";
  const remote = publicRankings.userEffects?.[trimmed];
  return typeof remote === "string" ? remote : "default";
}

function userIdMarkup(name) {
  const text = String(name ?? "");
  const className = userIdEffectClass(userIdEffectValue(text));
  return className ? `<span class="user-id ${className}">${escapeHtml(text)}</span>` : escapeHtml(text);
}

function renderIdEffectPicker() {
  const box = elements.idEffectOptions;
  if (!box) return;
  if (!authState.account) {
    box.innerHTML = '<p class="id-effect-empty">登录后可以选择用户 ID 特效。</p>';
    return;
  }
  const state = authState.account.effectState || {};
  const unlocked = new Set(Array.isArray(state.unlockedEffects) ? state.unlockedEffects : ["default"]);
  const userId = String(authState.account.userId || "");
  box.innerHTML = USER_ID_EFFECT_META.map((meta) => {
    const isUnlocked = unlocked.has(meta.id);
    const active = state.effect === meta.id;
    let detail = meta.detail;
    if (Number.isFinite(meta.threshold) && Number.isFinite(state.contributionExports)) {
      detail = `${meta.detail}（你当前 ${state.contributionExports} 次）`;
    }
    return `<button class="id-effect-option${active ? " active" : ""}${isUnlocked ? "" : " locked"}" data-id-effect="${meta.id}" type="button" aria-pressed="${active}" aria-label="${escapeHtml(`${meta.tier || "特效"}：${detail}`)}"${isUnlocked ? "" : " disabled"}>
      <span class="id-effect-sample ${userIdEffectClass(meta.id)}">@${escapeHtml(userId)}</span>
      <span class="id-effect-copy"><em class="id-effect-tier">${escapeHtml(meta.tier || "特效")}</em><small>${escapeHtml(detail)}</small></span>
      <b class="id-effect-state">${active ? "使用中" : isUnlocked ? "可使用" : "未解锁"}</b>
    </button>`;
  }).join("");
}

let effectUnlockTimer = null;

function renderEffectUnlockDialog(effects) {
  const list = elements.effectUnlockList;
  if (!list) return;
  const userId = String(authState.account?.userId || "");
  list.innerHTML = effects
    .map((id) => USER_ID_EFFECT_META.find((meta) => meta.id === id))
    .filter(Boolean)
    .map((meta) => `<div class="effect-unlock-row"><span class="id-effect-sample ${userIdEffectClass(meta.id)}">@${escapeHtml(userId)}</span><span class="effect-unlock-copy"><small>${escapeHtml(meta.detail)}</small></span><b class="effect-unlock-tier">${escapeHtml(meta.tier || "解锁")}</b></div>`)
    .join("");
}

// 首次解锁弹一次；展示过就回执给服务端记档，之后不再提示。
function scheduleEffectUnlockNotice() {
  window.clearTimeout(effectUnlockTimer);
  const dialog = elements.effectUnlockDialog;
  if (!dialog) return;
  const pending = Array.isArray(authState.account?.effectState?.pendingUnlocks) ? authState.account.effectState.pendingUnlocks : [];
  if (!pending.length || dialog.open) return;
  const blockers = [...document.querySelectorAll("dialog[open]")].filter((node) => node !== dialog && !node.classList.contains("toast"));
  if (blockers.length) {
    effectUnlockTimer = window.setTimeout(scheduleEffectUnlockNotice, 400);
    return;
  }
  renderEffectUnlockDialog(pending);
  if (elements.effectUnlockTitle) {
    elements.effectUnlockTitle.textContent = pending.length > 1
      ? `解锁了 ${pending.length} 个新 ID 特效`
      : "解锁了新的 ID 特效";
  }
  dialog.showModal();
  if (authState.account?.effectState) authState.account.effectState.pendingUnlocks = [];
  authRequest("./api/auth/effect-notice", { method: "POST", body: { effects: pending } }).catch(() => {});
}

function setSignedInAccount(account) {
  authState.account = account || null;
  elements.accountButton.hidden = !authState.available;
  elements.accountButton.classList.toggle("is-signed-in", Boolean(account));
  elements.accountButtonLabel.innerHTML = account ? `@${userIdMarkup(account.userId)}` : "登录 / 注册";
  if (!account) mySongLibrary = [];
  if (account) {
    elements.accountEmail.textContent = account.email;
    elements.accountUserId.value = account.userId;
  }
  renderPointsUi();
  renderSongLibrary(elements.songSearch.value);
  renderSupportNotePreview();
  renderIdEffectPicker();
  schedulePointsNotice();
  scheduleEffectUnlockNotice();
}

let pointsNoticeTimer = null;

function schedulePointsNotice() {
  window.clearTimeout(pointsNoticeTimer);
  const dialog = document.querySelector("#pointsNoticeDialog");
  if (!dialog || !authState.account?.points?.noticePending || dialog.open) return;
  const blockers = [...document.querySelectorAll("dialog[open]")].filter((node) => node !== dialog && !node.classList.contains("toast"));
  if (blockers.length) {
    pointsNoticeTimer = window.setTimeout(schedulePointsNotice, 400);
    return;
  }
  dialog.showModal();
}

document.querySelector("#pointsNoticeConfirm").addEventListener("click", () => document.querySelector("#pointsNoticeDialog").close());
document.querySelector("#pointsNoticeDialog").addEventListener("close", () => {
  if (!authState.account?.points?.noticePending) return;
  authState.account.points.noticePending = false;
  authRequest("./api/points/notice", { method: "POST", body: {} }).catch(() => {});
  scheduleEffectUnlockNotice();
  flushPendingPointsTask();
});

const POINT_REASON_LABELS = { register: "注册奖励", legacy_grant: "版本更新补偿", legacy_export: "历史导出结算", daily_login: "每日登录", github_star: "GitHub Star", first_upload: "首次投稿", referral: "邀请好友", author: "作品被使用", unlock: "解锁曲谱" };

// 只有能帮用户看懂来源的参考信息才展示；注册/投稿/邀请的参考值是内部账号 ID，
// 既不直观也不该暴露，所以不显示。
const POINT_REFERENCE_NOTES = {
  daily_login: (reference) => (reference ? `日期 ${reference}` : ""),
  github_star: (reference) => (reference ? `GitHub ID ${reference}` : ""),
  unlock: (reference) => (reference ? `曲谱 ${reference}` : ""),
  // 作者收益的参考值是「解锁者账号 ID : 曲谱标识」，只展示曲谱，不暴露解锁者内部 ID。
  author: (reference) => { const code = String(reference || "").split(":").pop(); return code ? `曲谱 ${code}` : ""; },
};

function renderPointsLedger(entries = []) {
  if (!elements.pointsLedgerPanel || !elements.pointsLedgerList) return;
  elements.pointsLedgerPanel.hidden = !authState.account;
  if (!authState.account) return;
  if (!entries.length) { elements.pointsLedgerList.innerHTML = '<span class="points-ledger-empty">暂无积分记录</span>'; return; }
  elements.pointsLedgerList.innerHTML = entries.map(entry => {
    const amount = Number(entry.amount) || 0;
    const label = POINT_REASON_LABELS[entry.reason] || entry.reason || "积分变动";
    const date = new Date((Number(entry.created_at) || 0) * 1000);
    const when = Number.isNaN(date.getTime()) ? "" : date.toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });
    const note = POINT_REFERENCE_NOTES[entry.reason]?.(String(entry.reference ?? "")) || "";
    const meta = [when, note].filter(Boolean).join(" · ");
    return `<div class="points-ledger-entry"><span><b>${escapeHtml(label)}</b><small>${escapeHtml(meta)}</small></span><strong class="${amount >= 0 ? "positive" : "negative"}">${amount >= 0 ? "+" : ""}${amount}</strong></div>`;
  }).join("");
}

async function refreshPointsLedger() {
  if (!authState.account) { renderPointsLedger([]); return; }
  try { const result = await authRequest("./api/points/ledger"); renderPointsLedger(result.entries || []); } catch { renderPointsLedger([]); }
}

function renderPointsUi() {
  const points = authState.account?.points;
  const signedIn = Boolean(authState.account);
  const inviteCode = authState.account?.inviteCode || points?.inviteCode || "";
  elements.pointsTaskButton.hidden = !authState.available;
  elements.pointsTaskButtonLabel.textContent = !signedIn ? "登录领 30 分" : points?.unlimited ? "∞" : `${points?.balance ?? 0} 积分`;
  elements.pointsTaskButton.title = signedIn ? "查看积分任务" : "登录或注册领取 30 积分";
  elements.pointsTaskBalance.textContent = !signedIn ? "登录领 30" : points?.unlimited ? "∞" : `${points?.balance ?? 0} 积分`;
  elements.pointsTaskRegistration.textContent = signedIn ? "已领取注册奖励 +30" : "完成注册后领取 +30";
  elements.pointsTaskDailyLogin.textContent = signedIn && points?.dailyLoginRewarded ? "今日已领取 +20" : "每天首次登录领取 +20";
  elements.pointsTaskDailyLoginStatus.textContent = signedIn && points?.dailyLoginRewarded ? "今日已领取" : signedIn ? "登录奖励处理中" : "登录后自动领取";
  elements.pointsTaskGithub.textContent = points?.githubStarRewarded ? "已验证 Star，已领取 +500" : "验证项目 Star 后领取 +500";
  elements.pointsTaskUpload.textContent = points?.firstUploadRewarded ? "已领取首次投稿奖励 +50" : "成功发布一首谱子后领取 +50";
  const authorReward = points?.rules?.author_reward ?? 1;
  elements.pointsTaskAuthor.textContent = signedIn
    ? `已累计 ${points?.authorUnlocks || 0} 次有效解锁，每次 +${authorReward}`
    : `每次有效解锁 +${authorReward}`;

  elements.inviteCodeDisplay.textContent = signedIn ? (inviteCode || "生成中…") : "登录后显示";
  elements.copyInviteCodeButton.disabled = false;
  elements.copyInviteLinkButton.disabled = false;

  const githubReady = Boolean(points?.githubStarAvailable);
  elements.githubStarVerifyButton.disabled = signedIn && (!githubReady || Boolean(points?.githubStarRewarded));
  elements.githubStarVerifyButton.textContent = !signedIn
    ? "登录后验证 Star · +500"
    : points?.githubStarRewarded
      ? "已验证 Star · +500"
      : githubReady
        ? "验证 Star · 领取 500 积分"
        : "Star 验证暂不可用";
  elements.githubStarVerifyButton.title = !signedIn ? "登录后即可验证 GitHub Star" : githubReady ? "通过 GitHub 授权验证 Star" : "当前站点尚未配置 GitHub Star 验证";
}

async function refreshPointsUi() {
  if (!authState.account) { renderPointsUi(); return; }
  try { authState.account.points = await authRequest("./api/points"); } catch {}
  renderPointsUi();
}

function inviteLinkForCurrentAccount() {
  const link = new URL(window.location.pathname, window.location.origin);
  const inviteCode = authState.account?.inviteCode || authState.account?.points?.inviteCode || "";
  if (inviteCode) link.searchParams.set("ref", inviteCode);
  return link.href;
}

function flashTaskTarget(target) {
  target.classList.remove("task-target");
  void target.offsetWidth;
  target.classList.add("task-target");
  window.setTimeout(() => target.classList.remove("task-target"), 1800);
}

function navigateToPointsTask(task) {
  const targetMap = { github: elements.githubStarVerifyButton, invite: elements.inviteFriends, upload: elements.editorPanel, support: document.querySelector("#supportAuthor") };
  const target = targetMap[task];
  if (!target) return;
  elements.pointsTaskDialog.close();
  target.scrollIntoView({ behavior: "smooth", block: "center" });
  flashTaskTarget(target);
  window.setTimeout(() => target.focus?.({ preventScroll: true }), 500);
}

function flushPendingPointsTask() {
  const task = authState.pendingPointsTask;
  if (!task || !authState.account) return;
  const pointsNotice = document.querySelector("#pointsNoticeDialog");
  if (authState.account.points?.noticePending && !pointsNotice?.open) {
    window.setTimeout(flushPendingPointsTask, 250);
    return;
  }
  if (elements.authDialog.open || pointsNotice?.open) {
    window.setTimeout(flushPendingPointsTask, 250);
    return;
  }
  authState.pendingPointsTask = "";
  navigateToPointsTask(task);
}

function requirePointsTaskLogin(task, { register = false } = {}) {
  if (authState.account) return false;
  authState.pendingPointsTask = task;
  if (elements.pointsTaskDialog.open) elements.pointsTaskDialog.close();
  showAuthDialog();
  if (register) {
    setAuthMode("register", { focus: true });
  }
  return true;
}

function authFieldsForMode(mode = authState.mode) {
  return mode === "register"
    ? { email: elements.authRegisterEmail, code: elements.authRegisterCode, note: elements.authRegisterEmailNote, request: elements.authRegisterRequestCode }
    : { email: elements.authEmail, code: elements.authCode, note: elements.authEmailNote, request: elements.authRequestCode };
}

function setAuthMode(mode, { focus = false } = {}) {
  const selectedMode = mode === "register" ? "register" : "login";
  authState.mode = selectedMode;
  elements.authModeTabs.forEach((tab) => {
    const selected = tab.dataset.authMode === selectedMode;
    tab.setAttribute("aria-selected", String(selected));
    tab.tabIndex = selected ? 0 : -1;
  });
  elements.authLoginPanel.hidden = selectedMode !== "login";
  elements.authRegisterPanel.hidden = selectedMode !== "register";
  elements.authLoginPanel.querySelectorAll("input, button").forEach((field) => { field.disabled = selectedMode !== "login"; });
  elements.authRegisterPanel.querySelectorAll("input, button").forEach((field) => { field.disabled = selectedMode !== "register"; });
  elements.authTitle.textContent = selectedMode === "login" ? "登录" : "注册";
  elements.authDescription.textContent = selectedMode === "login"
    ? "使用已注册邮箱接收验证码并登录。"
    : "创建一个用户 ID，再使用邮箱验证码完成注册。";
  setAuthStatus(elements.authStatus);
  if (focus) authFieldsForMode(selectedMode).email.focus();
}

function resetAuthDialog() {
  stopAuthMailWatch();
  setAuthStatus(elements.authStatus);
  authState.email = "";
  ["login", "register"].forEach((mode) => {
    const fields = authFieldsForMode(mode);
    fields.email.value = "";
    fields.email.disabled = false;
    fields.code.value = "";
    fields.note.hidden = true;
    fields.note.textContent = "";
    fields.note.classList.remove("error");
  });
  elements.authUserId.value = "";
}

function showAuthDialog({ reason = "" } = {}) {
  resetAuthDialog();
  setAuthMode("login");
  if (reason === "anonymous-export-limit") {
    elements.authDescription.textContent = "匿名导出次数已用完，请注册或登录后继续使用宏导出。";
  }
  if (typeof elements.authDialog.showModal === "function") elements.authDialog.showModal();
  else toast(reason === "anonymous-export-limit" ? "请注册或登录后继续导出宏。 " : "请输入邮箱以登录后上传曲谱。 ");
  elements.authEmail.focus();
}

function stopAuthMailWatch() {
  if (!authMailWatch) return;
  clearTimeout(authMailWatch.timer);
  authMailWatch = null;
}

function authMailNoteText(status, email) {
  switch (status.state) {
    case "pending":
      return status.position > 1
        ? `验证码邮件排队中：前面还有 ${status.position - 1} 封待发送。`
        : `验证码邮件已进入发送队列，正在发送至 ${email}…`;
    case "sending":
      return `验证码邮件正在发送至 ${email}…`;
    case "sent":
      return `验证码邮件已发送至 ${email}，请查收（也请留意垃圾邮件箱）。`;
    case "failed":
      return "验证码邮件发送失败，请稍后重新发送。";
    case "expired":
      return "验证码邮件状态已失效，请重新发送。";
    case "timeout":
      return "验证码邮件仍在发送中，请稍后查收；长时间未收到可重新发送。";
    default:
      return `验证码正在发送至 ${email}…`;
  }
}

function renderAuthMailNote(status) {
  if (!authMailWatch) return;
  const { note, email } = authMailWatch;
  note.textContent = authMailNoteText(status, email);
  note.classList.toggle("error", status.state === "failed" || status.state === "expired");
  note.hidden = false;
}

async function pollAuthMailStatus(ticket) {
  if (!authMailWatch || authMailWatch.ticket !== ticket) return;
  let status = null;
  try {
    status = await authRequest(`./api/auth/mail-status?ticket=${encodeURIComponent(ticket)}`);
  } catch {
    status = null; // 状态查询失败不应该打断发送流程，下一轮继续尝试。
  }
  if (!authMailWatch || authMailWatch.ticket !== ticket) return;
  if (status) renderAuthMailNote(status);
  if (status && ["sent", "failed", "expired"].includes(status.state)) {
    if (status.state !== "sent") authMailWatch.fields.email.disabled = false;
    stopAuthMailWatch();
    return;
  }
  if (Date.now() >= authMailWatch.deadline) {
    renderAuthMailNote({ state: "timeout" });
    stopAuthMailWatch();
    return;
  }
  authMailWatch.timer = setTimeout(() => pollAuthMailStatus(ticket), AUTH_MAIL_WATCH_INTERVAL_MS);
}

function watchAuthMailDelivery(result, fields, email) {
  stopAuthMailWatch();
  if (!result || !result.ticket) return;
  authMailWatch = { ticket: result.ticket, fields, email, note: fields.note, timer: 0, deadline: Date.now() + AUTH_MAIL_WATCH_TIMEOUT_MS };
  renderAuthMailNote(result);
  authMailWatch.timer = setTimeout(() => pollAuthMailStatus(result.ticket), AUTH_MAIL_WATCH_INTERVAL_MS);
}

async function requestLoginCode() {
  const fields = authFieldsForMode();
  const email = fields.email.value.trim();
  if (!email) { setAuthStatus(elements.authStatus, "请先填写邮箱地址。 "); return; }
  fields.request.disabled = true;
  stopAuthMailWatch();
  setAuthStatus(elements.authStatus, "正在发送验证码…", true);
  try {
    const result = await authRequest("./api/auth/request-code", { method: "POST", body: { email, mode: authState.mode } });
    authState.email = email;
    setAuthStatus(elements.authStatus);
    fields.email.disabled = true;
    fields.note.textContent = `验证码已发送至 ${authState.email}。`;
    fields.note.hidden = false;
    fields.code.focus();
    watchAuthMailDelivery(result, fields, email);
  } catch (error) {
    setAuthStatus(elements.authStatus, error.message || "验证码发送失败。 ");
  } finally {
    fields.request.disabled = false;
  }
}

async function verifyLoginCode() {
  const fields = authFieldsForMode();
  const code = fields.code.value.trim();
  if (!/^\d{6}$/.test(code)) { setAuthStatus(elements.authStatus, "请输入 6 位验证码。 "); return; }
  const email = authState.email || fields.email.value.trim();
  if (!email) { setAuthStatus(elements.authStatus, "请先填写邮箱地址。 "); return; }
  authState.email = email;
  const userId = authState.mode === "register" ? elements.authUserId.value.trim() : "";
  if (authState.mode === "register" && !userId) { setAuthStatus(elements.authStatus, "请填写用户 ID。 "); return; }
  const verifyButton = authState.mode === "register" ? elements.authVerifyRegister : elements.authVerifyLogin;
  verifyButton.disabled = true;
  setAuthStatus(elements.authStatus, "正在验证邮箱…", true);
  try {
    const result = await authRequest("./api/auth/verify", { method: "POST", body: { email: authState.email, code, userId, mode: authState.mode, referral: document.querySelector("#authReferral")?.value.trim() || "" } });
    setSignedInAccount(result.account);
    await loadMySongLibrary();
    elements.authDialog.close();
    toast(`已登录为 @${result.account.userId}。`);
    if (authState.pendingCommunityUpload) {
      authState.pendingCommunityUpload = false;
      openScoreExportDialog("community-upload");
    }
    flushPendingPointsTask();
  } catch (error) {
    setAuthStatus(elements.authStatus, error.message || "登录失败。 ");
  } finally {
    verifyButton.disabled = false;
  }
}

