async function saveScoreToLocalLibrary() {
  const packaged = await scorePackageFromDialog();
  if (packaged.error) { toast(packaged.error); return; }
  elements.confirmScoreExport.disabled = true;
  try {
    const response = await fetch("./api/local-library/songs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...packaged.value, ...(currentScoreEditMode ? { replaceExisting: true } : {}) })
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || "写入本地曲库失败。");
    if (!Array.isArray(result.songs)) throw new Error("本地服务返回的曲库数据无效。");
    const savedSong = findSavedScore(result.songs, packaged.value);
    applyScorePackageMetadata(savedSong || packaged.value);
    replaceCommunitySongs(result.songs);
    elements.scoreExportDialog.close();
    toast(`《${packaged.value.title}》已${result.action === "updated" ? "更新" : "收录"}到本地工作区，待手动提交。`);
  } catch (error) {
    toast(error.message || "写入本地曲库失败。");
  } finally {
    elements.confirmScoreExport.disabled = false;
  }
}

async function uploadScoreToCommunityLibrary({ confirmReplace = false, packagedOverride = null } = {}) {
  const packaged = packagedOverride ? { value: packagedOverride } : await scorePackageFromDialog();
  if (packaged.error) { toast(packaged.error); return; }
  elements.confirmScoreExport.disabled = true;
  try {
    const response = await fetch("./api/public-library/songs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...packaged.value, ...(currentScoreEditMode ? { replaceExisting: true } : {}), ...(confirmReplace ? { confirmReplace: true } : {}) })
    });
    const result = await response.json().catch(() => ({}));
    if (response.status === 409 && result.code === "owned_duplicate" && !confirmReplace) {
      pendingCommunityOverwrite = packaged.value;
      elements.libraryOverwriteTitle.textContent = `确认覆盖《${packaged.value.title}》`;
      elements.libraryOverwriteDescription.textContent = `当前账号已经上传过《${packaged.value.title}》，确认用现在的内容覆盖原曲吗？`;
      elements.libraryOverwriteDialog.showModal();
      return;
    }
    if (!response.ok) throw new Error(result.error || "上传到曲库失败，请稍后重试。");
    if (authState.account) {
      try { authState.account.points = await authRequest("./api/points"); renderPointsUi(); } catch {}
    }
    if (!Array.isArray(result.songs)) throw new Error("服务器返回的曲库数据无效。");
    const savedSong = findSavedScore(result.songs, packaged.value);
    applyScorePackageMetadata(savedSong || packaged.value);
    replaceCommunitySongs(result.songs);
    await loadMySongLibrary();
    elements.scoreExportDialog.close();
    trackScoreAnalytics("community_upload_succeeded");
    toast(`《${packaged.value.title}》已${result.action === "updated" ? "更新" : "上传"}到公共曲库。`);
  } catch (error) {
    toast(error.message || "上传到曲库失败，请稍后重试。");
  } finally {
    elements.confirmScoreExport.disabled = false;
  }
}

