function softwareLogoMarkup(brandId) {
  const brand = EXPORT_BRANDS[brandId];
  if (!brand) return "";
  const label = `${brand.label} ${brand.small}`.trim();
  let icon = "";
  if (brand.type === "recorder") {
    icon = '<svg class="software-logo-icon" viewBox="0 0 28 24" aria-hidden="true" focusable="false"><circle cx="14" cy="12" r="4.5" /><path d="M6.5 12a7.5 7.5 0 0 0 7.5 7.5M21.5 12a7.5 7.5 0 0 1-7.5 7.5M6.5 12A7.5 7.5 0 0 1 14 4.5M21.5 12A7.5 7.5 0 0 0 14 4.5" /></svg>';
  } else if (brand.type === "mask") {
    icon = `<span class="software-logo-image software-logo-image--${brandId}"><span class="software-logo-mask software-logo-mask--${brandId}" aria-hidden="true"></span></span>`;
  } else if (brandId === "razer") {
    icon = '<span class="software-logo-image software-logo-image--razer"><span class="software-logo-icon software-logo-icon--razer" aria-hidden="true"></span></span>';
  } else {
    icon = `<span class="software-logo-image software-logo-image--${brandId}"><img src="${brand.src}" alt="" /></span>`;
  }
  return `<span class="software-logo software-logo--export ${brand.className}" aria-label="${label}">${icon}<span><strong>${brand.label}</strong><small>${brand.small}</small></span></span>`;
}

function normalizeExportMethodConfig(payload) {
  const methods = Array.isArray(payload?.methods) ? payload.methods : [];
  const byId = new Map(methods.map((method) => [method?.id, method]));
  return {
    methods: EXPORT_METHOD_IDS.map((id) => {
      const candidate = byId.get(id);
      const brandIds = Array.isArray(candidate?.brandIds)
        ? candidate.brandIds.filter((brandId) => Boolean(EXPORT_BRANDS[brandId]))
        : [];
      return { id, brandIds: brandIds.length ? [...new Set(brandIds)] : [...DEFAULT_EXPORT_METHOD_BRANDS[id]] };
    })
  };
}

function renderExportBrandFilter() {
  if (!elements.exportBrandFilter) return;
  const filterItems = [
    { id: "all", label: "全部", small: "ALL" },
    ...EXPORT_BRAND_FILTER_IDS.map((brandId) => ({ id: brandId, label: EXPORT_BRANDS[brandId].label, small: EXPORT_BRANDS[brandId].small }))
  ];
  elements.exportBrandFilter.innerHTML = filterItems.map(({ id, label, small }) => (
    `<button class="export-brand-filter-button" type="button" role="tab" data-export-brand-filter="${id}" aria-selected="false"><span>${label}</span><small>${small}</small></button>`
  )).join("");
  elements.exportBrandFilter.querySelectorAll("[data-export-brand-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      selectedExportBrand = button.dataset.exportBrandFilter || "all";
      applyExportBrandFilter();
    });
  });
}

function applyExportBrandFilter() {
  const brandIdsByMethod = new Map(exportMethodConfig.methods.map((method) => [method.id, method.brandIds]));
  let visibleCount = 0;
  document.querySelectorAll("[data-export-method]").forEach((card) => {
    const brandIds = brandIdsByMethod.get(card.dataset.exportMethod) || [];
    const isVisible = selectedExportBrand === "all" || brandIds.includes(selectedExportBrand);
    card.hidden = !isVisible;
    card.classList.toggle("is-export-filtered", !isVisible);
    if (isVisible) visibleCount += 1;
  });
  elements.exportBrandFilter?.querySelectorAll("[data-export-brand-filter]").forEach((button) => {
    const isSelected = button.dataset.exportBrandFilter === selectedExportBrand;
    button.setAttribute("aria-selected", String(isSelected));
  });
  if (elements.exportBrandFilterHint) {
    const label = selectedExportBrand === "all" ? "全部品牌" : EXPORT_BRANDS[selectedExportBrand]?.label || "当前品牌";
    elements.exportBrandFilterHint.textContent = selectedExportBrand === "all"
      ? `显示全部 ${visibleCount} 种导出方式`
      : `显示支持 ${label} 的 ${visibleCount} 种导出方式`;
  }
}

function applyExportMethodConfig(payload = exportMethodConfig) {
  exportMethodConfig = normalizeExportMethodConfig(payload);
  renderExportBrandFilter();
  const brandIdsByMethod = new Map(exportMethodConfig.methods.map((method) => [method.id, method.brandIds]));
  elements.exportBrandTargets.forEach((target) => {
    const brandIds = brandIdsByMethod.get(target.closest("[data-export-method]")?.dataset.exportMethod) || [];
    target.innerHTML = brandIds.map(softwareLogoMarkup).join("");
    target.hidden = !brandIds.length;
  });
  applyExportBrandFilter();
}

