function handleSongCardClick(event) {
  if (event.target.closest("[data-library-login]")) {
    showAuthDialog();
    return;
  }
  if (event.target.closest("[data-library-upload]")) {
    elements.uploadScoreButton.click();
    return;
  }
  const actionButton = event.target.closest("[data-song-action]");
  const card = event.target.closest("[data-song-index]");
  if (!card || event.target.closest("a")) return;
  const remixCode = card.dataset.remixCode;
  const song = remixCode ? remixCodeSong(remixCode) : SONG_LIBRARY[Number(card.dataset.songIndex)];
  if (!song) return;
  if (actionButton?.dataset.songAction === "copy-remix-code") {
    void copyRemixCodeLink(actionButton.dataset.remixCode);
    return;
  }
  if (actionButton?.dataset.songAction === "search-artist") {
    openLibrarySearch(actionButton.dataset.artist);
    return;
  }
  if (actionButton?.dataset.songAction === "search-sharer") {
    openLibrarySearch(song.sharedBy);
    return;
  }
  if (actionButton?.dataset.songAction === "preview") {
    void toggleSongPreview(song);
    return;
  }
  if (actionButton?.dataset.songAction === "search-sponsor") {
    openLibrarySearch(song.sponsor);
    return;
  }
  if (!actionButton || actionButton.dataset.songAction === "card-export-copy-remix") {
    loadSong(song, { destination: "export" });
    void copyRemixCodeLink(song.remixCode);
    return;
  }
  if (["recommend", "unrecommend"].includes(actionButton.dataset.songAction)) {
    updateSongRecommendation(song, actionButton.dataset.songAction === "recommend", actionButton);
    return;
  }
  if (actionButton.dataset.songAction === "delete") {
    openLibraryDeleteDialog(song);
    return;
  }
  if (actionButton.dataset.songAction === "edit") {
    openSongEditDialog(song);
    return;
  }
  const destination = actionButton.dataset.songAction === "export" ? "export" : "editor";
  loadSong(song, { destination });
  if (destination === "export") completeTourAction("library-export", "曲目已载入，正在打开导出区。");
}
